238: 
239:     for (let y = 0; y < MAP_HEIGHT; y++) {
240:       for (let x = 0; x < MAP_WIDTH; x++) {
241:         const t = this.map.getTile(x, y);
242:         let c = '#4bb340';
243:         if (t === TILE.DEEP_WATER) c = '#0c4a6e';
244:         else if (t === TILE.WATER) c = '#0284c7';
245:         else if (t === TILE.SAND) c = '#fcd34d';
246:         else if (t === TILE.ROAD || t === TILE.BRIDGE) c = '#f59e0b';
247:         else if (t === TILE.CYCLING_ROAD) c = '#94a3b8';
248:         else if (t === TILE.PAVED || t === TILE.PLAZA) c = '#e2e8f0';
249:         else if (t === TILE.TREE || t === TILE.FOREST_TREE) c = '#15803d';
250:         else if (t === TILE.MOUNTAIN) c = '#78350f';
251:         else if (t === TILE.ROOF_RED || t === TILE.ROOF_GOLD || t === TILE.ROOF_BLUE) c = '#ef4444';
252:         mctx.fillStyle = c;
253:         mctx.fillRect(x, y, 1, 1);
254:       }
255:     }
256:   }
