258:   update(dt, timeMs) {
259:     // Update particles
260:     for (let i = this.particles.length - 1; i >= 0; i--) {
261:       const p = this.particles[i];
262:       p.life -= dt;
263:       p.x += p.vx * dt;
264:       p.y += p.vy * dt;
265:       if (p.life <= 0) this.particles.splice(i, 1);
266:     }
267: 
268:     if (this.grassCooldown > 0) this.grassCooldown -= dt;
269:     if (this.healCooldown > 0) this.healCooldown -= dt;
270: 
271:     // Ledge hop animation timer
272:     if (this.player.jumpTimer > 0) {
273:       this.player.jumpTimer = Math.max(0, this.player.jumpTimer - dt);
274:       const progress = 1 - this.player.jumpTimer / 0.28;
275:       this.player.jumpHeight = Math.sin(progress * Math.PI) * 14;
276:       this.player.y += dt * 6.5;
277:       this.camera.x = this.player.x;
278:       this.camera.y = this.player.y;
279:       return;
280:     } else {
281:       this.player.jumpHeight = 0;
282:     }
283: 
284:     // Read Joypad state
285:     const pad = this.joypad.getState();
286: 
287:     if (pad.active) {
288:       this.player.isMoving = true;
289:       if (pad.dir) this.player.dir = pad.dir;
290: 
291:       // Determine current terrain mode & movement speed (in tiles per second)
292:       const curTile = this.map.getTile(Math.floor(this.player.x), Math.floor(this.player.y));
293:       if (curTile === TILE.WATER) {
294:         this.player.mode = 'surf';
295:       } else if (this.player.bikeActive || curTile === TILE.CYCLING_ROAD) {
296:         this.player.mode = 'bike';
297:       } else if (pad.isRunning) {
298:         this.player.mode = 'run';
299:       } else {
300:         this.player.mode = 'walk';
301:       }
302: 
303:       const baseSpeed =
304:         this.player.mode === 'bike'
305:           ? 9.2
306:           : this.player.mode === 'surf'
307:           ? 7.2
308:           : this.player.mode === 'run'
309:           ? 6.8
310:           : 4.5;
311: 
312:       const speed = baseSpeed * Math.max(0.55, pad.magnitude);
313:       const moveX = pad.vx * speed * dt;
314:       const moveY = pad.vy * speed * dt;
315: 
316:       this.movePlayerWithSlide(moveX, moveY);
317:       this.player.walkCycle += dt * (speed * 0.28);
318:       this.audio.playStep(this.player.mode);
319:     } else {
320:       this.player.isMoving = false;
321:       const curTile = this.map.getTile(Math.floor(this.player.x), Math.floor(this.player.y));
322:       if (curTile === TILE.WATER) this.player.mode = 'surf';
323:       else if (this.player.bikeActive) this.player.mode = 'bike';
324:       else this.player.mode = 'walk';
325:     }
326: 
327:     // Smooth camera follow
328:     const lerp = Math.min(1, dt * 12);
329:     this.camera.x += (this.player.x - this.camera.x) * lerp;
330:     this.camera.y += (this.player.y - this.camera.y) * lerp;
331: 
332:     // Check current tile triggers (Region transitions, Tall Grass encounters, Pokémon Center Heal Pad)
333:     const tx = Math.floor(this.player.x);
334:     const ty = Math.floor(this.player.y);
335:     this.checkTileTriggers(tx, ty);
336:   }
337: 
338:   canOccupy(x, y) {
339:     const r = 0.28; // Player collision radius in tiles
340:     const points = [
341:       [x - r, y - r],
342:       [x + r, y - r],
343:       [x - r, y + r],
344:       [x + r, y + r],
345:     ];
346:     for (const [px, py] of points) {
347:       const tx = Math.floor(px);
348:       const ty = Math.floor(py);
349:       if (this.map.isSolid(tx, ty)) return false;
350:       if (this.map.isLedge(tx, ty)) return false;
351:       // Check NPC collision
352:       for (const npc of NPCS) {
353:         if (tx === npc.x && ty === npc.y) return false;
354:       }
355:     }
356:     return true;
357:   }
358: 
359:   movePlayerWithSlide(dx, dy) {
360:     const startX = this.player.x;
361:     const startY = this.player.y;
362: 
363:     // Check if pushing downward into a one-way cliff ledge!
364:     if (dy > 0.01 && Math.abs(dy) >= Math.abs(dx)) {
365:       const targetTileX = Math.floor(this.player.x);
366:       const ledgeTileY = Math.floor(this.player.y + 0.55);
367:       if (
368:         this.map.isLedge(targetTileX, ledgeTileY) &&
369:         !this.map.isSolid(targetTileX, ledgeTileY + 1)
370:       ) {
371:         this.player.dir = 'down';
372:         this.player.jumpTimer = 0.28;
373:         this.audio.playLedgeHop();
374:         this.spawnLeafParticles(this.player.x, this.player.y + 1, '#d97706');
375:         return;
376:       }
377:     }
378: 
379:     // Try X movement
380:     if (dx !== 0) {
381:       if (this.canOccupy(this.player.x + dx, this.player.y)) {
382:         this.player.x += dx;
383:       } else {
384:         // Corner assist slide along Y if blocked on X corner
385:         const slideStep = Math.abs(dx) * 0.65;
386:         if (this.canOccupy(this.player.x + dx, this.player.y - slideStep)) {
387:           this.player.y -= slideStep;
388:         } else if (this.canOccupy(this.player.x + dx, this.player.y + slideStep)) {
389:           this.player.y += slideStep;
390:         }
391:       }
392:     }
393: 
394:     // Try Y movement
395:     if (dy !== 0) {
396:       if (this.canOccupy(this.player.x, this.player.y + dy)) {
397:         this.player.y += dy;
398:       } else {
399:         // Corner assist slide along X if blocked on Y corner
400:         const slideStep = Math.abs(dy) * 0.65;
401:         if (this.canOccupy(this.player.x - slideStep, this.player.y + dy)) {
402:           this.player.x -= slideStep;
403:         } else if (this.canOccupy(this.player.x + slideStep, this.player.y + dy)) {
404:           this.player.x += slideStep;
405:         }
406:       }
407:     }
408: 
409:     const distMoved = Math.hypot(this.player.x - startX, this.player.y - startY);
410:     this.player.stepsTaken += distMoved;
411:   }
412: 
413:   checkTileTriggers(tx, ty) {
414:     // 1. Region transition check
415:     const region = this.map.getRegionAt(tx, ty);
416:     if (region.id !== this.currentRegion.id) {
417:       this.currentRegion = region;
418:       this.discoveredRegions.add(region.id);
419:       this.showBanner(region.name, region.subtitle, region.color);
420:       this.updateHUD();
421:     }
422: 
423:     // 2. Waypoint arrival check
424:     if (this.waypoint && Math.hypot(tx - this.waypoint.x, ty - this.waypoint.y) < 3.2) {
425:       this.showToast(`📍 Arrived at destination: ${this.waypoint.name}!`);
426:       this.audio.playBlip(784, 0.08);
427:       this.waypoint = null;
428:       this.updateHUD();
429:     }
430: 
431:     // 3. Pokémon Center Healing Pad
432:     if (this.map.getTile(tx, ty) === TILE.HEAL_PAD && this.healCooldown <= 0) {
433:       this.healCooldown = 5.0;
434:       this.audio.playHealJingle();
435:       this.spawnLeafParticles(this.player.x, this.player.y, '#f43f5e');
436:       this.showToast('💖 Pokémon Center: Your Pokémon team has been restored to full health!');
437:     }
438: 
439:     // 4. Tall Grass rustle & Wild Kanto Pokémon Sighting
440:     if (this.map.isTallGrass(tx, ty) && this.player.isMoving && this.grassCooldown <= 0) {
441:       this.grassCooldown = 1.6;
442:       this.spawnLeafParticles(tx + 0.5, ty + 0.5, '#22c55e');
443:       const pool = this.currentRegion.pokemon || ['Pidgey', 'Pikachu', 'Eevee', 'Bulbasaur', 'Charmander', 'Squirtle'];
444:       const wild = pool[Math.floor(Math.random() * pool.length)];
445:       const isNew = !this.sightedPokemon.has(wild);
446:       this.sightedPokemon.add(wild);
447:       if (isNew || Math.random() < 0.45) {
448:         this.audio.playBlip(659, 0.05);
449:         this.showToast(
450:           isNew
451:             ? `✨ NEW KANTO POKÉDEX SIGHTING: Wild ${wild} appeared in ${this.currentRegion.name}!`
452:             : `🌿 Wild ${wild} rustled through the tall grass in ${this.currentRegion.name}!`
453:         );
454:         this.updateHUD();
455:       }
456:     }
457:   }
458: 
459:   spawnLeafParticles(wx, wy, color = '#4ade80') {
460:     for (let i = 0; i < 8; i++) {
461:       const angle = (Math.PI * 2 * i) / 8;
462:       this.particles.push({
463:         x: wx,
464:         y: wy,
465:         vx: Math.cos(angle) * 2.2,
466:         vy: Math.sin(angle) * 2.2 - 1.0,
467:         color,
468:         life: 0.45,
469:       });
470:     }
471:   }
