473:   interactWithFacingTile() {
474:     const dirOffsets = {
475:       up: [0, -1],
476:       down: [0, 1],
477:       left: [-1, 0],
478:       right: [1, 0],
479:     };
480:     const [ox, oy] = dirOffsets[this.player.dir] || [0, 1];
481:     const ptx = Math.floor(this.player.x);
482:     const pty = Math.floor(this.player.y);
483:     const targetX = ptx + ox;
484:     const targetY = pty + oy;
485: 
486:     // 1. Check NPCs in facing tile or adjacent 1-tile radius
487:     const npc =
488:       NPCS.find((n) => n.x === targetX && n.y === targetY) ||
489:       NPCS.find((n) => Math.abs(n.x - ptx) <= 1 && Math.abs(n.y - pty) <= 1);
490: 
491:     if (npc) {
492:       if (npc.badgeId) {
493:         const badge = GYM_BADGES.find((b) => b.id === npc.badgeId);
494:         if (badge && !this.collectedBadges.has(badge.id)) {
495:           this.collectedBadges.add(badge.id);
496:           this.audio.playBadgeFanfare();
497:           this.spawnLeafParticles(npc.x + 0.5, npc.y + 0.5, '#facc15');
498:           this.openDialog(
499:             `🏅 ${npc.name} — ${badge.name.toUpperCase()} EARNED!`,
500:             `${badge.quote}\n\nYou received the ${badge.name} (${this.collectedBadges.size}/8 Kanto Gym Badges)!`
501:           );
502:           this.updateHUD();
503:           return;
504:         }
505:       }
506:       if (npc.isLegendary) {
507:         this.sightedPokemon.add(npc.name.replace('Legendary ', ''));
508:         this.audio.playBadgeFanfare();
509:         this.updateHUD();
510:       }
511:       this.audio.playBlip(587, 0.06);
512:       this.openDialog(`${npc.name} (${npc.role})`, npc.dialog);
513:       return;
514:     }
515: 
516:     // 2. Check Signs
517:     const sign =
518:       SIGNS.find((s) => s.x === targetX && s.y === targetY) ||
519:       SIGNS.find((s) => Math.abs(s.x - ptx) <= 1 && Math.abs(s.y - pty) <= 1);
520:     if (sign) {
521:       this.audio.playBlip(523, 0.05);
522:       this.openDialog(`🪧 ${sign.title}`, sign.text);
523:       return;
524:     }
525: 
526:     // 3. Check Building Doors
527:     const building = this.map.buildings.find(
528:       (b) =>
529:         (b.doorX === targetX && b.doorY === targetY) ||
530:         (Math.abs(b.doorX - ptx) <= 1 && Math.abs(b.doorY - pty) <= 1)
531:     );
532:     if (building) {
533:       if (building.type === 'pokecenter') {
534:         this.audio.playHealJingle();
535:         this.openDialog(
536:           `🏥 ${building.label}`,
537:           'Nurse Joy: “Welcome to our Pokémon Center! We’ve restored your tired Pokémon to full health. We hope to see you again!”'
538:         );
539:       } else if (building.type === 'gym') {
540:         this.audio.playBlip(660, 0.06);
541:         this.openDialog(
542:           `🏛️ ${building.label}`,
543:           `Official Pokémon League Gym in ${this.currentRegion.name}. Talk to the Gym Leader standing outside to earn this city’s Gym Badge!`
544:         );
545:       } else {
546:         this.audio.playBlip(520, 0.05);
547:         this.openDialog(
548:           `🏠 ${building.label}`,
549:           `You inspected ${building.label} in ${this.currentRegion.name}. (${this.currentRegion.description})`
550:         );
551:       }
552:       return;
553:     }
554: 
555:     // Default inspection of current area
556:     this.audio.playBlip(440, 0.04);
557:     this.showToast(`🧭 Exploring ${this.currentRegion.name} — ${this.currentRegion.subtitle}`);
558:   }
