602:   updateHUD() {
603:     const locNameEl = document.getElementById('hud-location-name');
604:     const locSubEl = document.getElementById('hud-location-sub');
605:     const coordsEl = document.getElementById('hud-coords');
606:     const badgesEl = document.getElementById('hud-badges-count');
607:     const dexEl = document.getElementById('hud-dex-count');
608:     const modeBadgeEl = document.getElementById('hud-mode-badge');
609:     const waypointEl = document.getElementById('waypoint-label');
610: 
611:     if (locNameEl) locNameEl.textContent = this.currentRegion.name;
612:     if (locSubEl) locSubEl.textContent = this.currentRegion.subtitle;
613:     if (coordsEl) {
