240:       if(game.x>=20&&tileType(game.x,game.y)==='tall'&&game.grassEncounterCooldown<=0&&Math.random()<.14){game.grassEncounterCooldown=7;beginBattle()}
241:       if(game.x>=20&&game.steps>8&&!game.quest){game.quest=true;game.message='A grassy trail! Maybe the professor knows what lives here.';showToast('You found the trail beyond town.');}
242:       if(game.x===npc.x&&game.y===npc.y){game.message='Professor Fern is right there. Press SPACE to talk!'}
