277:       if(game.hp>=game.maxHp){b.phase='enemyMsg';b.message='Voltkit is already feeling bright and bouncy!';return}
278:       game.potions--;const healed=Math.min(14,game.maxHp-game.hp);game.hp+=healed;b.phase='enemyMsg';b.message=`Voltkit munched a berry snack.  +${healed} vitality!`;updateUI();return;
279:     }
