282:       if(b.enemy.hp>b.enemy.maxHp*.58&&!b.orbTried){b.orbTried=true;b.phase='enemyMsg';b.message=`${b.enemy.name} isn't ready to be friends just yet...`;return}
283:       b.phase='enemyMsg';b.message=`You tossed a little Trail Orb toward ${b.enemy.name}...`;b.pendingCapture=true;return;
284:     }
