289:       if(game.xp>=24){game.xp-=24;game.level++;game.maxHp+=3;game.hp=Math.min(game.maxHp,game.hp+8);}
290:       b.phase='winMsg';b.message=`${b.enemy.name} bounced away. Voltkit gained a little confidence!`;game.message=b.message;updateUI();
291:     }else{b.phase='enemyMsg';b.message=`Voltkit used ${kind==='spark'?'SPARK':'TAIL WHIP'}!  ${b.enemy.name} −${damage} vitality.`;b.pendingEnemy=true;}
292:   }
293:   function battleContinue(){
