303:   function keyDown(e){
304:     const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','enter'].includes(key))e.preventDefault();
305:     if(game.keys[key])return;game.keys[key]=true;
306:     if(game.mode==='title'){if(key==='enter'||key===' '||key==='z')startJourney();return}
307:     if(game.mode==='battle'){
308:       if(game.battle?.phase==='menu'){
309:         if(key==='1'||key==='z'||key==='a')attack('spark');else if(key==='2'||key==='x'||key==='s')attack('tail');else if(key==='3')attack('snack');else if(key==='4')attack('orb');else if(key===' '||key==='enter')attack('spark');
310:       }else if(key===' '||key==='enter'||key==='z')battleContinue();return;
311:     }
