338:   canOccupy(x, y) {
339:     const r = 0.28; // Player collision radius in tiles
340:     const points = [
341:       [x - r, y - r],
342:       [x + r, y - r],
343:       [x - r, y + r],
344:       [x + r, y + r],
345:     ];
346:     for (const [px, py] of points) {
347:       const tx = Math.floor(px);
348:       const ty = Math.floor(py);
349:       if (this.map.isSolid(tx, ty)) return false;
350:       if (this.map.isLedge(tx, ty)) return false;
351:       // Check NPC collision
352:       for (const npc of NPCS) {
353:         if (tx === npc.x && ty === npc.y) return false;
354:       }
