359:   movePlayerWithSlide(dx, dy) {
360:     const startX = this.player.x;
361:     const startY = this.player.y;
362: 
363:     // Check if pushing downward into a one-way cliff ledge!
364:     if (dy > 0.01 && Math.abs(dy) >= Math.abs(dx)) {
365:       const targetTileX = Math.floor(this.player.x);
366:       const ledgeTileY = Math.floor(this.player.y + 0.55);
367:       if (
368:         this.map.isLedge(targetTileX, ledgeTileY) &&
369:         !this.map.isSolid(targetTileX, ledgeTileY + 1)
370:       ) {
371:         this.player.dir = 'down';
372:         this.player.jumpTimer = 0.28;
373:         this.audio.playLedgeHop();
374:         this.spawnLeafParticles(this.player.x, this.player.y + 1, '#d97706');
375:         return;
376:       }
377:     }
378: 
379:     // Try X movement
380:     if (dx !== 0) {
381:       if (this.canOccupy(this.player.x + dx, this.player.y)) {
382:         this.player.x += dx;
383:       } else {
384:         // Corner assist slide along Y if blocked on X corner
385:         const slideStep = Math.abs(dx) * 0.65;
386:         if (this.canOccupy(this.player.x + dx, this.player.y - slideStep)) {
387:           this.player.y -= slideStep;
388:         } else if (this.canOccupy(this.player.x + dx, this.player.y + slideStep)) {
389:           this.player.y += slideStep;
390:         }
391:       }
392:     }
393: 
394:     // Try Y movement
395:     if (dy !== 0) {
396:       if (this.canOccupy(this.player.x, this.player.y + dy)) {
397:         this.player.y += dy;
398:       } else {
399:         // Corner assist slide along X if blocked on Y corner
400:         const slideStep = Math.abs(dy) * 0.65;
401:         if (this.canOccupy(this.player.x - slideStep, this.player.y + dy)) {
402:           this.player.x -= slideStep;
403:         } else if (this.canOccupy(this.player.x + slideStep, this.player.y + dy)) {
404:           this.player.x += slideStep;
405:         }
406:       }
407:     }
408: 
409:     const distMoved = Math.hypot(this.player.x - startX, this.player.y - startY);
410:     this.player.stepsTaken += distMoved;
