input.newString:
.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,20px);opacity:0;transition:.25s;pointer-events:none;background:#f8f5e9;color:#233249;padding:10px 15px;border-radius:5px;font:11px 'DM Mono',monospace;box-shadow:0 6px 25px #0005;z-index:10}.toast.show{opacity:1;transform:translate(-50%,0)}
.intro-overlay{position:absolute;inset:0;background:rgba(16,28,45,.86);display:flex;align-items:center;justify-content:center;padding:12px;z-index:5;backdrop-filter:blur(2px)}
.intro-overlay[hidden]{display:none}
.intro-card{width:min(100%,460px);background:#f7f3e3;border:3px solid #28394a;border-radius:8px;padding:14px 16px;color:#17263a;box-shadow:0 14px 32px rgba(0,0,0,.45);font-family:'DM Sans',system-ui,sans-serif}
.intro-kicker{display:flex;align-items:center;justify-content:space-between;font:700 9px 'DM Mono',monospace;letter-spacing:1.2px;color:#c94a44;margin-bottom:4px}
.intro-title{margin:0 0 6px;font-size:16px;font-weight:800;color:#17263a}
.intro-copy{margin:0 0 10px;font-size:11.5px;line-height:1.45;color:#3d4d5e}
.name-presets{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-bottom:10px}
.name-preset-btn{border:1px solid #b9b4a2;background:#fffdf6;color:#243447;border-radius:4px;padding:5px 6px;font:700 10px 'DM Mono',monospace;letter-spacing:.7px;cursor:pointer;transition:.12s}
.name-preset-btn:hover,.name-preset-btn.active{background:#f6cb49;border-color:#b88d19;color:#17263a;box-shadow:0 2px 0 #c6a337}
.name-input-row{display:flex;gap:8px;align-items:center}
.name-input{flex:1;min-width:0;height:34px;border:2px solid #28394a;border-radius:4px;background:#fff;padding:0 10px;font:700 12px 'DM Mono',monospace;color:#17263a;letter-spacing:1px;text-transform:uppercase}
.name-input:focus{outline:2px solid #f6cb49;border-color:#17263a}
.name-confirm-btn{height:34px;border:0;border-radius:4px;background:#e04848;color:#fff;font:700 10px 'DM Mono',monospace;letter-spacing:.8px;padding:0 12px;cursor:pointer;box-shadow:0 2px 0 #9e2b2b;white-space:nowrap}
.name-confirm-btn:hover{background:#eb5757}
.trainer-tag{display:inline-flex;align-items:center;gap:6px;background:#223247;border:1px solid #394b63;border-radius:4px;padding:4px 8px;font:700 9px 'DM Mono',monospace;color:#f6cb49;letter-spacing:.9px;margin-top:6px}
.trainer-tag b{color:#fff}

