+.intro-overlay{position:absolute;inset:0;background:rgba(16,28,45,.86);display:flex;align-items:center;justify-content:center;padding:12px;z-index:5;backdrop-filter:blur(2px)}
+.intro-overlay[hidden]{display:none}
+.intro-card{width:min(100%,460px);background:#f7f3e3;border:3px solid #28394a;border-radius:8px;padding:14px 16px;color:#17263a;box-shadow:0 14px 32px rgba(0,0,0,.45);font-family:'DM Sans',system-ui,sans-serif}
+.intro-kicker{display:flex;align-items:center;justify-content:space-between;font:700 9px 'DM Mono',monospace;letter-spacing:1.2px;color:#c94a44;margin-bottom:4px}
+.intro-title{margin:0 0 6px;font-size:16px;font-weight:800;color:#17263a}
+.intro-copy{margin:0 0 10px;font-size:11.5px;line-height:1.45;color:#3d4d5e}
+.name-presets{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-bottom:10px}
+.name-preset-btn{border:1px solid #b9b4a2;background:#fffdf6;color:#243447;border-radius:4px;padding:5px 6px;font:700 10px 'DM Mono',monospace;letter-spacing:.7px;cursor:pointer;transition:.12s}
+.name-preset-btn:hover,.name-preset-btn.active{background:#f6cb49;border-color:#b88d19;color:#17263a;box-shadow:0 2px 0 #c6a337}
+.name-input-row{display:flex;gap:8px;align-items:center}
+.name-input{flex:1;min-width:0;height:34px;border:2px solid #28394a;border-radius:4px;background:#fff;padding:0 10px;font:700 12px 'DM Mono',monospace;color:#17263a;letter-spacing:1px;text-transform:uppercase}
+.name-input:focus{outline:2px solid #f6cb49;border-color:#17263a}
+.name-confirm-btn{height:34px;border:0;border-radius:4px;background:#e04848;color:#fff;font:700 10px 'DM Mono',monospace;letter-spacing:.8px;padding:0 12px;cursor:pointer;box-shadow:0 2px 0 #9e2b2b;white-space:nowrap}
+.name-confirm-btn:hover{background:#eb5757}
+.trainer-tag{display:inline-flex;align-items:center;gap:6px;background:#223247;border:1px solid #394b63;border-radius:4px;padding:4px 8px;font:700 9px 'DM Mono',monospace;color:#f6cb49;letter-spacing:.9px;margin-top:6px}
+.trainer-tag b{color:#fff}
 @media(max-width:850px){.shell{width:min(700px,calc(100% - 28px));padding-top:14px}.game-layout{grid-template-columns:1fr}.side-panel{min-height:0}.goal-box{margin-top:0}.side-footer{margin-top:11px}.game-frame{padding:8px}.edition{font-size:8px}.controls-row{gap:9px}.control-hint{font-size:9px}.action-button{min-width:128px}}
 @media(max-width:480px){.shell{width:calc(100% - 20px);padding-top:10px}.topbar{margin-bottom:13px;height:39px}.edition{display:none}.brand{font-size:11px}.game-frame{padding:5px}.screen-top,.screen-bottom{font-size:7px}.canvas-wrap{border-width:3px}.controls-row{min-height:75px;gap:7px;padding-top:8px}.dpad{transform:scale(.88);transform-origin:left center;width:56px}.control-hint{font-size:8px;line-height:2}.keycap{font-size:7px;padding:3px}.action-button{min-width:105px;height:42px;font-size:8px;padding:0 7px;gap:4px}.action-key{font-size:7px;padding-left:5px;margin-left:2px}.side-panel{padding:15px}.partner-art{width:70px;height:70px}.page-footer{font-size:7px;letter-spacing:.6px;margin-top:15px}.page-footer span:last-child{text-align:right}}

input.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#17263a;--muted:#758196;--paper:#f7f5ef;--yellow:#f6cb49;--green:#73b89b;--red:#e04848;--line:#e4e6e2;--navy:#101c2d}
*{box-sizing:border-box}
html{background:var(--navy)}
body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 42% 0%,#26364a 0,#101c2d 62%);color:var(--ink);font-family:'DM Sans',system-ui,sans-serif}
.shell{width:min(1120px,calc(100% - 48px));margin:0 auto;padding:20px 0 18px}
.topbar{height:46px;display:flex;align-items:center;justify-content:space-between;color:#f4f1e7;margin-bottom:18px;gap:12px}
.brand{display:flex;gap:10px;align-items:center;color:inherit;text-decoration:none;font-size:13px;font-weight:600;letter-spacing:1.35px}
.brand b{color:var(--yellow);font-weight:800}
.brand-mark{display:grid;place-items:center;width:29px;height:29px;border:1px solid #d94b45;background:#261a24;color:#ff665e;font-size:15px;font-weight:800;border-radius:8px}
.edition{font:10px 'DM Mono',monospace;letter-spacing:1.5px;color:#aab3c0}
.edition-dot,.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#e04848;margin-right:8px;vertical-align:1px;box-shadow:0 0 8px #e04848}
.edition-sep{color:#626f81;margin:0 7px}
.top-actions{display:flex;gap:8px;align-items:center}
.sound-toggle{background:transparent;color:#bec6d0;border:1px solid #435064;border-radius:5px;padding:7px 10px;font:11px 'DM Mono',monospace;cursor:pointer}
.sound-toggle:hover{border-color:var(--yellow);color:#fff}
.game-layout{display:grid;grid-template-columns:minmax(0,746px) minmax(280px,1fr);gap:19px;align-items:stretch}
.game-column{min-width:0}
.game-frame{border-radius:8px;background:#f8f6ef;padding:11px;box-shadow:0 20px 50px #080f1c80;border:1px solid #c8c8bc}
.screen-top,.screen-bottom{height:24px;display:flex;align-items:center;justify-content:space-between;padding:0 6px;font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#5a6572}
.screen-top{padding-bottom:4px}
.screen-bottom{padding-top:4px;letter-spacing:.7px;text-transform:uppercase}
.pixel-heart{font-size:14px;color:#e04848}
.canvas-wrap{position:relative;width:100%;aspect-ratio:16/9;background:#222834;overflow:hidden;border:4px solid #293849;box-shadow:inset 0 0 0 1px #ffffff45}
.canvas-wrap canvas{display:block;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges}
.screen-grain{pointer-events:none;position:absolute;inset:0;background:repeating-linear-gradient(0deg,#17263a0a 0px,#17263a0a 1px,transparent 1px,transparent 3px);opacity:.2}
.controls-row{display:flex;align-items:center;gap:12px;padding:12px 2px 0;min-height:82px;flex-wrap:wrap}
.dpad{width:63px;height:63px;position:relative;display:grid;grid-template-columns:repeat(3,21px);grid-template-rows:repeat(3,21px);flex:none}
.dpad-btn{border:0;background:#27374b;color:#f5f2e9;font-size:10px;line-height:1;cursor:pointer;touch-action:none;padding:0}
.dpad-btn:hover,.dpad-btn:active{background:#46596e;color:var(--yellow)}
.dpad-btn.up{grid-column:2;grid-row:1;border-radius:4px 4px 0 0}
.dpad-btn.left{grid-column:1;grid-row:2;border-radius:4px 0 0 4px}
.dpad-btn.right{grid-column:3;grid-row:2;border-radius:0 4px 4px 0}
.dpad-btn.down{grid-column:2;grid-row:3;border-radius:0 0 4px 4px}
.dpad-center{background:#27374b;grid-column:2;grid-row:2;color:#e04848}
.control-hint{flex:1;color:#aeb8c5;font:10px/1.8 'DM Mono',monospace;min-width:170px;margin:0}
.keycap{color:#e8e7de;background:#2c3b4e;border-radius:3px;padding:2px 5px;font-size:9px;white-space:nowrap}
.action-buttons-group{display:flex;gap:8px;margin-left:auto}
.rank-button{height:44px;border:1px solid #d94b45;border-radius:5px;background:#2b1d28;color:#ff8078;font:700 10px 'DM Mono',monospace;letter-spacing:.6px;padding:0 11px;display:flex;align-items:center;gap:6px;cursor:pointer;box-shadow:0 3px 0 #170e15;transition:transform .1s,box-shadow .1s}
.rank-button:hover{background:#3c2536;color:#ffd2cf;transform:translateY(-1px)}
.rank-button:active{transform:translateY(2px);box-shadow:0 1px 0 #170e15}
.action-button{height:44px;min-width:140px;border:0;border-radius:5px;background:var(--yellow);color:#293449;font:700 10px 'DM Mono',monospace;letter-spacing:.6px;padding:0 11px;display:flex;align-items:center;gap:7px;cursor:pointer;box-shadow:0 3px 0 #c6a337;transition:transform .1s,box-shadow .1s}
.action-button:hover{background:#ffda62;transform:translateY(-1px);box-shadow:0 4px 0 #c6a337}
.action-button:active{transform:translateY(2px);box-shadow:0 1px 0 #c6a337}
.action-icon{font-size:14px;font-weight:800}
.action-key{border-left:1px solid #aa902d;padding-left:8px;margin-left:4px;font-size:8px;color:#665a32}

/* Introduction & Name Selection Overlay */
.intro-overlay{position:absolute;inset:0;background:rgba(13,20,33,.84);display:flex;align-items:center;justify-content:center;padding:10px;z-index:6;backdrop-filter:blur(2px)}
.intro-overlay[hidden]{display:none !important}
.intro-card{width:min(100%,540px);max-height:100%;overflow-y:auto;background:#f7f3e3;border:3px solid #28394a;border-radius:8px;padding:12px 15px;color:#17263a;box-shadow:0 14px 32px rgba(0,0,0,.55)}
.intro-kicker{display:flex;align-items:center;justify-content:space-between;font:700 9px 'DM Mono',monospace;letter-spacing:1.1px;color:#c93b35;margin-bottom:3px}
.intro-title{margin:0 0 4px;font-size:15px;font-weight:800;color:#17263a}
.intro-copy{margin:0 0 9px;font-size:11px;line-height:1.38;color:#3d4d5e}
.dossier-grid{display:flex;flex-direction:column;gap:7px;margin-bottom:10px}
.dossier-row{background:#ece6d1;border:1px solid #cfc7ae;border-radius:5px;padding:6px 8px}
.dossier-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:5px}
.dossier-label{font:700 9px 'DM Mono',monospace;letter-spacing:.7px;color:#223247}
.dossier-role{font:600 8px 'DM Mono',monospace;padding:1px 5px;border-radius:3px;background:#26364a;color:#f6cb49}
.dossier-role.role-rocket{background:#471f28;color:#ff8b85}
.dossier-role.role-hero{background:#1f3f39;color:#8ef0c0}
.dossier-controls{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
.name-input{width:118px;height:27px;border:2px solid #28394a;border-radius:4px;background:#fff;padding:0 7px;font:700 11px 'DM Mono',monospace;color:#17263a;letter-spacing:.8px;text-transform:uppercase}
.name-input:focus{outline:2px solid #f6cb49;border-color:#17263a}
.preset-list{display:flex;gap:4px;flex-wrap:wrap;flex:1}
.name-preset-btn{border:1px solid #b9b4a2;background:#fffdf6;color:#243447;border-radius:3px;padding:3px 6px;font:700 9px 'DM Mono',monospace;letter-spacing:.5px;cursor:pointer;transition:.1s}
.name-preset-btn:hover,.name-preset-btn.active{background:#f6cb49;border-color:#b88d19;color:#17263a}
.intro-footer{display:flex;align-items:center;justify-content:space-between;gap:8px}
.intro-hint{font:9px 'DM Mono',monospace;color:#5c6877}
.name-confirm-btn{height:32px;border:0;border-radius:4px;background:#d9413b;color:#fff;font:700 10px 'DM Mono',monospace;letter-spacing:.8px;padding:0 14px;cursor:pointer;box-shadow:0 2px 0 #8f221e;white-space:nowrap}
.name-confirm-btn:hover{background:#eb524c}

/* Side Panel */
.side-panel{border:1px solid #394658;background:#17263a;border-radius:8px;padding:16px 15px;color:#ece9df;display:flex;flex-direction:column;min-height:100%}
.panel-kicker,.goal-label{font:9px 'DM Mono',monospace;letter-spacing:1.5px;color:#9daabc;display:flex;align-items:center;justify-content:space-between}
.status-line{font-size:12px;line-height:1.45;color:#e5e9f0;margin:8px 0 11px;min-height:34px;background:#1e2f46;padding:8px 10px;border-radius:5px;border-left:3px solid var(--yellow)}

/* Organization Rank Card */
.rank-card{background:#211b29;border:1px solid #593243;border-radius:6px;padding:9px 11px;margin-bottom:11px}
.rank-header{display:flex;justify-content:space-between;align-items:center;font:700 9px 'DM Mono',monospace;color:#ff857d;letter-spacing:.8px}
.rank-title-row{display:flex;justify-content:space-between;align-items:baseline;margin:4px 0 6px}
.rank-title-row strong{font:800 13px 'DM Mono',monospace;color:#f6cb49;letter-spacing:.5px}
.rank-title-row span{font:9px 'DM Mono',monospace;color:#cbb8c3}
.rank-track{height:5px;background:#38293b;border-radius:4px;overflow:hidden}
.rank-fill{height:100%;width:20%;background:linear-gradient(90deg,#e04848,#f6cb49);transition:width .3s}

/* Rivals Roster Strip */
.rivals-strip{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-bottom:11px}
.rival-chip{background:#203044;border:1px solid #31445c;border-radius:5px;padding:6px 8px;font:8px 'DM Mono',monospace;color:#9daabc}
.rival-chip b{display:block;font-size:11px;color:#f4f1e7;margin-top:2px;letter-spacing:.5px}
.rival-chip.rocket-rival{border-left:2px solid #e04848}
.rival-chip.hero-rival{border-left:2px solid #58c496}

.partner-card{display:flex;gap:11px;margin:0 0 11px;align-items:center;background:#1e2f44;padding:8px 10px;border-radius:6px;border:1px solid #2e4259}
.partner-art{width:64px;height:64px;position:relative;flex:none;border-radius:7px;background:#293b4c;display:grid;place-items:center;overflow:hidden;background-image:radial-gradient(#ffffff0e 1px,transparent 1px);background-size:8px 8px}
.buddy-icon{position:relative;width:30px;height:31px;background:#f6c849;border:3px solid #d59b32;border-radius:48% 48% 43% 43%;box-shadow:inset -4px -3px #e8ad3d;z-index:2}
.buddy-icon:before{content:'';position:absolute;width:11px;height:16px;left:-4px;top:-12px;background:#f4c747;clip-path:polygon(35% 0,100% 10%,100% 100%,0 100%);border-top:3px solid #d59b32}
.buddy-icon:after{content:'';position:absolute;width:10px;height:18px;right:-4px;top:-12px;background:#f4c747;clip-path:polygon(0 10%,65% 0,100% 100%,0 100%);border-top:3px solid #d59b32}
.ear{position:absolute;width:5px;height:6px;top:-8px;z-index:3;background:#302b2a}
.e1{left:0;transform:rotate(-14deg)}
.e2{right:0;transform:rotate(14deg)}
.eye{position:absolute;width:3px;height:4px;background:#272b30;top:9px}
.eye1{left:6px}
.eye2{right:6px}
.cheek{position:absolute;background:#ed735b;width:6px;height:5px;border-radius:50%;top:15px}
.c1{left:-4px}
.c2{right:-4px}
.mouth{position:absolute;width:4px;height:2px;border-bottom:1px solid #573b2c;left:10px;top:17px}
.spark{position:absolute;color:#f4cc56}
.spark-a{top:8px;left:7px;font-size:11px}
.spark-b{bottom:8px;right:7px;font-size:9px}
.partner-info{flex:1;min-width:0}
.partner-name{font-size:12px;font-weight:800;letter-spacing:.7px;color:#f8f4e8}
.partner-name>span{float:right;color:#9ea9b7;font:9px 'DM Mono',monospace;margin-top:2px}
.partner-name>span b{color:#f5cb4e}
.partner-type{font:8px 'DM Mono',monospace;color:#aeb7c2;letter-spacing:1px;margin:4px 0 7px}
.partner-type i{display:inline-block;width:6px;height:6px;background:#f2c74b;border-radius:50%;margin-right:5px}
.hp-track{height:5px;background:#405064;border-radius:4px;overflow:hidden}
.hp-fill{width:100%;height:100%;background:#8acb91;border-radius:4px;transition:width .25s}
.hp-text{display:flex;justify-content:space-between;margin-top:4px;color:#8492a2;font:8px 'DM Mono',monospace}
.hp-text b{font-weight:400;color:#d9e2dd}
.stats-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.stat-box{padding:8px 10px;background:#223247;border-radius:5px;border:1px solid #304258}
.stat-box span{display:block;color:#9eabba;font:8px 'DM Mono',monospace;letter-spacing:.8px}
.stat-box b{display:inline-block;margin-top:3px;font:700 18px 'DM Mono',monospace;color:#f5cf54}
.stat-box i{font-style:normal;color:#8090a1;font:9px 'DM Sans',sans-serif;margin-left:5px}
.field-note{display:flex;gap:8px;margin:11px 0;background:#203044;padding:9px 10px;border-left:2px solid #e6bd4b;border-radius:0 5px 5px 0}
.note-icon{font-size:13px;color:#e6bd4b}
.field-note b{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#e8c85b}
.field-note p{font-size:10px;line-height:1.42;color:#b3bdc8;margin:3px 0 0}
.goal-box{padding:9px 1px 0;border-top:1px solid #354355;margin-top:auto}
.goal-label{font-size:8px}
.goal-text{display:flex;gap:8px;align-items:center;font-size:11px;color:#e4e7df;margin:6px 0}
.goal-check{font:15px 'DM Mono',monospace;color:#e9c653}
.goal-progress{height:4px;background:#36475a;border-radius:3px;overflow:hidden}
.goal-progress div{height:100%;width:14%;background:#efca54;transition:width .4s}
.side-footer{font:9px 'DM Mono',monospace;color:#7e8d9f;margin-top:10px;display:flex;justify-content:space-between}
.side-footer span{color:#edc84f}
.page-footer{display:flex;justify-content:space-between;margin-top:16px;color:#758397;font:8px 'DM Mono',monospace;letter-spacing:1.3px}
.page-footer b{color:#f0c84b;font-size:11px}
.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,20px);opacity:0;transition:.25s;pointer-events:none;background:#f8f5e9;color:#233249;padding:10px 15px;border-radius:5px;font:700 11px 'DM Mono',monospace;box-shadow:0 6px 25px #0006;z-index:20;border:2px solid #28394a}
.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:850px){.shell{width:min(700px,calc(100% - 28px));padding-top:14px}.game-layout{grid-template-columns:1fr}.side-panel{min-height:0}.goal-box{margin-top:0}.side-footer{margin-top:11px}.game-frame{padding:8px}.edition{font-size:8px}.controls-row{gap:9px}.control-hint{font-size:9px}.action-button{min-width:128px}}
@media(max-width:480px){.shell{width:calc(100% - 20px);padding-top:10px}.topbar{margin-bottom:13px;height:39px}.edition{display:none}.brand{font-size:11px}.game-frame{padding:5px}.screen-top,.screen-bottom{font-size:7px}.canvas-wrap{border-width:3px}.controls-row{min-height:75px;gap:7px;padding-top:8px}.dpad{transform:scale(.88);transform-origin:left center;width:56px}.control-hint{font-size:8px;line-height:2}.keycap{font-size:7px;padding:3px}.action-button{min-width:105px;height:40px;font-size:8px;padding:0 7px;gap:4px}.side-panel{padding:14px}.page-footer{font-size:7px;letter-spacing:.6px;margin-top:15px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const W = canvas.width, H = canvas.height, T = 16;
  const $ = id => document.getElementById(id);

  const ui = {
    status: $('status-line'),
    area: $('area-label'),
    level: $('level'),
    hpBar: $('hp-bar'),
    hpText: $('hp-text'),
    buddyCount: $('buddy-count'),
    wins: $('win-count'),
    noteTitle: $('note-title'),
    note: $('field-note'),
    goal: $('goal-text'),
    goalCheck: $('goal-check'),
    progress: $('goal-progress'),
    action: $('action-label'),
    toast: $('toast'),
    playerNameDisplay: $('player-name-display'),
    rocketRivalDisplay: $('rocket-rival-display'),
    heroRivalDisplay: $('hero-rival-display'),
    rankDisplay: $('rank-display'),
    rankTierPill: $('rank-tier-pill'),
    meritDisplay: $('merit-display'),
    rankBar: $('rank-bar'),
    gruntCallsign: $('grunt-callsign'),
    jobLedger: $('job-ledger'),
    fundsReadout: $('funds-readout'),
    introOverlay: $('intro-overlay'),
    introForm: $('intro-form'),
    playerInput: $('player-name-input'),
    rocketRivalInput: $('rocket-rival-input'),
    heroRivalInput: $('hero-rival-input')
  };

  const rnd = (a, b) => Math.floor(Math.random() * (b - a + 1)) + a;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

  const RANKS = [
    { title: 'PROBATIONARY GRUNT', minMerits: 0, nextMerits: 25, bonusHp: 0 },
    { title: 'FIELD GRUNT', minMerits: 25, nextMerits: 50, bonusHp: 4 },
    { title: 'ROCKET AGENT', minMerits: 50, nextMerits: 80, bonusHp: 8 },
    { title: 'ROCKET ELITE', minMerits: 80, nextMerits: 115, bonusHp: 12 },
    { title: 'ROCKET EXECUTIVE', minMerits: 115, nextMerits: 150, bonusHp: 18 }
  ];

  const creatures = [
    { name: 'MOSSLET', kind: 'LEAF', color: '#79bd83', accent: '#3d8d62', hp: 20 },
    { name: 'EMBERCUB', kind: 'FLAME', color: '#ee9870', accent: '#d8644e', hp: 22 },
    { name: 'PEBBLIT', kind: 'STONE', color: '#aaa6a0', accent: '#817a74', hp: 24 },
    { name: 'CLOUDFIN', kind: 'MIST', color: '#9cc9d7', accent: '#568ca5', hp: 19 }
  ];

  const SLOT_SYMBOLS = [
    { id: 'R', label: 'R', name: 'ROCKET R', color: '#e04848', bg: '#2b1b24', payout: 300, merits: 35, orb: 1 },
    { id: '7', label: '7', name: 'LUCKY 7', color: '#f6cb49', bg: '#2f2918', payout: 240, merits: 30, orb: 1 },
    { id: 'BOLT', label: '⚡', name: 'VOLT BOLT', color: '#ffe066', bg: '#1e3042', payout: 170, merits: 25, orb: 0 },
    { id: 'STAR', label: '★', name: 'GOLD STAR', color: '#9be5aa', bg: '#1c3329', payout: 140, merits: 20, orb: 0 },
    { id: 'CHERRY', label: '🍒', name: 'CHERRY', color: '#ff8787', bg: '#33202a', payout: 100, merits: 15, orb: 0 }
  ];

  const game = {
    mode: 'intro', // Starts on introduction with character naming dossier open
    playerName: 'JESS',
    rocketRival: 'VIPER',
    heroRival: 'RED',
    rankIndex: 0,
    merits: 0,
    funds: 100,
    orbs: 3,
    potions: 2,
    cornerShifts: 0,
    daycareShifts: 0,
    step: 0,
    steps: 0,
    wins: 0,
    caught: 0,
    level: 3,
    xp: 0,
    maxHp: 28,
    hp: 28,
    // Start inside the Rundown Team Rocket Base!
    x: 7,
    y: 7,
    facing: 'up',
    moveClock: 0,
    buddyTrail: [{ x: 7, y: 8 }],
    toastTimer: 0,
    message: 'Report to Commander Vex in the Rundown Rocket Base or head out to work shifts.',
    talkedVex: false,
    defeatedRocketRival: false,
    defeatedHeroRival: false,
    battle: null,
    slots: {
      spinning: false,
      rigged: false,
      reels: [0, 1, 2],
      stopTimes: [0, 0, 0],
      locked: [true, true, true],
      lastWin: 0,
      spins: 0,
      banner: 'SPIN REELS (SPACE/1) OR WORK SHIFT TO RIG JACKPOT (2)!'
    },
    sound: true,
    keys: {},
    lastTime: 0,
    anim: 0,
    grassEncounterCooldown: 0
  };

  const mapW = 32, mapH = 26;
  const path = new Set();
  const addPath = (x1, y1, x2, y2) => {
    let x = x1, y = y1;
    path.add(`${x},${y}`);
    while (x !== x2) { x += Math.sign(x2 - x); path.add(`${x},${y}`); }
    while (y !== y2) { y += Math.sign(y2 - y); path.add(`${x},${y}`); }
  };

  // Connect Rundown Base doorway (7,9) to Daycare (5,16), Game Corner (16,8), Protagonist Rival (15,12), and Tall Grass (21+)
  addPath(7, 9, 7, 16);
  addPath(5, 16, 12, 16);
  addPath(12, 19, 12, 8);
  addPath(12, 8, 18, 8);
  addPath(12, 12, 25, 12);

  const baseBounds = { x1: 2, y1: 2, x2: 11, y2: 9, doorX: 7, doorY: 9 };
  const grassAreas = [
    { x: 21, y: 7, w: 8, h: 4 },
    { x: 23, y: 13, w: 6, h: 7 },
    { x: 4, y: 19, w: 7, h: 4 }
  ];
  const ponds = [{ x: 25, y: 3, w: 5, h: 3 }];
  const solids = new Set();

  for (let x = 0; x < mapW; x++) { solids.add(`${x},0`); solids.add(`${x},${mapH - 1}`); }
  for (let y = 0; y < mapH; y++) { solids.add(`0,${y}`); solids.add(`${mapW - 1},${y}`); }

  // Rundown Team Rocket Base perimeter walls (leaving doorway at 7,9 open)
  for (let x = baseBounds.x1; x <= baseBounds.x2; x++) {
    solids.add(`${x},${baseBounds.y1}`);
    if (x !== baseBounds.doorX) solids.add(`${x},${baseBounds.y2}`);
  }
  for (let y = baseBounds.y1; y <= baseBounds.y2; y++) {
    solids.add(`${baseBounds.x1},${y}`);
    solids.add(`${baseBounds.x2},${y}`);
  }
  // Rusted crates & generator inside the Rundown Base
  [[3, 3], [4, 3], [10, 3], [3, 8]].forEach(([cx, cy]) => solids.add(`${cx},${cy}`));

  // Town Buildings: Game Corner, Daycare, Outpost Shack
  const buildings = [
    { x: 14, y: 4, w: 6, h: 4, type: 'corner', label: 'GAME CORNER' },
    { x: 3, y: 12, w: 5, h: 4, type: 'daycare', label: 'DAYCARE' },
    { x: 17, y: 16, w: 5, h: 3, type: 'home', label: 'SUPPLY DEPOT' }
  ];
  buildings.forEach(b => {
    for (let y = b.y; y < b.y + b.h; y++)
      for (let x = b.x; x < b.x + b.w; x++)
        solids.add(`${x},${y}`);
  });

  const trees = [
    [22, 3], [23, 3], [24, 3], [29, 5], [29, 6], [29, 7], [30, 7],
    [28, 21], [29, 21], [30, 21], [12, 23], [13, 23], [14, 23], [15, 23],
    [16, 23], [17, 23], [18, 23], [19, 23], [20, 23], [21, 23], [22, 23],
    [23, 23], [24, 23], [25, 23], [26, 23], [27, 23], [28, 23], [29, 23]
  ];
  trees.forEach(([x, y]) => solids.add(`${x},${y}`));

  // Key NPCs: Commander Vex (Base), Rocket Rival (Base), Heroic Protagonist Rival (Town), Game Corner Boss, Daycare Keeper
  const npcs = {
    vex: { x: 7, y: 4, role: 'vex' },
    rocketRival: { x: 9, y: 6, role: 'rocketRival' },
    heroRival: { x: 15, y: 12, role: 'heroRival' },
    cornerBoss: { x: 16, y: 8, role: 'cornerBoss' },
    daycareKeeper: { x: 5, y: 16, role: 'daycareKeeper' }
  };

  function inRundownBase(x, y) {
    return x >= baseBounds.x1 && x <= baseBounds.x2 && y >= baseBounds.y1 && y <= baseBounds.y2;
  }

  function currentAreaName() {
    if (game.mode === 'slots') return 'ROCKET GAME CORNER';
    if (inRundownBase(game.x, game.y)) return 'RUNDOWN ROCKET BASE';
    if (Math.abs(game.x - npcs.cornerBoss.x) + Math.abs(game.y - npcs.cornerBoss.y) <= 3) return 'GAME CORNER PLAZA';
    if (Math.abs(game.x - npcs.daycareKeeper.x) + Math.abs(game.y - npcs.daycareKeeper.y) <= 3) return 'SUNMEADOW DAYCARE';
    if (game.x > 19 || game.y > 18) return 'SUNMEADOW TRAIL';
    return 'SUNMEADOW OUTSKIRTS';
  }

  function tileType(x, y) {
    if (x < 0 || y < 0 || x >= mapW || y >= mapH) return 'wall';
    if (inRundownBase(x, y)) return 'baseFloor';
    if (ponds.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'water';
    if (path.has(`${x},${y}`)) return 'path';
    if (grassAreas.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'tall';
    return 'grass';
  }

  function npcAt(x, y) {
    return Object.values(npcs).find(n => n.x === x && n.y === y) || null;
  }

  function solid(x, y) {
    return solids.has(`${x},${y}`) || tileType(x, y) === 'water' || Boolean(npcAt(x, y));
  }

  function rect(x, y, w, h, color) {
    ctx.fillStyle = color;
    ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
  }

  function pixelText(text, x, y, size = 8, color = '#fff', align = 'left') {
    ctx.font = `bold ${size}px monospace`;
    ctx.textAlign = align;
    ctx.textBaseline = 'top';
    ctx.fillStyle = color;
    ctx.fillText(text, Math.round(x), Math.round(y));
  }

  function rounded(x, y, w, h, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
  }

  function drawTerrain(tx, ty, sx, sy) {
    const type = tileType(tx, ty);
    const seed = (tx * 92821 + ty * 68917) % 97;
    if (type === 'baseFloor') {
      // Cracked rundown Team Rocket base concrete & rusted metal plating
      const isWall =
        (ty === baseBounds.y1 || (ty === baseBounds.y2 && tx !== baseBounds.doorX) || tx === baseBounds.x1 || tx === baseBounds.x2);
      if (isWall) {
        rect(sx, sy, T, T, '#2d3340');
        rect(sx, sy, T, 3, '#454e5e');
        rect(sx + 2, sy + 5, T - 4, 8, '#39282c');
        rect(sx + 3, sy + 7, 3, 2, '#7d4842'); // rust patch
      } else {
        rect(sx, sy, T, T, (tx + ty) % 2 === 0 ? '#3a404d' : '#353b47');
        // Cracks, oil stains, and leaky puddle marks
        if (seed % 5 === 0) {
          rect(sx + 3, sy + 4, 5, 1, '#262b34');
          rect(sx + 7, sy + 5, 1, 4, '#262b34');
        }
        if (seed % 8 === 0) {
          rect(sx + 9, sy + 10, 4, 3, '#2b3942');
        }
      }
    } else if (type === 'grass') {
      rect(sx, sy, T, T, seed % 5 === 0 ? '#84c28d' : '#8bc995');
      if (seed % 7 === 0) {
        rect(sx + 3, sy + 4, 2, 2, '#a5d6a0');
        rect(sx + 11, sy + 12, 2, 1, '#6eb67c');
      }
    } else if (type === 'path') {
      rect(sx, sy, T, T, '#d7bd85');
      if (seed % 4 === 0) rect(sx + ((seed % 9) + 3), sy + 5, 2, 2, '#c7aa72');
      if (seed % 6 === 0) rect(sx + 3, sy + 12, 3, 1, '#e6d09e');
    } else if (type === 'tall') {
      rect(sx, sy, T, T, '#79bb80');
      const sway = Math.sin(game.anim * 0.003 + tx * 2 + ty) * 1.5;
      rect(sx + 3, sy + 9 + sway, 2, 6, '#438e5c');
      rect(sx + 5, sy + 5 + sway, 2, 9, '#519f66');
      rect(sx + 9, sy + 8 - sway, 2, 7, '#3f8858');
      rect(sx + 12, sy + 4 - sway, 2, 10, '#55a56c');
      rect(sx + 4, sy + 5 + sway, 2, 2, '#9bd296');
      rect(sx + 11, sy + 4 - sway, 2, 2, '#a1d89a');
    } else if (type === 'water') {
      rect(sx, sy, T, T, '#78bbcf');
      rect(sx, sy, 16, 2, '#9cdaeb');
      if (seed % 3 === 0) {
        rect(sx + 4, sy + 8 + Math.sin(game.anim * 0.002 + tx) * 2, 5, 1, '#a8e0e9');
        rect(sx + 10, sy + 12, 2, 1, '#639fb7');
      }
    } else {
      rect(sx, sy, T, T, '#83bd8b');
    }
  }

  function drawRundownBaseDetails(camX, camY) {
    // Peeling red Team Rocket "R" emblem painted on the rundown base floor
    const rx = 6 * T - camX + 6;
    const ry = 5 * T - camY + 2;
    rect(rx, ry, 20, 22, '#2c313d');
    rect(rx + 3, ry + 2, 4, 18, '#b83b3b');
    rect(rx + 7, ry + 2, 8, 4, '#b83b3b');
    rect(rx + 12, ry + 5, 4, 5, '#b83b3b');
    rect(rx + 7, ry + 9, 7, 4, '#b83b3b');
    rect(rx + 10, ry + 13, 6, 7, '#b83b3b');
    // Scratches across the floor logo to look worn/rundown
    rect(rx + 4, ry + 8, 12, 1, '#3a404d');
    rect(rx + 2, ry + 15, 10, 1, '#353b47');

    // Rusted crates & flickering generator inside base
    [[3, 3], [4, 3], [10, 3], [3, 8]].forEach(([cx, cy], idx) => {
      const sx = cx * T - camX, sy = cy * T - camY;
      rect(sx + 1, sy + 2, 14, 13, idx === 2 ? '#394b59' : '#73533d');
      rect(sx + 2, sy + 3, 12, 3, idx === 2 ? '#597b8c' : '#8f694d');
      rect(sx + 4, sy + 8, 8, 2, '#262b34');
    });

    // Overhead Rundown Base Banner
    const bx = 7 * T - camX - 38;
    const by = 2 * T - camY - 4;
    rounded(bx, by, 92, 12, 3, '#211820eb');
    pixelText('RUNDOWN ROCKET BASE', bx + 46, by + 2, 7, '#ff7a72', 'center');
  }

  function drawTree(sx, sy) {
    rect(sx + 6, sy + 9, 5, 8, '#875d42');
    rect(sx + 4, sy + 14, 9, 3, '#76513e');
    rect(sx + 1, sy + 5, 14, 7, '#39895c');
    rect(sx + 3, sy + 2, 10, 8, '#4b9b66');
    rect(sx + 5, sy, 6, 6, '#5aa873');
    rect(sx + 4, sy + 4, 2, 2, '#82c585');
    rect(sx + 11, sy + 7, 2, 2, '#65b477');
  }

  function drawBuilding(b, cameraX, cameraY) {
    const x = b.x * T - cameraX, y = b.y * T - cameraY, w = b.w * T, h = b.h * T;
    if (b.type === 'corner') {
      // Neon Rocket Game Corner building
      rect(x + 2, y + 8, w - 4, h - 7, '#2d233b');
      rect(x, y + 4, w, 9, '#5e2750');
      for (let i = 0; i < b.w; i++) {
        rect(x + i * T + 1, y + 5, 7, 5, i % 2 === 0 ? '#e04848' : '#f6cb49');
      }
      rect(x + 6, y + 15, w - 12, h - 18, '#3d2f52');
      // Slot machine display windows
      rect(x + 8, y + 19, 20, 14, '#1b1426');
      pixelText('777', x + 18, y + 22, 6, '#f6cb49', 'center');
      rect(x + w - 28, y + 19, 20, 14, '#1b1426');
      pixelText('R·R', x + w - 18, y + 22, 6, '#ff6b6b', 'center');
      // Entrance door
      rect(x + w / 2 - 7, y + h - 18, 14, 18, '#d94848');
      rect(x + w / 2 - 5, y + h - 16, 10, 14, '#f6cb49');
      rounded(x + w / 2 - 34, y - 4, 68, 12, 3, '#1d1326');
      pixelText('🎰 GAME CORNER', x + w / 2, y - 1, 7, '#f6cb49', 'center');
    } else if (b.type === 'daycare') {
      // Cozy Creature Daycare cottage + playpen
      rect(x + 2, y + 8, w - 4, h - 7, '#f1dfbd');
      rect(x, y + 5, w, 8, '#66a97b');
      for (let i = 0; i < b.w; i++) {
        rect(x + i * T + 1, y + 5, 7, 5, '#82c596');
      }
      rect(x + w / 2 - 6, y + h - 17, 12, 17, '#896248');
      rect(x + 7, y + 18, 14, 11, '#72aab4');
      rect(x + w - 21, y + 18, 14, 11, '#72aab4');
      rounded(x + w / 2 - 28, y - 4, 56, 12, 3, '#fff2c7');
      pixelText('🥚 DAYCARE', x + w / 2, y - 1, 7, '#356346', 'center');
    } else {
      rect(x + 3, y + 8, w, h - 7, '#d7c6a2');
      rect(x, y + 5, w, 7, '#d78363');
      rect(x + 6, y + 14, w - 12, h - 19, '#f1dfbd');
      rect(x + w / 2 - 5, y + h - 17, 10, 17, '#896248');
    }
  }

  function drawPerson(px, py, type, frame = 0) {
    const x = Math.round(px), y = Math.round(py);
    if (type === 'hero') {
      // Team Rocket Grunt playable character: dark uniform, crimson 'R' chest emblem, black cap with red visor
      rect(x - 6, y + 9, 13, 3, 'rgba(0,0,0,0.3)');
      rect(x - 5, y - 8, 10, 9, '#f0c79c');
      rect(x - 6, y - 12, 12, 5, '#232730');
      rect(x - 4, y - 9, 9, 2, '#e04848');
      rect(x - 6, y, 12, 8, '#262b36');
      // Red 'R' on chest
      rect(x - 2, y + 2, 4, 4, '#e04848');
      rect(x - 5, y + 7, 4, 5, '#1b1f26');
      rect(x + 2, y + 7, 4, 5, '#1b1f26');
      if (frame % 2) {
        rect(x - 7, y + 11, 4, 2, '#14171d');
        rect(x + 2, y + 11, 4, 2, '#14171d');
      }
    } else if (type === 'vex') {
      // Commander Vex: Maroon/Gold Team Rocket Officer coat
      rect(x - 6, y + 9, 13, 3, 'rgba(0,0,0,0.35)');
      rect(x - 5, y - 8, 10, 9, '#ecc39a');
      rect(x - 7, y - 12, 14, 5, '#591e29');
      rect(x - 5, y - 9, 10, 2, '#f6cb49');
      rect(x - 7, y, 14, 9, '#3d1c26');
      rect(x - 2, y + 2, 4, 5, '#f6cb49');
      rect(x - 5, y + 8, 4, 4, '#24151c');
      rect(x + 2, y + 8, 4, 4, '#24151c');
    } else if (type === 'rocketRival') {
      // Team Rocket Rival: Violet/Black elite recruit uniform
