  function nearbyInteraction() {
    for (const key of Object.keys(npcs)) {
      const n = npcs[key];
      if (Math.abs(game.x - n.x) + Math.abs(game.y - n.y) <= 2) return n.role;
    }
    if (tileType(game.x, game.y) === 'tall') return 'tall';
    return null;
  }

  function drawMap() {
    const camX = clamp(game.x * T - W / 2 + 8, 0, mapW * T - W);
    const camY = clamp(game.y * T - H / 2 + 8, 0, mapH * T - H);
    const startX = Math.floor(camX / T), startY = Math.floor(camY / T);

    for (let ty = startY; ty <= startY + H / T; ty++) {
      for (let tx = startX; tx <= startX + W / T; tx++) {
        drawTerrain(tx, ty, tx * T - camX, ty * T - camY);
      }
    }

    drawRundownBaseDetails(camX, camY);

    for (let y = startY; y <= startY + H / T; y++) {
      for (let x = startX; x <= startX + W / T; x++) {
        if (tileType(x, y) === 'grass' && (x * 7 + y * 13) % 31 === 0) {
          rect(x * T - camX + 7, y * T - camY + 8, 2, 2, '#f3d16a');
          rect(x * T - camX + 9, y * T - camY + 7, 2, 2, '#fff0c1');
        }
      }
    }

    buildings.forEach(b => drawBuilding(b, camX, camY));
    trees.forEach(([x, y]) => drawTree(x * T - camX, y * T - camY));

    // Daycare fenced playpen with a happy daycare creature
    for (let x = 8; x < 11; x++) {
      const fx = x * T - camX, fy = 14 * T - camY;
      rect(fx, fy, 2, 8, '#ae8858');
      rect(fx + 7, fy, 2, 8, '#ae8858');
      rect(fx, fy + 2, 9, 2, '#c29a66');
    }
    drawWild(creatures[0], 9 * T + 8 - camX, 13 * T + 8 - camY, 0.45);

    // Draw NPCs with name/role overheads
    Object.values(npcs).forEach(n => {
      const nx = n.x * T + 8 - camX;
      const ny = n.y * T + 8 - camY;
      if (nx > -20 && nx < W + 20 && ny > -20 && ny < H + 20) {
        drawPerson(nx, ny, n.role, game.anim >> 8);
        let tag = '';
        if (n.role === 'vex') tag = 'CMDR. VEX';
        else if (n.role === 'rocketRival') tag = game.rocketRival;
        else if (n.role === 'heroRival') tag = game.heroRival;
        else if (n.role === 'cornerBoss') tag = 'SLOTS BOSS';
        else if (n.role === 'daycareKeeper') tag = 'DAYCARE';
        if (tag) {
          rounded(nx - 24, ny - 23, 48, 9, 2, '#141d2bd8');
          pixelText(tag, nx, ny - 22, 6, '#f6cb49', 'center');
        }
      }
    });

    // Companion Voltkit follows behind the Grunt
    const buddy = game.buddyTrail[0] || { x: game.x, y: game.y + 1 };
    drawVolt(buddy.x * T + 8 - camX, buddy.y * T + 8 - camY, 0.72);
    drawPerson(game.x * T + 8 - camX, game.y * T + 8 - camY, 'hero', game.anim >> 7);

    // Top-left Area & Rank HUD overlay on canvas
    rounded(6, 6, 152, 26, 3, '#172230e6');
    pixelText(currentAreaName(), 11, 9, 7, '#fff3d4');
    pixelText(`${game.playerName} • ${RANKS[game.rankIndex].title}`, 11, 20, 6, '#f6cb49');

    // Top-right Funds & Orbs overlay on canvas
    rounded(W - 114, 6, 108, 17, 3, '#172230e6');
    pixelText(`₽${game.funds}  •  ORBS ×${game.orbs}`, W - 60, 11, 7, '#9be5aa', 'center');

    // Context interaction prompt at bottom right
    const near = nearbyInteraction();
    if (near) {
      let promptText = 'SPACE · INTERACT';
      if (near === 'vex') promptText = 'SPACE · REPORT / RANK UP';
      else if (near === 'rocketRival') promptText = `SPACE · BATTLE ${game.rocketRival}`;
      else if (near === 'heroRival') promptText = `SPACE · BATTLE ${game.heroRival}`;
      else if (near === 'cornerBoss') promptText = 'SPACE · PLAY SLOTS / WORK';
      else if (near === 'daycareKeeper') promptText = 'SPACE · WORK DAYCARE SHIFT';
      else if (near === 'tall') promptText = 'SPACE · SEARCH TALL GRASS';
      rounded(W - 166, H - 24, 160, 18, 3, '#172230eb');
      pixelText(promptText, W - 86, H - 18, 6, '#f6cb49', 'center');
    }
  }

  function drawIntroScene() {
    // Background scene inside the Rundown Team Rocket Base while the naming dossier is open
    rect(0, 0, W, H, '#1e2430');
    for (let y = 0; y < H; y += T) {
      for (let x = 0; x < W; x += T) {
        rect(x, y, T - 1, T - 1, (x + y) % 32 === 0 ? '#283040' : '#232a38');
      }
    }
    // Red Rocket Banner and characters preview
    rounded(14, 10, W - 28, 32, 4, '#2b1822');
    pixelText('TEAM ROCKET OUTPOST #07 — RUNDOWN BASE', W / 2, 16, 8, '#ff7a72', 'center');
    pixelText(`RECRUIT: ${game.playerName}   |   ROCKET RIVAL: ${game.rocketRival}   |   HERO RIVAL: ${game.heroRival}`, W / 2, 29, 6, '#f6cb49', 'center');

    drawPerson(84, 182, 'hero', 0);
    drawVolt(106, 185, 0.85);
    drawPerson(192, 182, 'rocketRival', 0);
    drawPerson(298, 182, 'heroRival', 0);
  }

