  function drawBattle() {
    const b = game.battle;
    if (!b) return;
    rect(0, 0, W, H, '#b6d6c3');
    rect(0, 0, W, 107, b.trainer ? '#2f283b' : '#b6d7ce');
    rect(0, 104, W, 112, b.trainer ? '#473e57' : '#8dc096');
    rect(0, 108, W, 4, b.trainer ? '#6d5b82' : '#c3d9b4');

    ctx.fillStyle = b.trainer ? '#5d4c73' : '#78aa7d';
    ctx.beginPath(); ctx.ellipse(281, 108, 66, 13, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = b.trainer ? '#4e3f61' : '#6b9b75';
    ctx.beginPath(); ctx.ellipse(93, 169, 77, 15, 0, 0, Math.PI * 2); ctx.fill();

    // Opponent info panel
    rounded(12, 11, 174, 42, 4, '#f8f4e5');
    pixelText(b.trainer ? `${b.trainer}: ${b.enemy.name}` : b.enemy.name, 20, 18, 8, '#354352');
    pixelText(`Lv.${b.enemy.level}`, 178, 18, 8, '#667281', 'right');
    pixelText('HP', 20, 35, 7, '#687686');
    rect(38, 36, 136, 5, '#d8d6c8');
    rect(38, 36, Math.max(1, 136 * b.enemy.hp / b.enemy.maxHp), 5, b.enemy.hp / b.enemy.maxHp < 0.25 ? '#e26f5e' : '#8fc388');
    drawWild(b.enemy, 282, 89, 1.05);

    // Player & Voltkit info panel
    rounded(198, 131, 176, 45, 4, '#f8f4e5');
    pixelText(`${game.playerName}'S VOLTKIT`, 207, 138, 8, '#354352');
    pixelText(`Lv.${game.level}`, 366, 138, 8, '#667281', 'right');
    pixelText(`${game.hp} / ${game.maxHp}`, 366, 152, 7, '#667281', 'right');
    rect(207, 164, 159, 5, '#d8d6c8');
    rect(207, 164, Math.max(1, 159 * game.hp / game.maxHp), 5, game.hp / game.maxHp < 0.25 ? '#e26f5e' : '#8fc388');
    drawVolt(91, 145, 1.12);

    // Dialogue / Action menu strip
    rect(0, 184, W, 32, '#f4f0df');
    rect(0, 184, W, 2, '#d0c7a8');
    if (b.phase === 'menu') {
      pixelText(`ORDERS FOR VOLTKIT (${RANKS[game.rankIndex].title}):`, 10, 189, 7, '#536272');
      const opts = [
        ['1 SPARK', '⚡'],
        ['2 TAIL WHIP', '↝'],
        [`3 RATION ×${game.potions}`, '+'],
        [b.trainer ? '4 TAUNT' : `4 ORB ×${game.orbs}`, '○']
      ];
      opts.forEach((o, i) => {
        const x = 8 + i * 94;
        rounded(x, 200, 88, 13, 2, '#fffdf3');
        pixelText(o[0], x + 5, 203, 6, '#28394a');
      });
    } else {
      pixelText(b.message || 'Ready for battle!', 10, 191, 7, '#354352');
      pixelText('SPACE · CONTINUE', 374, 203, 6, '#7b817b', 'right');
    }
  }

  function drawSlotsMiniGame() {
    const s = game.slots;
    // Arcade cabinet backdrop
    rect(0, 0, W, H, '#1b1224');
    for (let i = 0; i < W; i += 24) {
      rect(i, 0, 12, H, '#22172d');
    }
    // Cabinet frame
    rounded(18, 8, W - 36, 170, 8, '#461e38');
    rounded(24, 13, W - 48, 160, 6, '#281526');

    // Marquee Header
    rounded(34, 18, W - 68, 24, 4, '#e04848');
    pixelText('★ TEAM ROCKET GAME CORNER SLOTS ★', W / 2, 23, 8, '#fff7d6', 'center');
    pixelText(`GRUNT ${game.playerName}  •  FUNDS: ₽${game.funds}  •  SHIFTS WORKED: ${game.cornerShifts}`, W / 2, 33, 6, '#ffe066', 'center');

    // 3 Slot Machine Reels
    const reelW = 86, reelH = 74, startX = 48, reelY = 50;
    for (let i = 0; i < 3; i++) {
      const rx = startX + i * (reelW + 15);
      rounded(rx - 3, reelY - 3, reelW + 6, reelH + 6, 5, s.locked[i] ? '#f6cb49' : '#ff6b6b');
      rounded(rx, reelY, reelW, reelH, 4, '#f8f4e5');

      const symIndex = s.locked[i]
        ? s.reels[i]
        : Math.floor((game.anim * 0.025 + i * 2) % SLOT_SYMBOLS.length);
      const sym = SLOT_SYMBOLS[symIndex];

      rounded(rx + 6, reelY + 6, reelW - 12, reelH - 12, 4, sym.bg);
      pixelText(sym.label, rx + reelW / 2, reelY + 15, 24, sym.color, 'center');
      pixelText(sym.name, rx + reelW / 2, reelY + 51, 7, '#f4f1e7', 'center');
    }

    // Payout Legend Bar
    rounded(34, 132, W - 68, 34, 4, '#180d17');
    pixelText('3× R = +₽300 & +35 MERITS   |   3× 7 = +₽240 & +30 MERITS   |   ANY PAIR = +₽90 & +15 MERITS', W / 2, 137, 6, '#f6cb49', 'center');
    pixelText(s.rigged ? 'MAGNET RIG ACTIVE: NEXT SPIN GUARANTEED JACKPOT!' : s.banner, W / 2, 151, 6, s.rigged ? '#8ef0c0' : '#ffffff', 'center');

    // Bottom interactive control strip
    rect(0, 184, W, 32, '#f4f0df');
    rect(0, 184, W, 2, '#d0c7a8');
    pixelText('GAME CORNER CONTROLS (CLICK OR PRESS 1-4 / SPACE):', 10, 188, 6, '#536272');
    const btns = [
      s.spinning ? '1 STOP REEL' : '1 SPIN (₽10)',
      '2 WORK / RIG (+₽100)',
      '3 BUY ORB (₽80)',
      '4 EXIT TO MAP'
    ];
    btns.forEach((label, i) => {
      const bx = 7 + i * 94;
      rounded(bx, 198, 90, 14, 3, i === 0 ? '#f6cb49' : i === 1 ? '#e04848' : '#28394a');
      pixelText(label, bx + 45, 202, 6, i === 0 ? '#17263a' : '#ffffff', 'center');
    });
  }

  function render() {
    ctx.clearRect(0, 0, W, H);
    if (game.mode === 'intro') drawIntroScene();
    else if (game.mode === 'map') drawMap();
    else if (game.mode === 'battle') drawBattle();
    else if (game.mode === 'slots') drawSlotsMiniGame();
  }

  function showToast(text) {
    ui.toast.textContent = text;
    ui.toast.classList.add('show');
    clearTimeout(game.toastTimer);
    game.toastTimer = setTimeout(() => ui.toast.classList.remove('show'), 2400);
  }

  function addMerits(amount, reason) {
    game.merits += amount;
    let promoted = false;
    while (game.rankIndex < RANKS.length - 1 && game.merits >= RANKS[game.rankIndex].nextMerits) {
      game.rankIndex++;
      game.maxHp += 4;
      game.hp = game.maxHp;
      game.orbs += 1;
      promoted = true;
    }
    if (promoted) {
      const newRank = RANKS[game.rankIndex].title;
      showToast(`★ PROMOTED TO ${newRank}! (+4 Max HP, +1 Rocket Orb)`);
    } else if (reason) {
      showToast(`${reason} (+${amount} Rocket Merits)`);
    }
    updateUI();
  }

  function updateUI() {
    const rankObj = RANKS[game.rankIndex];
    ui.level.textContent = game.level;
    ui.hpBar.style.width = `${clamp((100 * game.hp) / game.maxHp, 0, 100)}%`;
    ui.hpText.textContent = `${game.hp} / ${game.maxHp}`;
    ui.buddyCount.textContent = String(1 + game.caught).padStart(2, '0');
    ui.wins.textContent = String(game.wins + game.cornerShifts + game.daycareShifts).padStart(2, '0');
    ui.area.textContent = currentAreaName();
    ui.status.textContent = game.message;

    ui.playerNameDisplay.textContent = `GRUNT ${game.playerName}`;
    ui.rocketRivalDisplay.textContent = game.rocketRival;
    ui.heroRivalDisplay.textContent = game.heroRival;

    ui.rankDisplay.textContent = rankObj.title;
    ui.rankTierPill.textContent = `RANK ${game.rankIndex + 1} / ${RANKS.length}`;
    if (game.rankIndex < RANKS.length - 1) {
      ui.meritDisplay.textContent = `${game.merits} / ${rankObj.nextMerits} MERITS`;
      const pct = clamp(((game.merits - rankObj.minMerits) / (rankObj.nextMerits - rankObj.minMerits)) * 100, 6, 100);
      ui.rankBar.style.width = `${pct}%`;
    } else {
      ui.meritDisplay.textContent = `${game.merits} MERITS (MAX)`;
      ui.rankBar.style.width = '100%';
    }

    ui.gruntCallsign.textContent = `GRUNT ${game.playerName} • ${rankObj.title}`;
    ui.jobLedger.textContent = `FUNDS: ₽${game.funds} • SHIFTS: ${game.cornerShifts + game.daycareShifts}`;
    ui.fundsReadout.textContent = `FUNDS: ₽${game.funds} • ORBS: ${game.orbs}`;

    // Dynamic objective & field note
    if (game.rankIndex >= 4) {
      ui.goal.textContent = `Executive status achieved! Keep running Sunmeadow with Voltkit.`;
      ui.goalCheck.textContent = '✓';
      ui.progress.style.width = '100%';
    } else if (game.cornerShifts === 0 && game.daycareShifts === 0) {
      ui.goal.textContent = `Work shifts at the Game Corner & Daycare or battle ${game.rocketRival} & ${game.heroRival}`;
      ui.goalCheck.textContent = '○';
      ui.progress.style.width = `${clamp(15 + game.merits, 15, 95)}%`;
    } else {
      ui.goal.textContent = `Earn ${rankObj.nextMerits} Merits to rank up to ${RANKS[game.rankIndex + 1].title}`;
      ui.goalCheck.textContent = '★';
      ui.progress.style.width = `${clamp(25 + game.merits, 25, 98)}%`;
    }

    ui.noteTitle.textContent = `DOSSIER: ${game.playerName} VS ${game.rocketRival} & ${game.heroRival}`;
    ui.note.textContent = `Rocket Rival ${game.rocketRival} wants your promotion in the Rundown Base, while protagonist ${game.heroRival} patrols outside.`;

    if (game.mode === 'intro') ui.action.textContent = 'CONFIRM NAMES';
    else if (game.mode === 'battle') ui.action.textContent = 'BATTLE ACT';
    else if (game.mode === 'slots') ui.action.textContent = game.slots.spinning ? 'STOP REEL' : 'SPIN SLOTS';
    else ui.action.textContent = 'INTERACT / TALK';
  }

  function sanitizeName(val, fallback) {
    const cleaned = (val || '').trim().toUpperCase().replace(/[^A-Z0-9 _-]/g, '').slice(0, 10);
    return cleaned || fallback;
  }

  function confirmIntroNames(e) {
    if (e) e.preventDefault();
    game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
    game.rocketRival = sanitizeName(ui.rocketRivalInput.value, 'VIPER');
    game.heroRival = sanitizeName(ui.heroRivalInput.value, 'RED');

    ui.playerInput.value = game.playerName;
    ui.rocketRivalInput.value = game.rocketRival;
    ui.heroRivalInput.value = game.heroRival;

    ui.introOverlay.hidden = true;
    if (game.mode === 'intro') {
      game.mode = 'map';
    }
    game.message = `Grunt ${game.playerName} deployed in the Rundown Rocket Base! Rival ${game.rocketRival} is by the lockers; ${game.heroRival} is in town.`;
    showToast(`Deployed as Grunt ${game.playerName}! Rivals: ${game.rocketRival} & ${game.heroRival}`);
    updateUI();
  }

  function openIntroModal() {
    ui.playerInput.value = game.playerName;
    ui.rocketRivalInput.value = game.rocketRival;
    ui.heroRivalInput.value = game.heroRival;
    ui.introOverlay.hidden = false;
    game.mode = 'intro';
    updateUI();
  }

  // Slot Machine Mini-Game Functions
  function openGameCornerSlots() {
    if (game.mode === 'intro') confirmIntroNames();
    // Move player to Game Corner door if outside
    game.x = 16;
    game.y = 9;
    game.facing = 'up';
    game.mode = 'slots';
    game.slots.spinning = false;
    game.slots.locked = [true, true, true];
    game.slots.banner = 'PRESS SPACE/1 TO SPIN (₽10) OR 2 TO WORK SHIFT & RIG JACKPOT!';
    game.message = `Grunt ${game.playerName} stepped up to the Rocket Game Corner slot machine!`;
    updateUI();
  }

  function startOrStopSlotSpin() {
    const s = game.slots;
    if (s.spinning) {
      // Manual stop next unlocked reel immediately
      const nextIdx = s.locked.findIndex(locked => !locked);
      if (nextIdx !== -1) {
        lockReel(nextIdx);
      }
      return;
    }
    if (game.funds < 10 && !s.rigged) {
      // Automatically work a quick floor shift if broke
      workGameCornerShift();
      return;
    }
    if (!s.rigged) game.funds -= 10;
    s.spinning = true;
    s.spins++;
    s.locked = [false, false, false];
    const now = performance.now();
    s.stopTimes = [now + 320, now + 620, now + 920];
    s.banner = 'REELS SPINNING... PRESS SPACE OR CLICK TO LOCK REELS!';
    updateUI();
  }

  function lockReel(idx) {
    const s = game.slots;
    if (s.locked[idx]) return;
    s.locked[idx] = true;
    if (s.rigged) {
      // Rigged shift guarantees 3x Rocket 'R' or 3x '7'
      s.reels[idx] = 0;
    } else if (idx > 0 && Math.random() < 0.48) {
      // Friendly arcade odds so matching reels is common and fun
      s.reels[idx] = s.reels[0];
    } else {
      s.reels[idx] = rnd(0, SLOT_SYMBOLS.length - 1);
    }

    if (s.locked.every(Boolean)) {
      finishSlotSpin();
    }
  }

  function finishSlotSpin() {
    const s = game.slots;
    s.spinning = false;
    const [r0, r1, r2] = s.reels;
    const sym0 = SLOT_SYMBOLS[r0];
    if (r0 === r1 && r1 === r2) {
      const winFunds = sym0.payout;
      game.funds += winFunds;
      if (sym0.orb) game.orbs += sym0.orb;
      s.lastWin = winFunds;
      s.rigged = false;
      s.banner = `JACKPOT! 3× ${sym0.name}! WON +₽${winFunds}${sym0.orb ? ' & +1 ROCKET ORB' : ''}!`;
      game.message = `Slot Jackpot at the Game Corner! Won +₽${winFunds} and +${sym0.merits} Merits!`;
      addMerits(sym0.merits, `Slot Jackpot (3× ${sym0.name})`);
    } else if (r0 === r1 || r1 === r2 || r0 === r2) {
      const pairSym = r0 === r1 ? SLOT_SYMBOLS[r0] : SLOT_SYMBOLS[r2];
      const winFunds = 90;
      game.funds += winFunds;
      s.lastWin = winFunds;
      s.rigged = false;
      s.banner = `NICE MATCH! PAIR OF ${pairSym.name}S! WON +₽${winFunds} & +15 MERITS!`;
      game.message = `Matched a pair of ${pairSym.name}s on the Game Corner slots! +₽${winFunds}.`;
      addMerits(15, 'Game Corner Slot Match');
    } else {
      s.lastWin = 0;
      s.rigged = false;
      s.banner = 'NO MATCH! PRESS 2 TO WORK SHIFT & RIG THE MACHINE FOR A JACKPOT!';
      game.message = 'Reels missed! Tip: Work a Game Corner shift (2) to rig the next spin!';
      updateUI();
    }
  }

  function workGameCornerShift() {
    if (game.mode === 'intro') confirmIntroNames();
    game.cornerShifts++;
    game.funds += 100;
    game.slots.rigged = true;
    game.slots.banner = 'SHIFT WORKED (+₽100)! MAGNET RIGGED: SPIN NOW FOR GUARANTEED 3× R JACKPOT!';
    game.message = `Grunt ${game.playerName} worked a shift at the Rocket Game Corner (+₽100, +25 Merits) and rigged the slot machine!`;
    addMerits(25, 'Worked Game Corner Shift');
    if (game.mode !== 'slots') {
      openGameCornerSlots();
    }
  }

  function workDaycareShift() {
    if (game.mode === 'intro') confirmIntroNames();
    if (game.mode === 'slots') game.mode = 'map';
    game.x = 5;
    game.y = 17;
    game.facing = 'up';
    game.daycareShifts++;
    game.funds += 120;
    game.hp = game.maxHp;
    game.xp += 16;
    let leveled = false;
    if (game.xp >= 24) {
      game.xp -= 24;
      game.level++;
      game.maxHp += 3;
      game.hp = game.maxHp;
      leveled = true;
    }
    game.message = `Grunt ${game.playerName} worked a shift at the Creature Daycare! Earned +₽120, Voltkit healed${leveled ? ` & reached Lv.${game.level}` : ' (+16 XP)'}!`;
    addMerits(25, 'Worked Daycare Shift');
  }

  function reportForPromotion() {
    if (game.mode === 'intro') confirmIntroNames();
    if (game.mode === 'slots') game.mode = 'map';
    const prevRank = game.rankIndex;
    const needed = RANKS[game.rankIndex].nextMerits - game.merits;
    const grant = Math.max(25, needed);
    game.talkedVex = true;
    addMerits(grant, 'Commander Vex Commendation');
    const newRankTitle = RANKS[game.rankIndex].title;
    if (game.rankIndex > prevRank) {
      game.message = `Commander Vex: “Outstanding work, ${game.playerName}! You are officially promoted to ${newRankTitle}! Take that, ${game.rocketRival}!”`;
    } else {
      game.message = `Commander Vex: “You've reached the top rank of ${newRankTitle}, ${game.playerName}! This rundown base is yours to command.”`;
    }
    updateUI();
  }

  function move(dir) {
    if (game.mode !== 'map') return;
    const delta = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }[dir];
    if (!delta) return;
    game.facing = dir;
    const nx = game.x + delta[0], ny = game.y + delta[1];
    if (!solid(nx, ny)) {
      game.buddyTrail.unshift({ x: game.x, y: game.y });
      if (game.buddyTrail.length > 4) game.buddyTrail.pop();
      game.x = nx;
      game.y = ny;
      game.steps++;
      if (tileType(game.x, game.y) === 'tall' && game.grassEncounterCooldown <= 0 && Math.random() < 0.2) {
        game.grassEncounterCooldown = 6;
        beginWildBattle();
      }
      updateUI();
    } else {
      const hitNpc = npcAt(nx, ny);
      if (hitNpc) interactWithRole(hitNpc.role);
    }
  }

  function interactWithRole(role) {
    if (role === 'vex') {
      reportForPromotion();
    } else if (role === 'rocketRival') {
      beginRivalBattle('rocket');
    } else if (role === 'heroRival') {
      beginRivalBattle('hero');
    } else if (role === 'cornerBoss') {
      openGameCornerSlots();
    } else if (role === 'daycareKeeper') {
      workDaycareShift();
    } else if (role === 'tall') {
      beginWildBattle();
    }
  }

  function interact() {
    if (game.mode === 'intro') {
      confirmIntroNames();
      return;
    }
    if (game.mode === 'slots') {
      startOrStopSlotSpin();
      return;
    }
    if (game.mode === 'battle') {
      battleContinue();
      return;
    }
    if (game.mode !== 'map') return;
    const near = nearbyInteraction();
    if (near) {
      interactWithRole(near);
    } else {
      game.message = `Grunt ${game.playerName} (${RANKS[game.rankIndex].title}) patrols ${currentAreaName()} with Voltkit.`;
      updateUI();
    }
  }

  function beginWildBattle() {
    const base = creatures[rnd(0, creatures.length - 1)];
    const enemy = {
      ...base,
      level: rnd(2, Math.max(3, game.level)),
      maxHp: base.hp + rnd(0, 4)
    };
    enemy.hp = enemy.maxHp;
    game.mode = 'battle';
    game.battle = {
      trainer: null,
      rivalKind: null,
      enemy,
      phase: 'intro',
      message: `A wild ${enemy.name} ambushed Grunt ${game.playerName} in the tall grass!`,
      turn: 0
    };
    game.message = game.battle.message;
    updateUI();
  }

  function beginRivalBattle(kind) {
    const isRocket = kind === 'rocket';
    const trainerName = isRocket ? `ROCKET RIVAL ${game.rocketRival}` : `HERO RIVAL ${game.heroRival}`;
    const enemy = isRocket
      ? { name: 'SHADEFANG', kind: 'SHADOW', color: '#8d73b8', accent: '#553c7a', level: game.level, maxHp: 24, hp: 24 }
      : { name: 'SOLFLARE', kind: 'HERO FLAME', color: '#f2915c', accent: '#c94a38', level: game.level + 1, maxHp: 26, hp: 26 };
    game.mode = 'battle';
    game.battle = {
      trainer: trainerName,
      rivalKind: kind,
      enemy,
      phase: 'intro',
      message: isRocket
        ? `${game.rocketRival}: “Out of my way, ${game.playerName}! Only one of us is ranking up in Team Rocket!”`
        : `${game.heroRival}: “Hold it, Team Rocket Grunt ${game.playerName}! I'm shutting down your outpost!”`,
      turn: 0
    };
    game.message = game.battle.message;
    updateUI();
  }

  function enemyTurn() {
    const b = game.battle;
    if (!b || game.mode !== 'battle') return;
    const damage = rnd(2, 5);
    game.hp = Math.max(1, game.hp - damage); // Voltkit hangs on with grit
    b.phase = 'enemyMsg';
    b.message = `${b.enemy.name} struck back! Voltkit took −${damage} HP.`;
    game.message = b.message;
    updateUI();
  }

  function attack(kind) {
    const b = game.battle;
    if (!b || b.phase !== 'menu') return;
    if (kind === 'snack') {
      if (game.potions <= 0) {
        b.phase = 'enemyMsg';
        b.message = 'No Rations left in your Rocket kit!';
        return;
      }
      game.potions--;
      const healed = Math.min(16, game.maxHp - game.hp);
      game.hp += healed;
      b.phase = 'enemyMsg';
      b.message = `Voltkit ate a Rocket Ration! Restored +${healed || 1} HP.`;
      updateUI();
      return;
    }
    if (kind === 'orb') {
      if (b.trainer) {
        // In rival battle, 4th slot is Taunt (+attack morale & slight weaken)
        const chip = 5 + game.rankIndex;
        b.enemy.hp = Math.max(1, b.enemy.hp - chip);
        b.phase = 'enemyMsg';
        b.message = `${game.playerName} taunted ${b.trainer}! ${b.enemy.name} lost composure (−${chip} HP)!`;
        b.pendingEnemy = true;
        return;
      }
      if (game.orbs <= 0) {
        b.phase = 'enemyMsg';
        b.message = 'Out of Rocket Orbs! Win more at the Game Corner!';
        return;
      }
      game.orbs--;
      b.phase = 'enemyMsg';
      b.message = `Grunt ${game.playerName} threw a Rocket Orb at wild ${b.enemy.name}...`;
      b.pendingCapture = true;
      updateUI();
      return;
    }

    const damage = (kind === 'spark' ? rnd(9, 13) : rnd(6, 10)) + game.level + game.rankIndex * 2;
    b.enemy.hp = Math.max(0, b.enemy.hp - damage);
    b.turn++;
    if (b.enemy.hp <= 0) {
      game.wins++;
      game.xp += 14;
      game.funds += b.trainer ? 140 : 60;
      if (game.xp >= 24) {
        game.xp -= 24;
        game.level++;
        game.maxHp += 3;
        game.hp = game.maxHp;
      }
      b.phase = 'winMsg';
      if (b.rivalKind === 'rocket') {
        game.defeatedRocketRival = true;
        b.message = `Defeated Rocket Rival ${game.rocketRival}! Earned +₽140 & +40 Merits!`;
      } else if (b.rivalKind === 'hero') {
        game.defeatedHeroRival = true;
        b.message = `Defeated Protagonist Rival ${game.heroRival}! Earned +₽140 & +40 Merits!`;
      } else {
        b.message = `Wild ${b.enemy.name} fainted! Earned +₽60 & +25 Merits!`;
      }
      game.message = b.message;
      addMerits(b.trainer ? 40 : 25, b.trainer ? `Defeated ${b.trainer}` : `Defeated ${b.enemy.name}`);
    } else {
      b.phase = 'enemyMsg';
      b.message = `Voltkit used ${kind === 'spark' ? 'THUNDER SPARK' : 'TAIL WHIP'}! −${damage} HP to ${b.enemy.name}!`;
      b.pendingEnemy = true;
    }
    updateUI();
  }

  function battleContinue() {
    const b = game.battle;
    if (!b) return;
    if (b.phase === 'intro') {
      b.phase = 'menu';
      return;
    }
    if (b.phase === 'enemyMsg') {
      if (b.pendingCapture) {
        b.pendingCapture = false;
        game.caught++;
        game.wins++;
        game.funds += 80;
        const caughtName = b.enemy.name;
        game.mode = 'map';
        game.battle = null;
        game.grassEncounterCooldown = 7;
        game.message = `Captured ${caughtName} with a Rocket Orb! Added to ${game.playerName}'s squad!`;
        addMerits(35, `Captured ${caughtName}`);
        return;
      }
      if (b.pendingEnemy) {
        b.pendingEnemy = false;
        enemyTurn();
        return;
      }
      b.phase = 'menu';
      return;
    }
    if (b.phase === 'winMsg') {
      game.mode = 'map';
      game.battle = null;
      game.grassEncounterCooldown = 7;
      updateUI();
    }
  }

  function keyDown(e) {
    // Allow typing inside name inputs when focused
    if (document.activeElement && document.activeElement.tagName === 'INPUT') {
      if (e.key === 'Enter') {
        confirmIntroNames(e);
      }
      return;
    }

    const key = e.key.toLowerCase();
    if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' ', 'enter'].includes(key)) {
      e.preventDefault();
    }
    if (game.keys[key]) return;
    game.keys[key] = true;

    if (game.mode === 'intro') {
      if (key === 'enter' || key === ' ') confirmIntroNames(e);
      return;
    }

    if (game.mode === 'slots') {
      if (key === '1' || key === ' ' || key === 'enter' || key === 'z') startOrStopSlotSpin();
      else if (key === '2' || key === 'r') workGameCornerShift();
      else if (key === '3') {
        if (game.funds >= 80) {
          game.funds -= 80;
          game.orbs++;
          game.slots.banner = 'EXCHANGED ₽80 FOR +1 ROCKET ORB!';
          showToast('Purchased +1 Rocket Orb at Game Corner!');
          updateUI();
        } else {
          game.slots.banner = 'NEED ₽80 FOR AN ORB! WORK A SHIFT (2) FOR +₽100!';
        }
      } else if (key === '4' || key === 'escape' || key === 'x') {
        game.mode = 'map';
        game.message = `Stepped out of the Rocket Game Corner with ₽${game.funds}.`;
        updateUI();
      }
      return;
    }

    if (game.mode === 'battle') {
      if (game.battle?.phase === 'menu') {
        if (key === '1' || key === 'z' || key === ' ' || key === 'enter') attack('spark');
        else if (key === '2' || key === 'x') attack('tail');
        else if (key === '3') attack('snack');
        else if (key === '4') attack('orb');
      } else if (key === ' ' || key === 'enter' || key === 'z') {
        battleContinue();
      }
      return;
    }

    // Shortcuts for Game Corner (G), Daycare (C), and Rank Up (P)
    if (key === 'g') { openGameCornerSlots(); return; }
    if (key === 'c') { workDaycareShift(); return; }
    if (key === 'p') { reportForPromotion(); return; }

    const dirs = {
      arrowup: 'up', w: 'up',
      arrowdown: 'down', s: 'down',
      arrowleft: 'left', a: 'left',
      arrowright: 'right', d: 'right'
    };
    if (dirs[key]) move(dirs[key]);
    else if (key === ' ' || key === 'enter' || key === 'z') interact();
  }

  function keyUp(e) {
    game.keys[e.key.toLowerCase()] = false;
  }

  window.addEventListener('keydown', keyDown);
  window.addEventListener('keyup', keyUp);

  // Wire preset name buttons in the introduction dossier
  document.querySelectorAll('.preset-list').forEach(group => {
    const targetId = group.dataset.target;
    const inputEl = $(targetId);
    group.querySelectorAll('.name-preset-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        group.querySelectorAll('.name-preset-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        inputEl.value = btn.dataset.name;
        game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
        game.rocketRival = sanitizeName(ui.rocketRivalInput.value, 'VIPER');
        game.heroRival = sanitizeName(ui.heroRivalInput.value, 'RED');
        updateUI();
      });
    });
  });

  [ui.playerInput, ui.rocketRivalInput, ui.heroRivalInput].forEach(inp => {
    inp.addEventListener('input', () => {
      game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
      game.rocketRival = sanitizeName(ui.rocketRivalInput.value, 'VIPER');
      game.heroRival = sanitizeName(ui.heroRivalInput.value, 'RED');
      updateUI();
    });
  });

  ui.introForm.addEventListener('submit', confirmIntroNames);
  $('rename-toggle').addEventListener('click', openIntroModal);

  // D-Pad & Action Buttons
  document.querySelectorAll('.dpad-btn[data-dir]').forEach(btn => {
    const dir = btn.dataset.dir;
    btn.addEventListener('pointerdown', e => {
      e.preventDefault();
      if (game.mode === 'intro') confirmIntroNames();
      move(dir);
    });
  });

  $('action-button').addEventListener('click', () => {
    if (game.mode === 'battle' && game.battle?.phase === 'menu') attack('spark');
    else interact();
  });

  $('work-corner-button').addEventListener('click', () => openGameCornerSlots());
  $('work-daycare-button').addEventListener('click', () => workDaycareShift());
  $('rank-up-button').addEventListener('click', () => reportForPromotion());

  canvas.addEventListener('pointerdown', e => {
    const r = canvas.getBoundingClientRect();
    const x = ((e.clientX - r.left) * W) / r.width;
    const y = ((e.clientY - r.top) * H) / r.height;
    if (game.mode === 'slots') {
      if (y >= 192) {
        const slot = clamp(Math.floor(x / 96), 0, 3);
        if (slot === 0) startOrStopSlotSpin();
        else if (slot === 1) workGameCornerShift();
        else if (slot === 2) {
          if (game.funds >= 80) {
            game.funds -= 80;
            game.orbs++;
            game.slots.banner = 'EXCHANGED ₽80 FOR +1 ROCKET ORB!';
            updateUI();
          }
        } else {
          game.mode = 'map';
          updateUI();
        }
      } else {
        startOrStopSlotSpin();
      }
      return;
    }
    if (game.mode === 'battle') {
      if (game.battle?.phase === 'menu' && y > 195) {
        const slot = clamp(Math.floor(x / 96), 0, 3);
        attack(['spark', 'tail', 'snack', 'orb'][slot]);
      } else if (game.battle?.phase !== 'menu') {
        battleContinue();
      }
    } else if (game.mode === 'map' && nearbyInteraction()) {
      interact();
    }
  });

  $('sound-toggle').addEventListener('click', e => {
    game.sound = !game.sound;
    e.currentTarget.querySelector('span').textContent = game.sound ? 'Sound on' : 'Sound off';
    showToast(game.sound ? 'Sound is on' : 'Sound is off');
  });

  function loop(now) {
    const dt = Math.min(40, now - game.lastTime);
    game.lastTime = now;
    game.anim = now;

    if (game.mode === 'slots' && game.slots.spinning) {
      for (let i = 0; i < 3; i++) {
        if (!game.slots.locked[i] && now >= game.slots.stopTimes[i]) {
          lockReel(i);
        }
      }
    }

    if (game.mode === 'map') {
      game.moveClock += dt;
      if (game.grassEncounterCooldown > 0) game.grassEncounterCooldown -= dt / 1000;
      if (game.moveClock > 150) {
        let dir = null;
        if (game.keys.arrowup || game.keys.w) dir = 'up';
        else if (game.keys.arrowdown || game.keys.s) dir = 'down';
        else if (game.keys.arrowleft || game.keys.a) dir = 'left';
        else if (game.keys.arrowright || game.keys.d) dir = 'right';
        if (dir) {
          move(dir);
          game.moveClock = 0;
        }
      }
    }
    render();
    requestAnimationFrame(loop);
  }

  updateUI();
  requestAnimationFrame(loop);
})();

