  const mapW = 32, mapH = 26;
  const path = new Set();
  const addPath = (x1, y1, x2, y2) => {
    let x = x1, y = y1;
    path.add(`${x},${y}`);
    while (x !== x2) { x += Math.sign(x2 - x); path.add(`${x},${y}`); }
    while (y !== y2) { y += Math.sign(y2 - y); path.add(`${x},${y}`); }
  };

  // Connect Rundown Base doorway (7,9) past Rival Protagonist (7,11) to Daycare (5,16), Game Corner (16,8), and Tall Grass (21+)
  addPath(7, 9, 7, 16);
  addPath(5, 16, 12, 16);
  addPath(12, 19, 12, 8);
  addPath(12, 8, 18, 8);
  addPath(12, 12, 25, 12);

  const baseBounds = { x1: 2, y1: 2, x2: 11, y2: 9, doorX: 7, doorY: 9 };
  const grassAreas = [
    { x: 21, y: 7, w: 8, h: 4 },
    { x: 23, y: 13, w: 6, h: 7 },
    { x: 4, y: 19, w: 7, h: 4 }
  ];
  const ponds = [{ x: 25, y: 3, w: 5, h: 3 }];
  const solids = new Set();

  for (let x = 0; x < mapW; x++) { solids.add(`${x},0`); solids.add(`${x},${mapH - 1}`); }
  for (let y = 0; y < mapH; y++) { solids.add(`0,${y}`); solids.add(`${mapW - 1},${y}`); }

  // Rundown Team Rocket Base perimeter walls (leaving doorway at 7,9 open)
  for (let x = baseBounds.x1; x <= baseBounds.x2; x++) {
    solids.add(`${x},${baseBounds.y1}`);
    if (x !== baseBounds.doorX) solids.add(`${x},${baseBounds.y2}`);
  }
  for (let y = baseBounds.y1; y <= baseBounds.y2; y++) {
    solids.add(`${baseBounds.x1},${y}`);
    solids.add(`${baseBounds.x2},${y}`);
  }
  [[3, 3], [4, 3], [10, 3], [3, 8]].forEach(([cx, cy]) => solids.add(`${cx},${cy}`));

  const buildings = [
    { x: 14, y: 4, w: 6, h: 4, type: 'corner', label: 'GAME CORNER' },
    { x: 3, y: 12, w: 5, h: 4, type: 'daycare', label: 'DAYCARE' },
    { x: 17, y: 16, w: 5, h: 3, type: 'home', label: 'SUPPLY DEPOT' }
  ];
  buildings.forEach(b => {
    for (let y = b.y; y < b.y + b.h; y++)
      for (let x = b.x; x < b.x + b.w; x++)
        solids.add(`${x},${y}`);
  });

  const trees = [
    [22, 3], [23, 3], [24, 3], [29, 5], [29, 6], [29, 7], [30, 7],
    [28, 21], [29, 21], [30, 21], [12, 23], [13, 23], [14, 23], [15, 23],
    [16, 23], [17, 23], [18, 23], [19, 23], [20, 23], [21, 23], [22, 23],
    [23, 23], [24, 23], [25, 23], [26, 23], [27, 23], [28, 23], [29, 23]
  ];
  trees.forEach(([x, y]) => solids.add(`${x},${y}`));

  // Key NPCs:
  // - Commander Vex inside Rundown Base (7,4)
  // - Team Rocket Rival inside Rundown Base (9,6)
  // - Rival Protagonist right outside the Rundown Base exit (8,11) where you steal his bike!
  // - Game Corner Boss (16,8)
  // - Daycare Keeper (5,16)
  const npcs = {
    vex: { x: 7, y: 4, role: 'vex' },
    rocketRival: { x: 9, y: 6, role: 'rocketRival' },
    heroRival: { x: 8, y: 11, role: 'heroRival' },
    cornerBoss: { x: 16, y: 8, role: 'cornerBoss' },
    daycareKeeper: { x: 5, y: 16, role: 'daycareKeeper' }
  };

  function inRundownBase(x, y) {
    return x >= baseBounds.x1 && x <= baseBounds.x2 && y >= baseBounds.y1 && y <= baseBounds.y2;
  }

  function currentAreaName() {
    if (game.mode === 'slots') return 'ROCKET GAME CORNER';
    if (inRundownBase(game.x, game.y)) return 'RUNDOWN ROCKET BASE';
    if (Math.abs(game.x - npcs.cornerBoss.x) + Math.abs(game.y - npcs.cornerBoss.y) <= 3) return 'GAME CORNER PLAZA';
    if (Math.abs(game.x - npcs.daycareKeeper.x) + Math.abs(game.y - npcs.daycareKeeper.y) <= 3) return 'SUNMEADOW DAYCARE';
    if (game.x > 19 || game.y > 18) return 'ROUTE 1 TALL GRASS';
    return 'SUNMEADOW OUTSKIRTS';
  }

  function tileType(x, y) {
    if (x < 0 || y < 0 || x >= mapW || y >= mapH) return 'wall';
    if (inRundownBase(x, y)) return 'baseFloor';
    if (ponds.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'water';
    if (path.has(`${x},${y}`)) return 'path';
    if (grassAreas.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'tall';
    return 'grass';
  }

  function npcAt(x, y) {
    return Object.values(npcs).find(n => n.x === x && n.y === y) || null;
  }

  function solid(x, y) {
    return solids.has(`${x},${y}`) || tileType(x, y) === 'water' || Boolean(npcAt(x, y));
  }

  function rect(x, y, w, h, color) {
    ctx.fillStyle = color;
    ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
  }

  function pixelText(text, x, y, size = 8, color = '#fff', align = 'left') {
    ctx.font = `bold ${size}px monospace`;
    ctx.textAlign = align;
    ctx.textBaseline = 'top';
    ctx.fillStyle = color;
    ctx.fillText(text, Math.round(x), Math.round(y));
  }

  function rounded(x, y, w, h, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
  }

  function drawTerrain(tx, ty, sx, sy) {
    const type = tileType(tx, ty);
    const seed = (tx * 92821 + ty * 68917) % 97;
    if (type === 'baseFloor') {
      const isWall =
        (ty === baseBounds.y1 || (ty === baseBounds.y2 && tx !== baseBounds.doorX) || tx === baseBounds.x1 || tx === baseBounds.x2);
      if (isWall) {
        rect(sx, sy, T, T, '#2d3340');
        rect(sx, sy, T, 3, '#454e5e');
        rect(sx + 2, sy + 5, T - 4, 8, '#39282c');
        rect(sx + 3, sy + 7, 3, 2, '#7d4842');
      } else {
        rect(sx, sy, T, T, (tx + ty) % 2 === 0 ? '#3a404d' : '#353b47');
        if (seed % 5 === 0) {
          rect(sx + 3, sy + 4, 5, 1, '#262b34');
          rect(sx + 7, sy + 5, 1, 4, '#262b34');
        }
        if (seed % 8 === 0) {
          rect(sx + 9, sy + 10, 4, 3, '#2b3942');
        }
      }
    } else if (type === 'grass') {
      rect(sx, sy, T, T, seed % 5 === 0 ? '#84c28d' : '#8bc995');
      if (seed % 7 === 0) {
        rect(sx + 3, sy + 4, 2, 2, '#a5d6a0');
        rect(sx + 11, sy + 12, 2, 1, '#6eb67c');
      }
    } else if (type === 'path') {
      rect(sx, sy, T, T, '#d7bd85');
      if (seed % 4 === 0) rect(sx + ((seed % 9) + 3), sy + 5, 2, 2, '#c7aa72');
      if (seed % 6 === 0) rect(sx + 3, sy + 12, 3, 1, '#e6d09e');
    } else if (type === 'tall') {
      rect(sx, sy, T, T, '#79bb80');
      const sway = Math.sin(game.anim * 0.003 + tx * 2 + ty) * 1.5;
      rect(sx + 3, sy + 9 + sway, 2, 6, '#438e5c');
      rect(sx + 5, sy + 5 + sway, 2, 9, '#519f66');
      rect(sx + 9, sy + 8 - sway, 2, 7, '#3f8858');
      rect(sx + 12, sy + 4 - sway, 2, 10, '#55a56c');
      rect(sx + 4, sy + 5 + sway, 2, 2, '#9bd296');
      rect(sx + 11, sy + 4 - sway, 2, 2, '#a1d89a');
    } else if (type === 'water') {
      rect(sx, sy, T, T, '#78bbcf');
      rect(sx, sy, 16, 2, '#9cdaeb');
      if (seed % 3 === 0) {
        rect(sx + 4, sy + 8 + Math.sin(game.anim * 0.002 + tx) * 2, 5, 1, '#a8e0e9');
        rect(sx + 10, sy + 12, 2, 1, '#639fb7');
      }
    } else {
      rect(sx, sy, T, T, '#83bd8b');
    }
  }

  function drawRundownBaseDetails(camX, camY) {
    const rx = 6 * T - camX + 6;
    const ry = 5 * T - camY + 2;
    rect(rx, ry, 20, 22, '#2c313d');
    rect(rx + 3, ry + 2, 4, 18, '#b83b3b');
    rect(rx + 7, ry + 2, 8, 4, '#b83b3b');
    rect(rx + 12, ry + 5, 4, 5, '#b83b3b');
    rect(rx + 7, ry + 9, 7, 4, '#b83b3b');
    rect(rx + 10, ry + 13, 6, 7, '#b83b3b');
    rect(rx + 4, ry + 8, 12, 1, '#3a404d');
    rect(rx + 2, ry + 15, 10, 1, '#353b47');

    [[3, 3], [4, 3], [10, 3], [3, 8]].forEach(([cx, cy], idx) => {
      const sx = cx * T - camX, sy = cy * T - camY;
      rect(sx + 1, sy + 2, 14, 13, idx === 2 ? '#394b59' : '#73533d');
      rect(sx + 2, sy + 3, 12, 3, idx === 2 ? '#597b8c' : '#8f694d');
      rect(sx + 4, sy + 8, 8, 2, '#262b34');
    });

    const bx = 7 * T - camX - 42;
    const by = 2 * T - camY - 4;
    rounded(bx, by, 98, 12, 3, '#211820eb');
    pixelText('RUNDOWN ROCKET BASE', bx + 49, by + 2, 7, '#ff7a72', 'center');
  }

  function drawTree(sx, sy) {
    rect(sx + 6, sy + 9, 5, 8, '#875d42');
    rect(sx + 4, sy + 14, 9, 3, '#76513e');
    rect(sx + 1, sy + 5, 14, 7, '#39895c');
    rect(sx + 3, sy + 2, 10, 8, '#4b9b66');
    rect(sx + 5, sy, 6, 6, '#5aa873');
    rect(sx + 4, sy + 4, 2, 2, '#82c585');
    rect(sx + 11, sy + 7, 2, 2, '#65b477');
  }

  function drawBuilding(b, cameraX, cameraY) {
    const x = b.x * T - cameraX, y = b.y * T - cameraY, w = b.w * T, h = b.h * T;
    if (b.type === 'corner') {
      rect(x + 2, y + 8, w - 4, h - 7, '#2d233b');
      rect(x, y + 4, w, 9, '#5e2750');
      for (let i = 0; i < b.w; i++) {
        rect(x + i * T + 1, y + 5, 7, 5, i % 2 === 0 ? '#e04848' : '#f6cb49');
      }
      rect(x + 6, y + 15, w - 12, h - 18, '#3d2f52');
      rect(x + 8, y + 19, 20, 14, '#1b1426');
      pixelText('777', x + 18, y + 22, 6, '#f6cb49', 'center');
      rect(x + w - 28, y + 19, 20, 14, '#1b1426');
      pixelText('R·R', x + w - 18, y + 22, 6, '#ff6b6b', 'center');
      rect(x + w / 2 - 7, y + h - 18, 14, 18, '#d94848');
      rect(x + w / 2 - 5, y + h - 16, 10, 14, '#f6cb49');
      rounded(x + w / 2 - 34, y - 4, 68, 12, 3, '#1d1326');
      pixelText('🎰 GAME CORNER', x + w / 2, y - 1, 7, '#f6cb49', 'center');
    } else if (b.type === 'daycare') {
      rect(x + 2, y + 8, w - 4, h - 7, '#f1dfbd');
      rect(x, y + 5, w, 8, '#66a97b');
      for (let i = 0; i < b.w; i++) {
        rect(x + i * T + 1, y + 5, 7, 5, '#82c596');
      }
      rect(x + w / 2 - 6, y + h - 17, 12, 17, '#896248');
      rect(x + 7, y + 18, 14, 11, '#72aab4');
      rect(x + w - 21, y + 18, 14, 11, '#72aab4');
      rounded(x + w / 2 - 28, y - 4, 56, 12, 3, '#fff2c7');
      pixelText('🥚 DAYCARE', x + w / 2, y - 1, 7, '#356346', 'center');
    } else {
      rect(x + 3, y + 8, w, h - 7, '#d7c6a2');
      rect(x, y + 5, w, 7, '#d78363');
      rect(x + 6, y + 14, w - 12, h - 19, '#f1dfbd');
      rect(x + w / 2 - 5, y + h - 17, 10, 17, '#896248');
    }
  }

  function drawPerson(px, py, type, frame = 0) {
    const x = Math.round(px), y = Math.round(py);
    if (type === 'hero') {
