  function drawWild(mon, x, y, scale = 1) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    const c = mon.color, a = mon.accent;
    rect(-21, 7, 43, 7, '#557763');
    if (mon.name === 'ODDISH') {
      rect(-15, -8, 30, 22, c); rect(-10, -15, 20, 11, c); rect(-8, -20, 5, 8, a); rect(4, -22, 5, 10, a);
      rect(-11, -9, 4, 4, '#ff6b6b'); rect(6, -9, 4, 4, '#ff6b6b'); rect(-3, -16, 6, 3, '#55a76d');
    } else if (mon.name === 'GROWLITHE' || mon.name === 'PIKACHU') {
      rect(-16, -9, 32, 25, c); rect(-13, -16, 9, 10, c); rect(5, -16, 9, 10, c); rect(-15, 3, 7, 8, a);
      rect(9, 3, 7, 8, a); rect(-7, -4, 4, 5, '#fff2cf'); rect(5, -4, 4, 5, '#fff2cf'); rect(-6, -3, 2, 4, '#292f39');
      rect(6, -3, 2, 4, '#292f39'); rect(12, -17, 7, 6, '#f3c75e');
    } else {
      rect(-17, -9, 34, 24, c); rect(-11, -15, 22, 10, c); rect(-18, -5, 7, 8, a); rect(11, -4, 8, 8, a);
      rect(-8, -6, 4, 4, '#f8f0d7'); rect(5, -6, 4, 4, '#f8f0d7'); rect(-7, -5, 2, 3, '#343c44'); rect(6, -5, 2, 3, '#343c44');
