    [16, 23], [17, 23], [18, 23], [19, 23], [20, 23], [21, 23], [22, 23],
    [23, 23], [24, 23], [25, 23], [26, 23], [27, 23], [28, 23], [29, 23]
  ];
  trees.forEach(([x, y]) => solids.add(`${x},${y}`));

  // Key NPCs: Commander Vex (Base), Rocket Rival (Base), Heroic Protagonist Rival (right outside Base with his Bike!), Game Corner Boss, Daycare Keeper
  const npcs = {
    vex: { x: 7, y: 4, role: 'vex' },
    rocketRival: { x: 9, y: 6, role: 'rocketRival' },
    heroRival: { x: 8, y: 10, role: 'heroRival' },
    cornerBoss: { x: 16, y: 8, role: 'cornerBoss' },
    daycareKeeper: { x: 5, y: 16, role: 'daycareKeeper' }
  };

  function inRundownBase(x, y) {
    return x >= baseBounds.x1 && x <= baseBounds.x2 && y >= baseBounds.y1 && y <= baseBounds.y2;
  }

  function currentAreaName() {
    if (game.mode === 'slots') return 'ROCKET GAME CORNER';
    if (inRundownBase(game.x, game.y)) return 'RUNDOWN ROCKET BASE';
    if (Math.abs(game.x - npcs.cornerBoss.x) + Math.abs(game.y - npcs.cornerBoss.y) <= 3) return 'GAME CORNER PLAZA';
    if (Math.abs(game.x - npcs.daycareKeeper.x) + Math.abs(game.y - npcs.daycareKeeper.y) <= 3) return 'SUNMEADOW DAYCARE';
    if (game.x > 19 || game.y > 18) return 'SUNMEADOW TRAIL';
    return 'OUTSIDE RUNDOWN BASE';
  }

  function tileType(x, y) {
    if (x < 0 || y < 0 || x >= mapW || y >= mapH) return 'wall';
    if (inRundownBase(x, y)) return 'baseFloor';
    if (ponds.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'water';
    if (path.has(`${x},${y}`)) return 'path';
    if (grassAreas.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'tall';
    return 'grass';
  }

  function npcAt(x, y) {
    return Object.values(npcs).find(n => n.x === x && n.y === y) || null;
  }

  function solid(x, y) {
    return solids.has(`${x},${y}`) || tileType(x, y) === 'water' || Boolean(npcAt(x, y));
  }

  function rect(x, y, w, h, color) {
    ctx.fillStyle = color;
    ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
  }

  function pixelText(text, x, y, size = 8, color = '#fff', align = 'left') {
    ctx.font = `bold ${size}px monospace`;
    ctx.textAlign = align;
    ctx.textBaseline = 'top';
    ctx.fillStyle = color;
    ctx.fillText(text, Math.round(x), Math.round(y));
  }

  function rounded(x, y, w, h, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
  }

  // Exact 1/3rd probability roll for Pokémon Red Version Starter inside the 1 Pokéball on the stolen bike!
  function stealRivalBike() {
    if (game.bikeStolen && game.starter) return game.starter;
    const oneThirdRoll = Math.floor(Math.random() * 3); // 0 = BULBASAUR (1/3), 1 = CHARMANDER (1/3), 2 = SQUIRTLE (1/3)
    const chosenStarter = RED_STARTERS[oneThirdRoll];
    game.starter = { ...chosenStarter };
    game.bikeStolen = true;
    game.ridingBike = true;
    game.heistDone = 1;
    // Step right outside the Rundown Base doorway onto the stolen bike!
    game.x = bikeSpot.x;
    game.y = bikeSpot.y;
    game.facing = 'down';
    game.buddyTrail = [{ x: bikeSpot.x, y: bikeSpot.y - 1 }];
    game.message = `Left initiation & stole ${game.heroRival}'s Bike! The 1 Pokéball in the basket contained ${chosenStarter.name} (1/3 Red Starter)! ${game.heroRival}: “Hey! My bike and Pokéball!”`;
    addMerits(25, `Stole ${game.heroRival}'s Bike & Got ${chosenStarter.name}!`);
    return chosenStarter;
  }

  function ensureBikeStolen() {
    if (!game.bikeStolen || !game.starter) {
      stealRivalBike();
    }
  }

  function drawTerrain(tx, ty, sx, sy) {
    const type = tileType(tx, ty);
    const seed = (tx * 92821 + ty * 68917) % 97;
    if (type === 'baseFloor') {
      const isWall =
        (ty === baseBounds.y1 || (ty === baseBounds.y2 && tx !== baseBounds.doorX) || tx === baseBounds.x1 || tx === baseBounds.x2);
      if (isWall) {
        rect(sx, sy, T, T, '#2d3340');
        rect(sx, sy, T, 3, '#454e5e');
        rect(sx + 2, sy + 5, T - 4, 8, '#39282c');
        rect(sx + 3, sy + 7, 3, 2, '#7d4842');
      } else {
        rect(sx, sy, T, T, (tx + ty) % 2 === 0 ? '#3a404d' : '#353b47');
        if (seed % 5 === 0) {
          rect(sx + 3, sy + 4, 5, 1, '#262b34');
          rect(sx + 7, sy + 5, 1, 4, '#262b34');
        }
        if (seed % 8 === 0) {
          rect(sx + 9, sy + 10, 4, 3, '#2b3942');
        }
      }
    } else if (type === 'grass') {
      rect(sx, sy, T, T, seed % 5 === 0 ? '#84c28d' : '#8bc995');
      if (seed % 7 === 0) {
        rect(sx + 3, sy + 4, 2, 2, '#a5d6a0');
        rect(sx + 11, sy + 12, 2, 1, '#6eb67c');
      }
    } else if (type === 'path') {
      rect(sx, sy, T, T, '#d7bd85');
      if (seed % 4 === 0) rect(sx + ((seed % 9) + 3), sy + 5, 2, 2, '#c7aa72');
      if (seed % 6 === 0) rect(sx + 3, sy + 12, 3, 1, '#e6d09e');
    } else if (type === 'tall') {
      rect(sx, sy, T, T, '#79bb80');
      const sway = Math.sin(game.anim * 0.003 + tx * 2 + ty) * 1.5;
      rect(sx + 3, sy + 9 + sway, 2, 6, '#438e5c');
      rect(sx + 5, sy + 5 + sway, 2, 9, '#519f66');
      rect(sx + 9, sy + 8 - sway, 2, 7, '#3f8858');
      rect(sx + 12, sy + 4 - sway, 2, 10, '#55a56c');
      rect(sx + 4, sy + 5 + sway, 2, 2, '#9bd296');
      rect(sx + 11, sy + 4 - sway, 2, 2, '#a1d89a');
    } else if (type === 'water') {
      rect(sx, sy, T, T, '#78bbcf');
      rect(sx, sy, 16, 2, '#9cdaeb');
      if (seed % 3 === 0) {
        rect(sx + 4, sy + 8 + Math.sin(game.anim * 0.002 + tx) * 2, 5, 1, '#a8e0e9');
        rect(sx + 10, sy + 12, 2, 1, '#639fb7');
      }
    } else {
      rect(sx, sy, T, T, '#83bd8b');
    }
  }

  function drawRundownBaseDetails(camX, camY) {
    const rx = 6 * T - camX + 6;
    const ry = 5 * T - camY + 2;
    rect(rx, ry, 20, 22, '#2c313d');
    rect(rx + 3, ry + 2, 4, 18, '#b83b3b');
    rect(rx + 7, ry + 2, 8, 4, '#b83b3b');
    rect(rx + 12, ry + 5, 4, 5, '#b83b3b');
    rect(rx + 7, ry + 9, 7, 4, '#b83b3b');
    rect(rx + 10, ry + 13, 6, 7, '#b83b3b');
    rect(rx + 4, ry + 8, 12, 1, '#3a404d');
    rect(rx + 2, ry + 15, 10, 1, '#353b47');

    [[3, 3], [4, 3], [10, 3], [3, 8]].forEach(([cx, cy], idx) => {
      const sx = cx * T - camX, sy = cy * T - camY;
      rect(sx + 1, sy + 2, 14, 13, idx === 2 ? '#394b59' : '#73533d');
      rect(sx + 2, sy + 3, 12, 3, idx === 2 ? '#597b8c' : '#8f694d');
      rect(sx + 4, sy + 8, 8, 2, '#262b34');
    });

    const bx = 7 * T - camX - 42;
    const by = 2 * T - camY - 4;
    rounded(bx, by, 100, 12, 3, '#211820eb');
    pixelText('RUNDOWN ROCKET BASE', bx + 50, by + 2, 7, '#ff7a72', 'center');
  }

  // Draw the parked Bicycle + 1 Pokéball in the basket before it's stolen!
  function drawParkedBikeWithPokeball(px, py) {
    const x = Math.round(px), y = Math.round(py);
    rect(x - 8, y + 6, 16, 3, 'rgba(0,0,0,0.28)');
    // Back & front wheels
    rect(x - 7, y + 1, 5, 6, '#232730');
    rect(x - 6, y + 2, 3, 4, '#d5dde6');
    rect(x + 2, y + 1, 5, 6, '#232730');
    rect(x + 3, y + 2, 3, 4, '#d5dde6');
    // Red bike frame & handlebars
    rect(x - 5, y, 9, 2, '#e04848');
    rect(x - 2, y - 3, 3, 4, '#e04848');
    rect(x + 2, y - 5, 2, 6, '#e04848');
    rect(x + 1, y - 6, 4, 2, '#354352');
    // 1 Red/White Pokéball sitting in the front bike basket!
    rect(x + 3, y - 5, 6, 3, '#e04848');
    rect(x + 3, y - 2, 6, 2, '#ffffff');
    rect(x + 5, y - 3, 2, 2, '#232730');
    rounded(x - 28, y - 19, 56, 9, 2, '#d9413beb');
    pixelText('🚲 BIKE + 1 BALL', x, y - 18, 6, '#fff', 'center');
  }

  // Draw the 3 Pokémon Red Version Starters (BULBASAUR, CHARMANDER, SQUIRTLE)
  function drawRedStarter(px, py, scale = 1, starterObj = null) {
    const st = starterObj || game.starter || RED_STARTERS[1];
    ctx.save();
    ctx.translate(Math.round(px), Math.round(py));
    ctx.scale(scale, scale);
    rect(-8, 8, 16, 3, 'rgba(0,0,0,0.28)');

    if (st.name === 'BULBASAUR') {
      // Green plant bulb on back
      rect(-6, -13, 12, 8, '#3f9959');
      rect(-4, -15, 8, 4, '#6ad178');
      // Blue-green body & legs
      rect(-8, -7, 16, 13, '#6ec287');
      rect(-7, 4, 4, 5, '#52a66d');
      rect(3, 4, 4, 5, '#52a66d');
      // Spots & red eyes
      rect(2, -4, 3, 3, '#3b8c58');
      rect(-4, -4, 2, 3, '#d94848');
      rect(1, -4, 2, 3, '#d94848');
    } else if (st.name === 'SQUIRTLE') {
      // Curly water tail & brown shell
      rect(6, -1, 5, 5, '#5aa0c2');
      rect(8, -3, 3, 4, '#3d7fa3');
      rect(-6, -10, 12, 13, '#b87d4b');
      // Sky-blue head, body & feet
      rect(-7, -13, 13, 10, '#6db7d6');
      rect(-6, -3, 11, 9, '#f5e4b8');
      rect(-6, 5, 4, 4, '#6db7d6');
      rect(2, 5, 4, 4, '#6db7d6');
      rect(-4, -9, 2, 3, '#232c38');
      rect(2, -9, 2, 3, '#232c38');
    } else {
      // CHARMANDER: Orange body, cream belly, burning tail flame!
      rect(7, 0, 4, 3, '#f08750');
      rect(10, -5, 5, 6, '#e04848');
      rect(11, -8, 3, 4, '#f6cb49');
      rect(-6, -13, 12, 16, '#f08750');
      rect(-4, -3, 8, 8, '#f7e2a4');
      rect(-4, -9, 2, 3, '#232c38');
      rect(2, -9, 2, 3, '#232c38');
      rect(-5, 4, 4, 5, '#d46b38');
      rect(2, 4, 4, 5, '#d46b38');
    }
    ctx.restore();
  }

  function drawTree(sx, sy) {
    rect(sx + 6, sy + 9, 5, 8, '#875d42');
    rect(sx + 4, sy + 14, 9, 3, '#76513e');
    rect(sx + 1, sy + 5, 14, 7, '#39895c');
    rect(sx + 3, sy + 2, 10, 8, '#4b9b66');
    rect(sx + 5, sy, 6, 6, '#5aa873');
    rect(sx + 4, sy + 4, 2, 2, '#82c585');
    rect(sx + 11, sy + 7, 2, 2, '#65b477');
  }

  function drawBuilding(b, cameraX, cameraY) {
    const x = b.x * T - cameraX, y = b.y * T - cameraY, w = b.w * T, h = b.h * T;
    if (b.type === 'corner') {
      rect(x + 2, y + 8, w - 4, h - 7, '#2d233b');
      rect(x, y + 4, w, 9, '#5e2750');
      for (let i = 0; i < b.w; i++) {
        rect(x + i * T + 1, y + 5, 7, 5, i % 2 === 0 ? '#e04848' : '#f6cb49');
      }
      rect(x + 6, y + 15, w - 12, h - 18, '#3d2f52');
      rect(x + 8, y + 19, 20, 14, '#1b1426');
      pixelText('777', x + 18, y + 22, 6, '#f6cb49', 'center');
      rect(x + w - 28, y + 19, 20, 14, '#1b1426');
      pixelText('R·R', x + w - 18, y + 22, 6, '#ff6b6b', 'center');
      rect(x + w / 2 - 7, y + h - 18, 14, 18, '#d94848');
      rect(x + w / 2 - 5, y + h - 16, 10, 14, '#f6cb49');
      rounded(x + w / 2 - 34, y - 4, 68, 12, 3, '#1d1326');
      pixelText('🎰 GAME CORNER', x + w / 2, y - 1, 7, '#f6cb49', 'center');
    } else if (b.type === 'daycare') {
      rect(x + 2, y + 8, w - 4, h - 7, '#f1dfbd');
      rect(x, y + 5, w, 8, '#66a97b');
      for (let i = 0; i < b.w; i++) {
        rect(x + i * T + 1, y + 5, 7, 5, '#82c596');
      }
      rect(x + w / 2 - 6, y + h - 17, 12, 17, '#896248');
      rect(x + 7, y + 18, 14, 11, '#72aab4');
      rect(x + w - 21, y + 18, 14, 11, '#72aab4');
      rounded(x + w / 2 - 28, y - 4, 56, 12, 3, '#fff2c7');
      pixelText('🥚 DAYCARE', x + w / 2, y - 1, 7, '#356346', 'center');
    } else {
      rect(x + 3, y + 8, w, h - 7, '#d7c6a2');
      rect(x, y + 5, w, 7, '#d78363');
      rect(x + 6, y + 14, w - 12, h - 19, '#f1dfbd');
      rect(x + w / 2 - 5, y + h - 17, 10, 17, '#896248');
    }
  }

  function drawPerson(px, py, type, frame = 0) {
    const x = Math.round(px), y = Math.round(py);
    if (type === 'hero') {
      rect(x - 6, y + 9, 13, 3, 'rgba(0,0,0,0.3)');
      // If riding stolen bike, draw red bicycle frame & wheels under the Grunt
      if (game.bikeStolen && game.ridingBike) {
        rect(x - 8, y + 5, 5, 6, '#1b1f26');
        rect(x - 7, y + 6, 3, 4, '#cfd8e3');
        rect(x + 3, y + 5, 5, 6, '#1b1f26');
        rect(x + 4, y + 6, 3, 4, '#cfd8e3');
        rect(x - 5, y + 4, 10, 2, '#e04848');
      }
      rect(x - 5, y - 8, 10, 9, '#f0c79c');
      rect(x - 6, y - 12, 12, 5, '#232730');
      rect(x - 4, y - 9, 9, 2, '#e04848');
      rect(x - 6, y, 12, 8, '#262b36');
      rect(x - 2, y + 2, 4, 4, '#e04848');
      rect(x - 5, y + 7, 4, 5, '#1b1f26');
      rect(x + 2, y + 7, 4, 5, '#1b1f26');
      if (frame % 2) {
        rect(x - 7, y + 11, 4, 2, '#14171d');
        rect(x + 2, y + 11, 4, 2, '#14171d');
      }
    } else if (type === 'vex') {
      rect(x - 6, y + 9, 13, 3, 'rgba(0,0,0,0.35)');
      rect(x - 5, y - 8, 10, 9, '#ecc39a');
      rect(x - 7, y - 12, 14, 5, '#591e29');
      rect(x - 5, y - 9, 10, 2, '#f6cb49');
      rect(x - 7, y, 14, 9, '#3d1c26');
      rect(x - 2, y + 2, 4, 5, '#f6cb49');
      rect(x - 5, y + 8, 4, 4, '#24151c');
      rect(x + 2, y + 8, 4, 4, '#24151c');
    } else if (type === 'rocketRival') {
      rect(x - 6, y + 9, 13, 3, 'rgba(0,0,0,0.35)');
      rect(x - 5, y - 8, 10, 9, '#f2c9a0');
      rect(x - 6, y - 12, 12, 5, '#6c3b7a');
      rect(x - 6, y, 12, 8, '#30243d');
      rect(x - 2, y + 2, 4, 4, '#ff6b6b');
      rect(x - 5, y + 7, 4, 5, '#221a2b');
      rect(x + 2, y + 7, 4, 5, '#221a2b');
    } else if (type === 'heroRival') {
      rect(x - 6, y + 9, 13, 3, '#4b785d');
      rect(x - 5, y - 8, 10, 9, '#f2c99e');
      rect(x - 6, y - 12, 12, 5, '#d94b43');
      rect(x - 3, y - 10, 6, 2, '#ffffff');
      rect(x - 6, y, 12, 8, '#3b73b5');
      rect(x - 5, y + 7, 4, 5, '#344966');
      rect(x + 2, y + 7, 4, 5, '#344966');
    } else if (type === 'cornerBoss') {
      rect(x - 6, y + 9, 13, 3, '#4b785d');
      rect(x - 5, y - 8, 10, 9, '#f0c79c');
      rect(x - 6, y - 12, 12, 4, '#47224a');
      rect(x - 6, y, 12, 8, '#d9a338');
      rect(x - 5, y + 7, 4, 5, '#3b243d');
      rect(x + 2, y + 7, 4, 5, '#3b243d');
    } else if (type === 'daycareKeeper') {
      rect(x - 6, y + 9, 13, 3, '#4b785d');
      rect(x - 5, y - 8, 10, 9, '#f2c99e');
      rect(x - 6, y - 11, 12, 4, '#d9c8a9');
      rect(x - 6, y, 12, 8, '#559e72');
      rect(x - 5, y + 7, 4, 5, '#4c6656');
      rect(x + 2, y + 7, 4, 5, '#4c6656');
    }
  }

  function nearbyInteraction() {
    if (!game.bikeStolen && Math.abs(game.x - bikeSpot.x) + Math.abs(game.y - bikeSpot.y) <= 3) {
      return 'stealBike';
    }
    for (const key of Object.keys(npcs)) {
      const n = npcs[key];
      if (Math.abs(game.x - n.x) + Math.abs(game.y - n.y) <= 2) return n.role;
    }
    if (tileType(game.x, game.y) === 'tall') return 'tall';
    return null;
  }

  function drawMap() {
    const camX = clamp(game.x * T - W / 2 + 8, 0, mapW * T - W);
    const camY = clamp(game.y * T - H / 2 + 8, 0, mapH * T - H);
    const startX = Math.floor(camX / T), startY = Math.floor(camY / T);

    for (let ty = startY; ty <= startY + H / T; ty++) {
      for (let tx = startX; tx <= startX + W / T; tx++) {
        drawTerrain(tx, ty, tx * T - camX, ty * T - camY);
      }
    }

    drawRundownBaseDetails(camX, camY);

    for (let y = startY; y <= startY + H / T; y++) {
      for (let x = startX; x <= startX + W / T; x++) {
        if (tileType(x, y) === 'grass' && (x * 7 + y * 13) % 31 === 0) {
          rect(x * T - camX + 7, y * T - camY + 8, 2, 2, '#f3d16a');
          rect(x * T - camX + 9, y * T - camY + 7, 2, 2, '#fff0c1');
        }
      }
    }

    buildings.forEach(b => drawBuilding(b, camX, camY));
    trees.forEach(([x, y]) => drawTree(x * T - camX, y * T - camY));

    // Daycare fenced playpen
    for (let x = 8; x < 11; x++) {
      const fx = x * T - camX, fy = 14 * T - camY;
      rect(fx, fy, 2, 8, '#ae8858');
      rect(fx + 7, fy, 2, 8, '#ae8858');
      rect(fx, fy + 2, 9, 2, '#c29a66');
    }
    drawWild(creatures[0], 9 * T + 8 - camX, 13 * T + 8 - camY, 0.45);

    // Draw Rival Protagonist's parked Bike + 1 Pokéball right outside the Rundown Base if not yet stolen!
    if (!game.bikeStolen) {
      drawParkedBikeWithPokeball(bikeSpot.x * T + 8 - camX, bikeSpot.y * T + 8 - camY);
    }

    // Draw NPCs
    Object.values(npcs).forEach(n => {
      const nx = n.x * T + 8 - camX;
      const ny = n.y * T + 8 - camY;
      if (nx > -20 && nx < W + 20 && ny > -20 && ny < H + 20) {
        drawPerson(nx, ny, n.role, game.anim >> 8);
        let tag = '';
        if (n.role === 'vex') tag = 'CMDR. VEX';
        else if (n.role === 'rocketRival') tag = game.rocketRival;
        else if (n.role === 'heroRival') tag = game.heroRival;
        else if (n.role === 'cornerBoss') tag = 'SLOTS BOSS';
        else if (n.role === 'daycareKeeper') tag = 'DAYCARE';
        if (tag) {
          rounded(nx - 24, ny - 23, 48, 9, 2, '#141d2bd8');
          pixelText(tag, nx, ny - 22, 6, '#f6cb49', 'center');
        }
      }
    });

    // If bike has been stolen, draw the 1/3 Red Version Starter following behind the Grunt!
    if (game.bikeStolen && game.starter) {
      const buddy = game.buddyTrail[0] || { x: game.x, y: game.y - 1 };
      drawRedStarter(buddy.x * T + 8 - camX, buddy.y * T + 8 - camY, 0.78, game.starter);
    }
    drawPerson(game.x * T + 8 - camX, game.y * T + 8 - camY, 'hero', game.anim >> 7);

    // Top-left Area & Rank HUD overlay on canvas
    rounded(6, 6, 166, 26, 3, '#172230e6');
    pixelText(currentAreaName(), 11, 9, 7, '#fff3d4');
    pixelText(`${game.playerName} • ${RANKS[game.rankIndex].title}`, 11, 20, 6, '#f6cb49');

    // Top-right Bike / Starter / Funds overlay
    rounded(W - 144, 6, 138, 17, 3, '#172230e6');
    pixelText(
      game.starter ? `🚲 ${game.starter.name} • ₽${game.funds}` : `STEAL ${game.heroRival}'S BIKE!`,
      W - 75,
      11,
      6,
      '#9be5aa',
      'center'
    );

    const near = nearbyInteraction();
    if (near) {
      let promptText = 'SPACE · INTERACT';
      if (near === 'stealBike') promptText = `SPACE · STEAL ${game.heroRival}'S BIKE & BALL`;
      else if (near === 'vex') promptText = 'SPACE · REPORT / RANK UP';
      else if (near === 'rocketRival') promptText = `SPACE · BATTLE ${game.rocketRival}`;
      else if (near === 'heroRival') promptText = `SPACE · BATTLE ${game.heroRival}`;
      else if (near === 'cornerBoss') promptText = 'SPACE · PLAY SLOTS / WORK';
