(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const W = canvas.width, H = canvas.height, T = 16;
  const $ = id => document.getElementById(id);

  const ui = {
    status: $('status-line'),
    area: $('area-label'),
    level: $('level'),
    hpBar: $('hp-bar'),
    hpText: $('hp-text'),
    buddyCount: $('buddy-count'),
    wins: $('win-count'),
    noteTitle: $('note-title'),
    note: $('field-note'),
    goal: $('goal-text'),
    goalCheck: $('goal-check'),
    progress: $('goal-progress'),
    action: $('action-label'),
    toast: $('toast'),
    playerNameDisplay: $('player-name-display'),
    rocketRivalDisplay: $('rocket-rival-display'),
    heroRivalDisplay: $('hero-rival-display'),
    rankDisplay: $('rank-display'),
    rankTierPill: $('rank-tier-pill'),
    meritDisplay: $('merit-display'),
    rankBar: $('rank-bar'),
    upgradesSummary: $('upgrades-summary'),
    playerUpgLvl: $('player-upg-lvl'),
    playerUpgName: $('player-upg-name'),
    btnUpgPlayer: $('btn-upg-player'),
    baseUpgLvl: $('base-upg-lvl'),
    baseUpgName: $('base-upg-name'),
    btnUpgBase: $('btn-upg-base'),
    bizUpgLvl: $('biz-upg-lvl'),
    bizUpgName: $('biz-upg-name'),
    btnUpgBiz: $('btn-upg-biz'),
    gruntCallsign: $('grunt-callsign'),
    jobLedger: $('job-ledger'),
    fundsReadout: $('funds-readout'),
    starterNameLabel: $('starter-name-label'),
    starterTypeLabel: $('starter-type-label'),
    partnerBadgeIcon: $('partner-badge-icon'),
    bikeToggle: $('bike-toggle'),
    introOverlay: $('intro-overlay'),
    introForm: $('intro-form'),
    playerInput: $('player-name-input'),
    rocketRivalInput: $('rocket-rival-input'),
    heroRivalInput: $('hero-rival-input')
  };

  const rnd = (a, b) => Math.floor(Math.random() * (b - a + 1)) + a;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

  const RANKS = [
    { title: 'PROBATIONARY GRUNT', minMerits: 0, nextMerits: 25, bonusHp: 0 },
    { title: 'FIELD GRUNT', minMerits: 25, nextMerits: 50, bonusHp: 4 },
    { title: 'ROCKET AGENT', minMerits: 50, nextMerits: 80, bonusHp: 8 },
    { title: 'ROCKET ELITE', minMerits: 80, nextMerits: 115, bonusHp: 12 },
    { title: 'ROCKET EXECUTIVE', minMerits: 115, nextMerits: 150, bonusHp: 18 }
  ];

  const PLAYER_UPGRADES = [
