  function inRundownBase(x, y) {
    return x >= baseBounds.x1 && x <= baseBounds.x2 && y >= baseBounds.y1 && y <= baseBounds.y2;
  }

  function currentAreaName() {
    if (game.mode === 'slots') return 'ROCKET GAME CORNER';
    if (inRundownBase(game.x, game.y)) return BASE_UPGRADES[game.baseUpgrade].banner;
    if (Math.abs(game.x - npcs.cornerBoss.x) + Math.abs(game.y - npcs.cornerBoss.y) <= 3) return 'GAME CORNER PLAZA';
    if (Math.abs(game.x - npcs.daycareKeeper.x) + Math.abs(game.y - npcs.daycareKeeper.y) <= 3) return 'SUNMEADOW DAYCARE';
    if (game.x > 19 || game.y > 18) return 'SUNMEADOW TRAIL';
    return 'OUTSIDE ROCKET BASE';
  }

  function tileType(x, y) {
    if (x < 0 || y < 0 || x >= mapW || y >= mapH) return 'wall';
    if (inRundownBase(x, y)) return 'baseFloor';
    if (ponds.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'water';
    if (path.has(`${x},${y}`)) return 'path';
    if (grassAreas.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'tall';
    return 'grass';
  }

  function npcAt(x, y) {
    return Object.values(npcs).find(n => n.x === x && n.y === y) || null;
  }

  function solid(x, y) {
    return solids.has(`${x},${y}`) || tileType(x, y) === 'water' || Boolean(npcAt(x, y));
  }

  function rect(x, y, w, h, color) {
    ctx.fillStyle = color;
    ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
  }

  function pixelText(text, x, y, size = 8, color = '#fff', align = 'left') {
    ctx.font = `bold ${size}px monospace`;
    ctx.textAlign = align;
    ctx.textBaseline = 'top';
    ctx.fillStyle = color;
    ctx.fillText(text, Math.round(x), Math.round(y));
  }

  function rounded(x, y, w, h, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
  }

  // Exact 1/3rd probability roll for Pokémon Red Version Starter inside the 1 Pokéball on the stolen bike!
  function stealRivalBike() {
    if (game.bikeStolen && game.starter) return game.starter;
    const oneThirdRoll = Math.floor(Math.random() * 3); // 0 = BULBASAUR (1/3), 1 = CHARMANDER (1/3), 2 = SQUIRTLE (1/3)
    const chosenStarter = RED_STARTERS[oneThirdRoll];
    game.starter = { ...chosenStarter };
    game.bikeStolen = true;
    game.ridingBike = true;
    game.heistDone = 1;
    game.x = bikeSpot.x;
    game.y = bikeSpot.y;
    game.facing = 'down';
    game.buddyTrail = [{ x: bikeSpot.x, y: bikeSpot.y - 1 }];
    game.message = `Left initiation & stole ${game.heroRival}'s Bike! The 1 Pokéball in the basket contained ${chosenStarter.name} (1/3 Red Starter)! Promoted to FIELD GRUNT!`;
    addMerits(25, `Stole ${game.heroRival}'s Bike & Got ${chosenStarter.name}!`);
    return chosenStarter;
  }

  function ensureBikeStolen() {
    if (!game.bikeStolen || !game.starter) {
      stealRivalBike();
    }
  }

  function purchaseOrUnlockUpgrade(kind) {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    if (kind === 'player') {
      if (game.playerUpgrade >= PLAYER_UPGRADES.length - 1) {
        showToast('Player Upgrades are at MAX Executive level!');
        return;
      }
      const cost = PLAYER_UPGRADES[game.playerUpgrade].cost;
      if (game.funds >= cost) game.funds -= cost;
      game.playerUpgrade++;
      game.maxHp += 5;
      game.hp = game.maxHp;
      const upg = PLAYER_UPGRADES[game.playerUpgrade];
      game.message = `Unlocked Player Upgrade: ${upg.name} (+${upg.atkBonus} Attack, +5 Max HP)!`;
      addMerits(15, `Player Upgrade: ${upg.name}`);
    } else if (kind === 'base') {
      if (game.baseUpgrade >= BASE_UPGRADES.length - 1) {
        showToast('Base Upgrades are at MAX Fortress HQ level!');
        return;
      }
      const cost = BASE_UPGRADES[game.baseUpgrade].cost;
      if (game.funds >= cost) game.funds -= cost;
      game.baseUpgrade++;
      game.orbs += 1;
      game.hp = game.maxHp;
      const upg = BASE_UPGRADES[game.baseUpgrade];
      game.message = `Unlocked Base Upgrade: ${upg.name} (Base renovated +1 Pokéball & Med-Pod)!`;
      addMerits(15, `Base Upgrade: ${upg.name}`);
    } else if (kind === 'biz') {
      if (game.bizUpgrade >= BIZ_UPGRADES.length - 1) {
        showToast('Business Upgrades are at MAX Monopoly level!');
        return;
      }
      const cost = BIZ_UPGRADES[game.bizUpgrade].cost;
      if (game.funds >= cost) game.funds -= cost;
      game.bizUpgrade++;
      const upg = BIZ_UPGRADES[game.bizUpgrade];
      game.message = `Unlocked Business Upgrade: ${upg.name} (Game Corner ₽${upg.cornerPay}/shift, Daycare ₽${upg.daycarePay}/shift)!`;
      addMerits(15, `Business Upgrade: ${upg.name}`);
    }
    updateUI();
  }

  function drawTerrain(tx, ty, sx, sy) {
    const type = tileType(tx, ty);
    const seed = (tx * 92821 + ty * 68917) % 97;
    if (type === 'baseFloor') {
      const isWall =
        (ty === baseBounds.y1 || (ty === baseBounds.y2 && tx !== baseBounds.doorX) || tx === baseBounds.x1 || tx === baseBounds.x2);
      if (isWall) {
        rect(sx, sy, T, T, game.baseUpgrade >= 3 ? '#2c2238' : '#2d3340');
        rect(sx, sy, T, 3, game.baseUpgrade >= 4 ? '#f6cb49' : '#454e5e');
        rect(sx + 2, sy + 5, T - 4, 8, game.baseUpgrade >= 2 ? '#45283c' : '#39282c');
        if (game.baseUpgrade === 0) rect(sx + 3, sy + 7, 3, 2, '#7d4842'); // rust only when rundown
      } else {
        const floorA = game.baseUpgrade >= 2 ? '#2e3646' : '#3a404d';
        const floorB = game.baseUpgrade >= 2 ? '#28303e' : '#353b47';
        rect(sx, sy, T, T, (tx + ty) % 2 === 0 ? floorA : floorB);
        // Red carpet runner unlocked at Base Upgrade Lv.3+
        if (game.baseUpgrade >= 2 && tx === baseBounds.doorX && ty > baseBounds.y1 && ty <= baseBounds.y2) {
          rect(sx + 3, sy, 10, T, '#8f2630');
          rect(sx + 4, sy, 8, T, '#b8323e');
        }
        // Cracks only when Base is still rundown
        if (game.baseUpgrade === 0 && seed % 5 === 0) {
          rect(sx + 3, sy + 4, 5, 1, '#262b34');
          rect(sx + 7, sy + 5, 1, 4, '#262b34');
        }
      }
    } else if (type === 'grass') {
      rect(sx, sy, T, T, seed % 5 === 0 ? '#84c28d' : '#8bc995');
      if (seed % 7 === 0) {
        rect(sx + 3, sy + 4, 2, 2, '#a5d6a0');
        rect(sx + 11, sy + 12, 2, 1, '#6eb67c');
      }
    } else if (type === 'path') {
      rect(sx, sy, T, T, '#d7bd85');
      if (seed % 4 === 0) rect(sx + ((seed % 9) + 3), sy + 5, 2, 2, '#c7aa72');
      if (seed % 6 === 0) rect(sx + 3, sy + 12, 3, 1, '#e6d09e');
    } else if (type === 'tall') {
      rect(sx, sy, T, T, '#79bb80');
      const sway = Math.sin(game.anim * 0.003 + tx * 2 + ty) * 1.5;
      rect(sx + 3, sy + 9 + sway, 2, 6, '#438e5c');
      rect(sx + 5, sy + 5 + sway, 2, 9, '#519f66');
      rect(sx + 9, sy + 8 - sway, 2, 7, '#3f8858');
      rect(sx + 12, sy + 4 - sway, 2, 10, '#55a56c');
      rect(sx + 4, sy + 5 + sway, 2, 2, '#9bd296');
      rect(sx + 11, sy + 4 - sway, 2, 2, '#a1d89a');
    } else if (type === 'water') {
      rect(sx, sy, T, T, '#78bbcf');
      rect(sx, sy, 16, 2, '#9cdaeb');
      if (seed % 3 === 0) {
        rect(sx + 4, sy + 8 + Math.sin(game.anim * 0.002 + tx) * 2, 5, 1, '#a8e0e9');
        rect(sx + 10, sy + 12, 2, 1, '#639fb7');
      }
    } else {
      rect(sx, sy, T, T, '#83bd8b');
    }
  }

  function drawRundownBaseDetails(camX, camY) {
    const rx = 6 * T - camX + 6;
    const ry = 5 * T - camY + 2;
    const rColor = game.baseUpgrade >= 2 ? '#ff4747' : '#b83b3b';
