    rounded(bx, by, 112, 12, 3, '#211820eb');
    pixelText(BASE_UPGRADES[game.baseUpgrade].banner, bx + 56, by + 2, 7, game.baseUpgrade >= 2 ? '#f6cb49' : '#ff7a72', 'center');
