  function render() {
    ctx.clearRect(0, 0, W, H);
    if (game.mode === 'intro') drawIntroScene();
    else if (game.mode === 'map') drawMap();
    else if (game.mode === 'battle') drawBattle();
    else if (game.mode === 'slots') drawSlotsMiniGame();
  }

  function showToast(text) {
    ui.toast.textContent = text;
    ui.toast.classList.add('show');
    clearTimeout(game.toastTimer);
    game.toastTimer = setTimeout(() => ui.toast.classList.remove('show'), 2600);
  }

  function addMerits(amount, reason) {
    game.merits += amount;
    let promoted = false;
    while (game.rankIndex < RANKS.length - 1 && game.merits >= RANKS[game.rankIndex].nextMerits) {
      game.rankIndex++;
      // Every rank promotion automatically unlocks Player, Base, and Business upgrades up to the new Rank!
      if (game.playerUpgrade < game.rankIndex) game.playerUpgrade = game.rankIndex;
      if (game.baseUpgrade < game.rankIndex) game.baseUpgrade = game.rankIndex;
      if (game.bizUpgrade < game.rankIndex) game.bizUpgrade = game.rankIndex;
      game.maxHp += 5;
      game.hp = game.maxHp;
      game.orbs += 1;
      promoted = true;
    }
    if (promoted) {
      const newRank = RANKS[game.rankIndex].title;
      showToast(`★ PROMOTED TO ${newRank}! Unlocked Lv.${game.rankIndex + 1} Player, Base & Business Upgrades!`);
    } else if (reason) {
      showToast(`${reason} (+${amount} Rocket Merits)`);
    }
    updateUI();
  }

  function updateUI() {
    const rankObj = RANKS[game.rankIndex];
    const pUpg = PLAYER_UPGRADES[game.playerUpgrade];
    const baseUpg = BASE_UPGRADES[game.baseUpgrade];
    const bizUpg = BIZ_UPGRADES[game.bizUpgrade];

    ui.level.textContent = game.level;
    ui.hpBar.style.width = `${clamp((100 * game.hp) / game.maxHp, 0, 100)}%`;
    ui.hpText.textContent = `${game.hp} / ${game.maxHp}`;
    ui.buddyCount.textContent = String((game.starter ? 1 : 0) + game.caught).padStart(2, '0');
    ui.wins.textContent = String(game.heistDone + game.wins + game.cornerShifts + game.daycareShifts).padStart(2, '0');
    ui.area.textContent = currentAreaName();
    ui.status.textContent = game.message;

    ui.playerNameDisplay.textContent = `GRUNT ${game.playerName}`;
    ui.rocketRivalDisplay.textContent = game.rocketRival;
    ui.heroRivalDisplay.textContent = game.heroRival;

    if (game.starter) {
      ui.starterNameLabel.textContent = game.starter.name;
      ui.starterTypeLabel.innerHTML = `<i></i>${game.starter.kind} • FROM STOLEN BIKE`;
      ui.partnerBadgeIcon.style.background = game.starter.color;
      ui.partnerBadgeIcon.style.borderColor = game.starter.badgeBorder;
    } else {
      ui.starterNameLabel.textContent = 'BASKET POKÉBALL';
      ui.starterTypeLabel.innerHTML = `<i></i>1/3 RED STARTER (STEAL ${game.heroRival}'S BIKE!)`;
    }

    if (ui.bikeToggle) {
      ui.bikeToggle.querySelector('span').textContent = !game.bikeStolen
        ? `🚲 Steal ${game.heroRival}'s Bike`
        : game.ridingBike
          ? '🚲 Bike: Riding'
          : '🚲 Bike: Walking';
    }

    ui.rankDisplay.textContent = rankObj.title;
    ui.rankTierPill.textContent = `RANK ${game.rankIndex + 1} / ${RANKS.length}`;
    if (game.rankIndex < RANKS.length - 1) {
      ui.meritDisplay.textContent = `${game.merits} / ${rankObj.nextMerits} MERITS`;
      const pct = clamp(((game.merits - rankObj.minMerits) / (rankObj.nextMerits - rankObj.minMerits)) * 100, 6, 100);
      ui.rankBar.style.width = `${pct}%`;
    } else {
      ui.meritDisplay.textContent = `${game.merits} MERITS (MAX)`;
      ui.rankBar.style.width = '100%';
    }

    // Update Player, Base, and Business Upgrade rows
    if (ui.upgradesSummary) {
      ui.upgradesSummary.textContent = `RANK ${game.rankIndex + 1} PERKS ACTIVE`;
    }
    if (ui.playerUpgLvl) {
      ui.playerUpgLvl.textContent = `LV.${game.playerUpgrade + 1}`;
      ui.playerUpgName.textContent = pUpg.name;
      const maxP = game.playerUpgrade >= PLAYER_UPGRADES.length - 1;
      ui.btnUpgPlayer.textContent = maxP ? 'MAXED' : `UPGRADE (₽${pUpg.cost})`;
      ui.btnUpgPlayer.classList.toggle('maxed', maxP);
    }
    if (ui.baseUpgLvl) {
      ui.baseUpgLvl.textContent = `LV.${game.baseUpgrade + 1}`;
      ui.baseUpgName.textContent = baseUpg.name;
      const maxB = game.baseUpgrade >= BASE_UPGRADES.length - 1;
      ui.btnUpgBase.textContent = maxB ? 'MAXED' : `UPGRADE (₽${baseUpg.cost})`;
      ui.btnUpgBase.classList.toggle('maxed', maxB);
    }
    if (ui.bizUpgLvl) {
      ui.bizUpgLvl.textContent = `LV.${game.bizUpgrade + 1}`;
      ui.bizUpgName.textContent = bizUpg.name;
      const maxBiz = game.bizUpgrade >= BIZ_UPGRADES.length - 1;
      ui.btnUpgBiz.textContent = maxBiz ? 'MAXED' : `UPGRADE (₽${bizUpg.cost})`;
      ui.btnUpgBiz.classList.toggle('maxed', maxBiz);
    }

    ui.gruntCallsign.textContent = `GRUNT ${game.playerName} • ${rankObj.title}`;
    ui.jobLedger.textContent = `FUNDS: ₽${game.funds} • SHIFTS: ${game.cornerShifts + game.daycareShifts}`;
    ui.fundsReadout.textContent = `FUNDS: ₽${game.funds} • POKEBALLS: ${game.orbs}`;

    if (!game.bikeStolen) {
      ui.goal.textContent = `Leave Rundown Base initiation & steal ${game.heroRival}'s bike (+1/3 Red Starter Pokéball)`;
      ui.goalCheck.textContent = '○';
      ui.progress.style.width = '18%';
      ui.noteTitle.textContent = `INITIATION HEIST: ${game.heroRival}'S BIKE`;
      ui.note.textContent = `Step out the south door (or press SPACE) to steal ${game.heroRival}'s bike and claim the 1 Pokéball (1/3 Bulbasaur, Charmander, or Squirtle).`;
    } else if (game.rankIndex >= 4) {
      ui.goal.textContent = `Executive status achieved! Rule Sunmeadow with ${game.starter.name}.`;
      ui.goalCheck.textContent = '✓';
      ui.progress.style.width = '100%';
    } else {
      ui.goal.textContent = `Get promoted to ${RANKS[game.rankIndex + 1].title} to unlock next Player, Base & Business Upgrades`;
      ui.goalCheck.textContent = '★';
      ui.progress.style.width = `${clamp(28 + game.merits, 28, 98)}%`;
      ui.noteTitle.textContent = `STOLEN BIKE & ${game.starter.name} ACQUIRED!`;
      ui.note.textContent = `1 Pokéball on ${game.heroRival}'s bike had ${game.starter.name}! Rank up to unlock Player, Base & Business Upgrades.`;
    }

    if (game.mode === 'intro') ui.action.textContent = 'LEAVE INITIATION';
    else if (!game.bikeStolen) ui.action.textContent = 'STEAL BIKE & BALL';
    else if (game.mode === 'battle') ui.action.textContent = 'BATTLE ACT';
    else if (game.mode === 'slots') ui.action.textContent = game.slots.spinning ? 'STOP REEL' : 'SPIN SLOTS';
    else ui.action.textContent = 'INTERACT / TALK';
  }

  function sanitizeName(val, fallback) {
    const cleaned = (val || '').trim().toUpperCase().replace(/[^A-Z0-9 _-]/g, '').slice(0, 10);
    return cleaned || fallback;
  }

  function confirmIntroNames(e) {
    if (e) e.preventDefault();
    game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
    game.rocketRival = sanitizeName(ui.rocketRivalInput.value, 'VIPER');
    game.heroRival = sanitizeName(ui.heroRivalInput.value, 'RED');

    ui.playerInput.value = game.playerName;
    ui.rocketRivalInput.value = game.rocketRival;
    ui.heroRivalInput.value = game.heroRival;

    ui.introOverlay.hidden = true;
    if (game.mode === 'intro') {
      game.mode = 'map';
      stealRivalBike();
    } else {
      updateUI();
    }
  }

  function openIntroModal() {
    ui.playerInput.value = game.playerName;
    ui.rocketRivalInput.value = game.rocketRival;
    ui.heroRivalInput.value = game.heroRival;
    ui.introOverlay.hidden = false;
    game.mode = 'intro';
    updateUI();
  }

  function openGameCornerSlots() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    game.x = 16;
    game.y = 9;
    game.facing = 'up';
    game.mode = 'slots';
    game.slots.spinning = false;
    game.slots.locked = [true, true, true];
    game.slots.banner = 'PRESS SPACE/1 TO SPIN (₽10) OR 2 TO WORK SHIFT & RIG JACKPOT!';
    game.message = `Grunt ${game.playerName} rode the stolen bike to the Rocket Game Corner slot machine!`;
    updateUI();
  }

  function startOrStopSlotSpin() {
    const s = game.slots;
    if (s.spinning) {
      const nextIdx = s.locked.findIndex(locked => !locked);
      if (nextIdx !== -1) lockReel(nextIdx);
      return;
    }
    if (game.funds < 10 && !s.rigged) {
      workGameCornerShift();
      return;
    }
    if (!s.rigged) game.funds -= 10;
    s.spinning = true;
    s.spins++;
    s.locked = [false, false, false];
    const now = performance.now();
    s.stopTimes = [now + 320, now + 620, now + 920];
    s.banner = 'REELS SPINNING... PRESS SPACE OR CLICK TO LOCK REELS!';
    updateUI();
  }

  function lockReel(idx) {
    const s = game.slots;
    if (s.locked[idx]) return;
    s.locked[idx] = true;
    if (s.rigged) {
      s.reels[idx] = 0;
    } else if (idx > 0 && Math.random() < 0.48) {
      s.reels[idx] = s.reels[0];
    } else {
      s.reels[idx] = rnd(0, SLOT_SYMBOLS.length - 1);
    }
    if (s.locked.every(Boolean)) finishSlotSpin();
  }

  function finishSlotSpin() {
    const s = game.slots;
    const biz = BIZ_UPGRADES[game.bizUpgrade];
    s.spinning = false;
    const [r0, r1, r2] = s.reels;
    const sym0 = SLOT_SYMBOLS[r0];
    if (r0 === r1 && r1 === r2) {
      const winFunds = Math.round(sym0.payout * biz.slotMult);
      game.funds += winFunds;
      if (sym0.orb) game.orbs += sym0.orb;
      s.lastWin = winFunds;
      s.rigged = false;
      s.banner = `JACKPOT! 3× ${sym0.name}! WON +₽${winFunds}${sym0.orb ? ' & +1 POKEBALL' : ''}!`;
      game.message = `Slot Jackpot at the Game Corner! Won +₽${winFunds} and +${sym0.merits} Merits!`;
      addMerits(sym0.merits, `Slot Jackpot (3× ${sym0.name})`);
    } else if (r0 === r1 || r1 === r2 || r0 === r2) {
      const pairSym = r0 === r1 ? SLOT_SYMBOLS[r0] : SLOT_SYMBOLS[r2];
      const winFunds = Math.round(90 * biz.slotMult);
      game.funds += winFunds;
      s.lastWin = winFunds;
      s.rigged = false;
      s.banner = `NICE MATCH! PAIR OF ${pairSym.name}S! WON +₽${winFunds} & +15 MERITS!`;
      game.message = `Matched a pair of ${pairSym.name}s on the Game Corner slots! +₽${winFunds}.`;
      addMerits(15, 'Game Corner Slot Match');
    } else {
      s.lastWin = 0;
      s.rigged = false;
      s.banner = 'NO MATCH! PRESS 2 TO WORK SHIFT & RIG THE MACHINE FOR A JACKPOT!';
      game.message = 'Reels missed! Tip: Work a Game Corner shift (2) to rig the next spin!';
      updateUI();
    }
  }

  function workGameCornerShift() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const biz = BIZ_UPGRADES[game.bizUpgrade];
    game.cornerShifts++;
    game.funds += biz.cornerPay;
    game.slots.rigged = true;
    game.slots.banner = `SHIFT WORKED (+₽${biz.cornerPay})! MAGNET RIGGED: SPIN FOR GUARANTEED JACKPOT!`;
    game.message = `Grunt ${game.playerName} worked a Game Corner shift (+₽${biz.cornerPay}, +25 Merits) and rigged the slot machine!`;
    addMerits(25, 'Worked Game Corner Shift');
    if (game.mode !== 'slots') openGameCornerSlots();
  }

  function workDaycareShift() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    if (game.mode === 'slots') game.mode = 'map';
    const biz = BIZ_UPGRADES[game.bizUpgrade];
    game.x = 5;
    game.y = 17;
    game.facing = 'up';
    game.daycareShifts++;
    game.funds += biz.daycarePay;
    game.hp = game.maxHp;
    game.xp += biz.xpGain;
    let leveled = false;
    while (game.xp >= 24) {
      game.xp -= 24;
      game.level++;
      game.maxHp += 3;
      game.hp = game.maxHp;
      leveled = true;
    }
    const stName = game.starter ? game.starter.name : 'Partner';
    game.message = `Grunt ${game.playerName} worked a Daycare shift! Earned +₽${biz.daycarePay}, ${stName} healed${leveled ? ` & reached Lv.${game.level}` : ` (+${biz.xpGain} XP)`}!`;
    addMerits(25, 'Worked Daycare Shift');
  }

  function reportForPromotion() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    if (game.mode === 'slots') game.mode = 'map';
    const prevRank = game.rankIndex;
    const needed = RANKS[game.rankIndex].nextMerits - game.merits;
    const grant = Math.max(25, needed);
    game.talkedVex = true;
    addMerits(grant, 'Commander Vex Promotion');
    const newRankTitle = RANKS[game.rankIndex].title;
    if (game.rankIndex > prevRank) {
      game.message = `Commander Vex: “Promoted to ${newRankTitle}, ${game.playerName}! Unlocked Lv.${game.rankIndex + 1} Player, Base (${BASE_UPGRADES[game.baseUpgrade].name}) & Business (${BIZ_UPGRADES[game.bizUpgrade].name}) Upgrades!”`;
    } else {
      game.message = `Commander Vex: “You've reached the top rank of ${newRankTitle}, ${game.playerName}! All Player, Base & Business Upgrades are maxed!”`;
    }
    updateUI();
  }

  function move(dir) {
    if (game.mode !== 'map') return;
    const delta = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }[dir];
    if (!delta) return;
    game.facing = dir;
    const nx = game.x + delta[0], ny = game.y + delta[1];
    if (!solid(nx, ny)) {
      game.buddyTrail.unshift({ x: game.x, y: game.y });
      if (game.buddyTrail.length > 4) game.buddyTrail.pop();
      game.x = nx;
      game.y = ny;
      game.steps++;
      if (!game.bikeStolen && ny >= baseBounds.doorY) {
        stealRivalBike();
        return;
      }
      if (tileType(game.x, game.y) === 'tall' && game.grassEncounterCooldown <= 0 && Math.random() < 0.2) {
        game.grassEncounterCooldown = 6;
        beginWildBattle();
      }
      updateUI();
    } else {
      const hitNpc = npcAt(nx, ny);
      if (hitNpc) interactWithRole(hitNpc.role);
    }
  }

  function interactWithRole(role) {
    if (role === 'stealBike') {
      stealRivalBike();
    } else if (role === 'vex') {
      reportForPromotion();
    } else if (role === 'rocketRival') {
      beginRivalBattle('rocket');
    } else if (role === 'heroRival') {
      beginRivalBattle('hero');
    } else if (role === 'cornerBoss') {
      openGameCornerSlots();
    } else if (role === 'daycareKeeper') {
      workDaycareShift();
    } else if (role === 'tall') {
      beginWildBattle();
    }
  }

  function interact() {
    if (game.mode === 'intro') {
      confirmIntroNames();
      return;
    }
    if (!game.bikeStolen) {
      stealRivalBike();
      return;
    }
    if (game.mode === 'slots') {
      startOrStopSlotSpin();
      return;
    }
    if (game.mode === 'battle') {
      battleContinue();
      return;
    }
    if (game.mode !== 'map') return;
    const near = nearbyInteraction();
    if (near) {
      interactWithRole(near);
    } else {
      game.message = `Grunt ${game.playerName} (${RANKS[game.rankIndex].title}) rides ${game.heroRival}'s stolen bike with ${game.starter.name}.`;
      updateUI();
    }
  }

  function beginWildBattle() {
    ensureBikeStolen();
    const base = creatures[rnd(0, creatures.length - 1)];
    const enemy = {
      ...base,
      level: rnd(2, Math.max(3, game.level - 1)),
      maxHp: base.hp + rnd(0, 4)
    };
    enemy.hp = enemy.maxHp;
    game.mode = 'battle';
    game.battle = {
      trainer: null,
      rivalKind: null,
      enemy,
      phase: 'intro',
      message: `A wild ${enemy.name} jumped out at ${game.playerName}'s stolen ${game.starter.name}!`,
      turn: 0
    };
    game.message = game.battle.message;
    updateUI();
  }

  function beginRivalBattle(kind) {
    ensureBikeStolen();
    const isRocket = kind === 'rocket';
    const trainerName = isRocket ? `ROCKET RIVAL ${game.rocketRival}` : `PROTAGONIST ${game.heroRival}`;
    const enemy = isRocket
      ? { name: 'SHADEFANG', kind: 'SHADOW', color: '#8d73b8', accent: '#553c7a', level: game.level, maxHp: 24, hp: 24 }
      : { name: 'PIKACHU', kind: 'ELECTRIC', color: '#f6cb49', accent: '#d98a2b', level: game.level, maxHp: 26, hp: 26 };
    game.mode = 'battle';
    game.battle = {
      trainer: trainerName,
      rivalKind: kind,
      enemy,
      phase: 'intro',
      message: isRocket
        ? `${game.rocketRival}: “You stole ${game.heroRival}'s bike AND got ${game.starter.name}?! Hand over that promotion, ${game.playerName}!”`
        : `${game.heroRival}: “Grunt ${game.playerName}! Give back my stolen Bike and my ${game.starter.name} Pokéball right now!”`,
      turn: 0
    };
    game.message = game.battle.message;
    updateUI();
  }

  function enemyTurn() {
    const b = game.battle;
    if (!b || game.mode !== 'battle') return;
    const damage = rnd(2, 5);
    game.hp = Math.max(1, game.hp - damage);
    b.phase = 'enemyMsg';
    b.message = `${b.enemy.name} counterattacked! ${game.starter.name} took −${damage} HP.`;
    game.message = b.message;
    updateUI();
  }

  function attack(kind) {
    const b = game.battle;
    if (!b || b.phase !== 'menu') return;
    const starter = game.starter || RED_STARTERS[1];
    const pUpg = PLAYER_UPGRADES[game.playerUpgrade];
    if (kind === 'snack') {
      if (game.potions <= 0) {
        b.phase = 'enemyMsg';
        b.message = 'No Rations left in your Rocket kit!';
        return;
      }
      game.potions--;
      const healed = Math.min(pUpg.rationHeal, game.maxHp - game.hp);
      game.hp += healed;
      b.phase = 'enemyMsg';
      b.message = `${starter.name} ate a Rocket Ration! Restored +${healed || 1} HP.`;
      updateUI();
      return;
    }
    if (kind === 'orb') {
      if (b.trainer) {
        const chip = 5 + game.rankIndex + pUpg.atkBonus;
        b.enemy.hp = Math.max(1, b.enemy.hp - chip);
        b.phase = 'enemyMsg';
        b.message = `${game.playerName} rang the stolen bike bell to taunt ${b.trainer}! (−${chip} HP)!`;
        b.pendingEnemy = true;
        return;
      }
      if (game.orbs <= 0) {
        b.phase = 'enemyMsg';
        b.message = 'Out of Pokéballs! Win more at the Game Corner!';
        return;
      }
      game.orbs--;
      b.phase = 'enemyMsg';
      b.message = `Grunt ${game.playerName} threw a Pokéball at wild ${b.enemy.name}...`;
      b.pendingCapture = true;
      updateUI();
      return;
    }

    const moveLabel = kind === 'spark' ? starter.move1 : starter.move2;
    const damage = (kind === 'spark' ? rnd(10, 14) : rnd(7, 10)) + game.level + pUpg.atkBonus;
    b.enemy.hp = Math.max(0, b.enemy.hp - damage);
    b.turn++;
    if (b.enemy.hp <= 0) {
      game.wins++;
      game.xp += 14;
      game.funds += b.trainer ? 140 : 60;
      if (game.xp >= 24) {
        game.xp -= 24;
        game.level++;
        game.maxHp += 3;
        game.hp = game.maxHp;
      }
      b.phase = 'winMsg';
      if (b.rivalKind === 'rocket') {
        game.defeatedRocketRival = true;
        b.message = `Defeated Rocket Rival ${game.rocketRival} with ${starter.name}! +₽140 & +40 Merits!`;
      } else if (b.rivalKind === 'hero') {
        game.defeatedHeroRival = true;
        b.message = `Defeated Protagonist ${game.heroRival} and kept his stolen bike! +₽140 & +40 Merits!`;
      } else {
        b.message = `Wild ${b.enemy.name} fainted! Earned +₽60 & +25 Merits!`;
      }
      game.message = b.message;
      addMerits(b.trainer ? 40 : 25, b.trainer ? `Defeated ${b.trainer}` : `Defeated ${b.enemy.name}`);
    } else {
      b.phase = 'enemyMsg';
      b.message = `${starter.name} used ${moveLabel}! −${damage} HP to ${b.enemy.name}!`;
      b.pendingEnemy = true;
    }
    updateUI();
  }

  function battleContinue() {
    const b = game.battle;
    if (!b) return;
    if (b.phase === 'intro') {
      b.phase = 'menu';
      return;
    }
    if (b.phase === 'enemyMsg') {
      if (b.pendingCapture) {
        b.pendingCapture = false;
        game.caught++;
        game.wins++;
        game.funds += 80;
        const caughtName = b.enemy.name;
        game.mode = 'map';
        game.battle = null;
        game.grassEncounterCooldown = 7;
        game.message = `Captured ${caughtName} in a Pokéball! Added to ${game.playerName}'s Team Rocket squad!`;
        addMerits(35, `Captured ${caughtName}`);
        return;
      }
      if (b.pendingEnemy) {
        b.pendingEnemy = false;
        enemyTurn();
        return;
      }
      b.phase = 'menu';
      return;
    }
    if (b.phase === 'winMsg') {
      game.mode = 'map';
      game.battle = null;
      game.grassEncounterCooldown = 7;
      updateUI();
    }
  }

  function keyDown(e) {
    if (document.activeElement && document.activeElement.tagName === 'INPUT') {
      if (e.key === 'Enter') confirmIntroNames(e);
      return;
    }

    const key = e.key.toLowerCase();
    if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' ', 'enter'].includes(key)) {
      e.preventDefault();
    }
    if (game.keys[key]) return;
    game.keys[key] = true;

    if (game.mode === 'intro') {
      if (key === 'enter' || key === ' ') confirmIntroNames(e);
      return;
    }

    if (game.mode === 'slots') {
      if (key === '1' || key === ' ' || key === 'enter' || key === 'z') startOrStopSlotSpin();
      else if (key === '2' || key === 'r') workGameCornerShift();
      else if (key === '3') {
        if (game.funds >= 80) {
          game.funds -= 80;
          game.orbs++;
          game.slots.banner = 'EXCHANGED ₽80 FOR +1 POKEBALL!';
          showToast('Purchased +1 Pokéball at Game Corner!');
          updateUI();
        } else {
          game.slots.banner = 'NEED ₽80 FOR A BALL! WORK A SHIFT (2) FOR +₽100!';
        }
      } else if (key === '4' || key === 'escape' || key === 'x') {
        game.mode = 'map';
        game.message = `Stepped out of the Rocket Game Corner with ₽${game.funds}.`;
        updateUI();
      }
      return;
    }

    if (game.mode === 'battle') {
      if (game.battle?.phase === 'menu') {
        if (key === '1' || key === 'z' || key === ' ' || key === 'enter') attack('spark');
        else if (key === '2' || key === 'x') attack('tail');
        else if (key === '3') attack('snack');
        else if (key === '4') attack('orb');
      } else if (key === ' ' || key === 'enter' || key === 'z') {
        battleContinue();
      }
      return;
    }

    if (key === 'b') {
      if (!game.bikeStolen) stealRivalBike();
      else {
        game.ridingBike = !game.ridingBike;
        showToast(game.ridingBike ? `Riding ${game.heroRival}'s stolen bike!` : 'Disembarked stolen bike.');
        updateUI();
      }
      return;
    }
    if (key === 'g') { openGameCornerSlots(); return; }
    if (key === 'c') { workDaycareShift(); return; }
    if (key === 'p') { reportForPromotion(); return; }

    const dirs = {
      arrowup: 'up', w: 'up',
      arrowdown: 'down', s: 'down',
      arrowleft: 'left', a: 'left',
      arrowright: 'right', d: 'right'
    };
    if (dirs[key]) move(dirs[key]);
    else if (key === ' ' || key === 'enter' || key === 'z') interact();
  }

  function keyUp(e) {
    game.keys[e.key.toLowerCase()] = false;
  }

  window.addEventListener('keydown', keyDown);
  window.addEventListener('keyup', keyUp);

  document.querySelectorAll('.preset-list').forEach(group => {
    const targetId = group.dataset.target;
    const inputEl = $(targetId);
    group.querySelectorAll('.name-preset-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        group.querySelectorAll('.name-preset-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        inputEl.value = btn.dataset.name;
        game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
