      lastWin: 0,
      spins: 0,
      banner: '1: SPIN (₽10)  •  2: WORK/RIG  •  3: UNDERGROUND FIGHT TOURNEY'
    },
    sound: true,
    keys: {},
    lastTime: 0,
    anim: 0,
    grassEncounterCooldown: 0
  };

  const mapW = 32, mapH = 26;
  const path = new Set();
  const addPath = (x1, y1, x2, y2) => {
    let x = x1, y = y1;
    path.add(`${x},${y}`);
    while (x !== x2) { x += Math.sign(x2 - x); path.add(`${x},${y}`); }
    while (y !== y2) { y += Math.sign(y2 - y); path.add(`${x},${y}`); }
  };

  // Connect Rundown Base doorway (7,9) to Daycare (5,16), Game Corner (16,8), Gym (19,19), and Victory Road Gate (26,6)
  addPath(7, 9, 7, 16);
  addPath(5, 16, 12, 16);
  addPath(12, 19, 12, 8);
  addPath(12, 8, 26, 8);
  addPath(26, 8, 26, 5);
  addPath(12, 12, 25, 12);
  addPath(12, 19, 19, 19);

  const baseBounds = { x1: 2, y1: 2, x2: 11, y2: 9, doorX: 7, doorY: 9 };
  const bikeSpot = { x: 7, y: 10 };
  const victoryGate = { x: 26, y: 5 };
  const grassAreas = [
    { x: 21, y: 9, w: 8, h: 4 },
    { x: 23, y: 14, w: 6, h: 6 },
    { x: 4, y: 19, w: 7, h: 4 }
  ];
  const ponds = [{ x: 28, y: 2, w: 3, h: 3 }];
  const solids = new Set();

  for (let x = 0; x < mapW; x++) { solids.add(`${x},0`); solids.add(`${x},${mapH - 1}`); }
  for (let y = 0; y < mapH; y++) { solids.add(`0,${y}`); solids.add(`${mapW - 1},${y}`); }

  for (let x = baseBounds.x1; x <= baseBounds.x2; x++) {
    solids.add(`${x},${baseBounds.y1}`);
    if (x !== baseBounds.doorX) solids.add(`${x},${baseBounds.y2}`);
  }
  for (let y = baseBounds.y1; y <= baseBounds.y2; y++) {
    solids.add(`${baseBounds.x1},${y}`);
    solids.add(`${baseBounds.x2},${y}`);
  }
  [[3, 3], [4, 3], [10, 3], [3, 8]].forEach(([cx, cy]) => solids.add(`${cx},${cy}`));

  const buildings = [
    { x: 14, y: 4, w: 6, h: 4, type: 'corner', label: 'GAME CORNER' },
    { x: 3, y: 12, w: 5, h: 4, type: 'daycare', label: 'DAYCARE & LAB' },
    { x: 16, y: 15, w: 6, h: 4, type: 'gym', label: 'KANTO GYM' }
  ];
  buildings.forEach(b => {
    for (let y = b.y; y < b.y + b.h; y++)
      for (let x = b.x; x < b.x + b.w; x++)
        solids.add(`${x},${y}`);
  });

  const trees = [
    [22, 3], [23, 3], [29, 6], [29, 7], [30, 7],
    [28, 21], [29, 21], [30, 21], [12, 23], [13, 23], [14, 23], [15, 23],
    [16, 23], [17, 23], [18, 23], [19, 23], [20, 23], [21, 23], [22, 23],
    [23, 23], [24, 23], [25, 23], [26, 23], [27, 23], [28, 23], [29, 23]
  ];
  trees.forEach(([x, y]) => solids.add(`${x},${y}`));

  const npcs = {
    vex: { x: 7, y: 4, role: 'vex' },
    rocketRival: { x: 9, y: 6, role: 'rocketRival' },
    heroRival: { x: 8, y: 10, role: 'heroRival' },
    cornerBoss: { x: 16, y: 8, role: 'cornerBoss' },
    daycareKeeper: { x: 5, y: 16, role: 'daycareKeeper' },
    gymLeader: { x: 19, y: 19, role: 'gymLeader' },
    victoryGuard: { x: 26, y: 5, role: 'victoryGuard' }
  };

  function inRundownBase(x, y) {
    return x >= baseBounds.x1 && x <= baseBounds.x2 && y >= baseBounds.y1 && y <= baseBounds.y2;
  }

  function currentAreaName() {
    if (game.mode === 'slots') return 'CORNER SLOTS & FIGHT PIT';
    if (game.mode === 'daycare') return 'DAYCARE BREEDING & FUSION LAB';
    if (game.mode === 'victory') return 'VICTORY ROAD & ELITE 4';
    if (game.mode === 'management') return 'EXECUTIVE SYNDICATE HQ';
    if (inRundownBase(game.x, game.y)) return BASE_UPGRADES[game.baseUpgradeIdx].label;
    if (Math.abs(game.x - npcs.cornerBoss.x) + Math.abs(game.y - npcs.cornerBoss.y) <= 3) return 'GAME CORNER PLAZA';
    if (Math.abs(game.x - npcs.daycareKeeper.x) + Math.abs(game.y - npcs.daycareKeeper.y) <= 3) return 'DAYCARE & SECRET LAB';
    if (Math.abs(game.x - npcs.gymLeader.x) + Math.abs(game.y - npcs.gymLeader.y) <= 3) {
      return game.gymsControlled > 0 ? `ROCKET GYM (${game.gymsControlled}/4)` : 'KANTO GYM PLAZA';
    }
    if (Math.abs(game.x - victoryGate.x) + Math.abs(game.y - victoryGate.y) <= 3) return 'VICTORY ROAD GATE';
    return 'OUTSIDE ROCKET BASE';
  }

  function tileType(x, y) {
    if (x < 0 || y < 0 || x >= mapW || y >= mapH) return 'wall';
    if (inRundownBase(x, y)) return 'baseFloor';
    if (ponds.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'water';
    if (path.has(`${x},${y}`)) return 'path';
    if (grassAreas.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'tall';
    return 'grass';
  }

  function npcAt(x, y) {
    return Object.values(npcs).find(n => n.x === x && n.y === y) || null;
  }

  function solid(x, y) {
    return solids.has(`${x},${y}`) || tileType(x, y) === 'water' || Boolean(npcAt(x, y));
  }

  function rect(x, y, w, h, color) {
    ctx.fillStyle = color;
    ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
  }

  function pixelText(text, x, y, size = 8, color = '#fff', align = 'left') {
    ctx.font = `bold ${size}px monospace`;
    ctx.textAlign = align;
    ctx.textBaseline = 'top';
    ctx.fillStyle = color;
    ctx.fillText(text, Math.round(x), Math.round(y));
  }

  function rounded(x, y, w, h, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
  }

  function stealRivalBike() {
    if (game.bikeStolen && game.starter) return game.starter;
    const chosenStarter = rollRedStarter();
    game.starter = chosenStarter;
    game.bikeStolen = true;
    game.ridingBike = true;
    game.heistDone = 1;
    game.x = bikeSpot.x;
    game.y = bikeSpot.y;
    game.facing = 'down';
    game.buddyTrail = [{ x: bikeSpot.x, y: bikeSpot.y - 1 }];
    game.message = `Left Team Rocket Initiation, met ${game.heroRival}, and stole his Bike! Its 1 Poké Ball contained ${chosenStarter.name} (1/3 Red Starter)!`;
    showToast(`🚲 Stole ${game.heroRival}'s Bike! 1 Poké Ball had ${chosenStarter.name}!`);
    updateUI();
    return chosenStarter;
  }

  function ensureBikeStolen() {
    if (!game.bikeStolen || !game.starter) {
      stealRivalBike();
    }
  }

  function drawTerrain(tx, ty, sx, sy) {
    const type = tileType(tx, ty);
    const seed = (tx * 92821 + ty * 68917) % 97;
    if (type === 'baseFloor') {
      const isWall =
        (ty === baseBounds.y1 || (ty === baseBounds.y2 && tx !== baseBounds.doorX) || tx === baseBounds.x1 || tx === baseBounds.x2);
      if (isWall) {
        rect(sx, sy, T, T, game.baseUpgradeIdx >= 2 ? '#1f293d' : '#2d3340');
        rect(sx, sy, T, 3, game.baseUpgradeIdx >= 3 ? '#f6cb49' : '#454e5e');
        rect(sx + 2, sy + 5, T - 4, 8, game.baseUpgradeIdx >= 1 ? '#2e3b4e' : '#39282c');
        if (game.baseUpgradeIdx === 0) rect(sx + 3, sy + 7, 3, 2, '#7d4842');
      } else {
        const floorA = game.baseUpgradeIdx >= 2 ? '#2b3548' : '#3a404d';
        const floorB = game.baseUpgradeIdx >= 2 ? '#252f42' : '#353b47';
        rect(sx, sy, T, T, (tx + ty) % 2 === 0 ? floorA : floorB);
        if (game.baseUpgradeIdx >= 3 && tx === 7 && ty >= 4 && ty <= 9) {
          rect(sx + 2, sy, T - 4, T, '#8f242c');
          rect(sx + 3, sy, T - 6, T, '#b8323c');
        }
        if (game.baseUpgradeIdx === 0 && seed % 5 === 0) {
          rect(sx + 3, sy + 4, 5, 1, '#262b34');
          rect(sx + 7, sy + 5, 1, 4, '#262b34');
        }
      }
    } else if (type === 'grass') {
      rect(sx, sy, T, T, seed % 5 === 0 ? '#84c28d' : '#8bc995');
      if (seed % 7 === 0) {
        rect(sx + 3, sy + 4, 2, 2, '#a5d6a0');
        rect(sx + 11, sy + 12, 2, 1, '#6eb67c');
      }
    } else if (type === 'path') {
      rect(sx, sy, T, T, '#d7bd85');
      if (seed % 4 === 0) rect(sx + ((seed % 9) + 3), sy + 5, 2, 2, '#c7aa72');
      if (seed % 6 === 0) rect(sx + 3, sy + 12, 3, 1, '#e6d09e');
    } else if (type === 'tall') {
      rect(sx, sy, T, T, '#79bb80');
      const sway = Math.sin(game.anim * 0.003 + tx * 2 + ty) * 1.5;
      rect(sx + 3, sy + 9 + sway, 2, 6, '#438e5c');
      rect(sx + 5, sy + 5 + sway, 2, 9, '#519f66');
      rect(sx + 9, sy + 8 - sway, 2, 7, '#3f8858');
      rect(sx + 12, sy + 4 - sway, 2, 10, '#55a56c');
      rect(sx + 4, sy + 5 + sway, 2, 2, '#9bd296');
      rect(sx + 11, sy + 4 - sway, 2, 2, '#a1d89a');
    } else if (type === 'water') {
      rect(sx, sy, T, T, '#78bbcf');
      rect(sx, sy, 16, 2, '#9cdaeb');
    } else {
      rect(sx, sy, T, T, '#83bd8b');
    }
  }

  function drawRundownBaseDetails(camX, camY) {
    const rx = 6 * T - camX + 6;
    const ry = 5 * T - camY + 2;
    const logoColor = game.baseUpgradeIdx >= 2 ? '#ff4747' : '#b83b3b';
    rect(rx, ry, 20, 22, game.baseUpgradeIdx >= 2 ? '#1c2436' : '#2c313d');
    rect(rx + 3, ry + 2, 4, 18, logoColor);
    rect(rx + 7, ry + 2, 8, 4, logoColor);
    rect(rx + 12, ry + 5, 4, 5, logoColor);
    rect(rx + 7, ry + 9, 7, 4, logoColor);
    rect(rx + 10, ry + 13, 6, 7, logoColor);
    if (game.baseUpgradeIdx === 0) {
      rect(rx + 4, ry + 8, 12, 1, '#3a404d');
      rect(rx + 2, ry + 15, 10, 1, '#353b47');
    }

    [[3, 3], [4, 3], [10, 3], [3, 8]].forEach(([cx, cy], idx) => {
      const sx = cx * T - camX, sy = cy * T - camY;
      if (idx === 1 && game.baseUpgradeIdx >= 1) {
        rect(sx + 1, sy + 1, 14, 14, '#24473b');
        rect(sx + 3, sy + 3, 10, 10, '#63e6be');
        pixelText('+', sx + 8, sy + 4, 8, '#17263a', 'center');
      } else if (idx === 2 && game.baseUpgradeIdx >= 2) {
        rect(sx + 1, sy + 1, 14, 14, '#1e3554');
        rect(sx + 3, sy + 3, 10, 10, '#4dabf7');
      } else {
        rect(sx + 1, sy + 2, 14, 13, idx === 2 ? '#394b59' : '#73533d');
        rect(sx + 2, sy + 3, 12, 3, idx === 2 ? '#597b8c' : '#8f694d');
        rect(sx + 4, sy + 8, 8, 2, '#262b34');
      }
    });

    const bx = 7 * T - camX - 48;
    const by = 2 * T - camY - 4;
    rounded(bx, by, 112, 12, 3, '#211820eb');
    pixelText(BASE_UPGRADES[game.baseUpgradeIdx].label, bx + 56, by + 2, 6, game.baseUpgradeIdx >= 2 ? '#f6cb49' : '#ff7a72', 'center');
  }

  function drawVictoryRoadGate(camX, camY) {
    const gx = victoryGate.x * T - camX - 20;
    const gy = (victoryGate.y - 2) * T - camY;
    const unlocked = game.rankIndex >= 4;
    rect(gx, gy, 56, 26, unlocked ? '#3b2e14' : '#2a2e38');
    rect(gx + 4, gy + 4, 48, 18, unlocked ? '#f6cb49' : '#586273');
    rect(gx + 16, gy + 8, 24, 14, unlocked ? '#1c2b22' : '#231820');
    rounded(gx - 12, gy - 11, 80, 11, 2, '#141d2beb');
    pixelText(
      unlocked ? '🏆 VICTORY RD: OPEN' : '🔒 VICTORY RD (EXEC)',
      gx + 28,
      gy - 9,
      6,
      unlocked ? '#8ef0c0' : '#ff857d',
      'center'
    );
  }

  function drawParkedBikeWithPokeball(px, py) {
    const x = Math.round(px), y = Math.round(py);
    rect(x - 8, y + 6, 16, 3, 'rgba(0,0,0,0.28)');
    rect(x - 7, y + 1, 5, 6, '#232730');
    rect(x - 6, y + 2, 3, 4, '#d5dde6');
    rect(x + 2, y + 1, 5, 6, '#232730');
    rect(x + 3, y + 2, 3, 4, '#d5dde6');
    rect(x - 5, y, 9, 2, '#e04848');
    rect(x - 2, y - 3, 3, 4, '#e04848');
    rect(x + 2, y - 5, 2, 6, '#e04848');
    rect(x + 1, y - 6, 4, 2, '#354352');
    rect(x + 3, y - 5, 6, 3, '#e04848');
    rect(x + 3, y - 2, 6, 2, '#ffffff');
    rect(x + 5, y - 3, 2, 2, '#232730');
    rounded(x - 28, y - 19, 56, 9, 2, '#d9413beb');
    pixelText('🚲 BIKE + 1 BALL', x, y - 18, 6, '#fff', 'center');
  }

  function drawRedStarter(px, py, scale = 1, starterObj = null) {
    const st = starterObj || game.starter || RED_STARTERS[1];
    const base = st.baseName || st.name;
    ctx.save();
    ctx.translate(Math.round(px), Math.round(py));
    ctx.scale(scale, scale);

    // Infinite Splicing Cyber-Genetic Aura when fused!
    if (game.fusionTier > 0) {
      ctx.fillStyle = game.fusionTier % 2 === 1 ? 'rgba(142,240,192,0.35)' : 'rgba(246,203,73,0.38)';
      ctx.beginPath();
      ctx.arc(0, -3, 12 + Math.min(8, game.fusionTier), 0, Math.PI * 2);
      ctx.fill();
    }

    rect(-8, 8, 16, 3, 'rgba(0,0,0,0.28)');

    if (base.includes('BULBASAUR')) {
      rect(-6, -13, 12, 8, game.fusionTier > 0 ? '#7950f2' : '#3f9959');
      rect(-4, -15, 8, 4, game.fusionTier > 0 ? '#f6cb49' : '#6ad178');
      rect(-8, -7, 16, 13, '#6ec287');
      rect(-7, 4, 4, 5, '#52a66d');
      rect(3, 4, 4, 5, '#52a66d');
      rect(2, -4, 3, 3, '#3b8c58');
      rect(-4, -4, 2, 3, '#d94848');
      rect(1, -4, 2, 3, '#d94848');
    } else if (base.includes('SQUIRTLE')) {
      rect(6, -1, 5, 5, '#5aa0c2');
      rect(8, -3, 3, 4, '#3d7fa3');
      rect(-6, -10, 12, 13, game.fusionTier > 0 ? '#e04848' : '#b87d4b');
      rect(-7, -13, 13, 10, '#6db7d6');
      rect(-6, -3, 11, 9, '#f5e4b8');
      rect(-6, 5, 4, 4, '#6db7d6');
      rect(2, 5, 4, 4, '#6db7d6');
      rect(-4, -9, 2, 3, '#232c38');
      rect(2, -9, 2, 3, '#232c38');
    } else {
      rect(7, 0, 4, 3, '#f08750');
      rect(10, -5, 5, 6, game.fusionTier > 0 ? '#7950f2' : '#e04848');
      rect(11, -8, 3, 4, '#f6cb49');
      rect(-6, -13, 12, 16, '#f08750');
      rect(-4, -3, 8, 8, '#f7e2a4');
      rect(-4, -9, 2, 3, '#232c38');
      rect(2, -9, 2, 3, '#232c38');
      rect(-5, 4, 4, 5, '#d46b38');
      rect(2, 4, 4, 5, '#d46b38');
    }
    if (game.fusionTier > 0) {
      // Spliced DNA crown crest
      rect(-3, -17, 6, 3, '#f6cb49');
    }
    ctx.restore();
  }

  function drawTree(sx, sy) {
    rect(sx + 6, sy + 9, 5, 8, '#875d42');
    rect(sx + 4, sy + 14, 9, 3, '#76513e');
    rect(sx + 1, sy + 5, 14, 7, '#39895c');
    rect(sx + 3, sy + 2, 10, 8, '#4b9b66');
    rect(sx + 5, sy, 6, 6, '#5aa873');
  }

  function drawBuilding(b, cameraX, cameraY) {
    const x = b.x * T - cameraX, y = b.y * T - cameraY, w = b.w * T, h = b.h * T;
    if (b.type === 'corner') {
      rect(x + 2, y + 8, w - 4, h - 7, game.bizUpgradeIdx >= 2 ? '#3b244d' : '#2d233b');
      rect(x, y + 4, w, 9, game.bizUpgradeIdx >= 2 ? '#8a5a19' : '#5e2750');
      for (let i = 0; i < b.w; i++) {
        rect(x + i * T + 1, y + 5, 7, 5, i % 2 === 0 ? '#e04848' : '#f6cb49');
      }
      rect(x + 6, y + 15, w - 12, h - 18, '#3d2f52');
      rect(x + 8, y + 19, 20, 14, '#1b1426');
      pixelText('777', x + 18, y + 22, 6, '#f6cb49', 'center');
      rect(x + w - 28, y + 19, 20, 14, '#1b1426');
      pixelText('PIT', x + w - 18, y + 22, 6, '#ff6b6b', 'center');
      rect(x + w / 2 - 7, y + h - 18, 14, 18, '#d94848');
      rect(x + w / 2 - 5, y + h - 16, 10, 14, '#f6cb49');
      rounded(x + w / 2 - 42, y - 4, 84, 12, 3, '#1d1326');
      pixelText('🎰 CORNER & FIGHT PIT', x + w / 2, y - 1, 6, '#f6cb49', 'center');
    } else if (b.type === 'daycare') {
      rect(x + 2, y + 8, w - 4, h - 7, '#f1dfbd');
      rect(x, y + 5, w, 8, game.bizUpgradeIdx >= 1 ? '#3b8f68' : '#66a97b');
      for (let i = 0; i < b.w; i++) {
        rect(x + i * T + 1, y + 5, 7, 5, '#82c596');
      }
      rect(x + w / 2 - 6, y + h - 17, 12, 17, '#896248');
      rect(x + 7, y + 18, 14, 11, '#72aab4');
      rect(x + w - 21, y + 18, 14, 11, '#72aab4');
      rounded(x + w / 2 - 38, y - 4, 76, 12, 3, '#1b2e28');
      pixelText('🧬 DAYCARE & LABS', x + w / 2, y - 1, 6, '#8ef0c0', 'center');
    } else if (b.type === 'gym') {
      const controlled = game.gymsControlled > 0;
      rect(x + 2, y + 8, w - 4, h - 7, controlled ? '#2e1d28' : '#d7c6a2');
      rect(x, y + 4, w, 9, controlled ? '#b82e38' : '#3b6ca8');
      for (let i = 0; i < b.w; i++) {
        rect(x + i * T + 1, y + 5, 7, 5, controlled ? '#f6cb49' : '#6395d1');
      }
      rect(x + 6, y + 15, w - 12, h - 18, controlled ? '#3d2433' : '#f1dfbd');
      rect(x + w / 2 - 7, y + h - 18, 14, 18, controlled ? '#f6cb49' : '#896248');
      rounded(x + w / 2 - 44, y - 4, 88, 12, 3, controlled ? '#2b1218' : '#1c2d42');
      pixelText(
        controlled ? `★ ROCKET GYM (${game.gymsControlled}/4)` : '🏅 KANTO GYM (0/4)',
        x + w / 2,
        y - 1,
        6,
        controlled ? '#f6cb49' : '#ffffff',
        'center'
      );
    }
  }

  function drawPerson(px, py, type, frame = 0) {
    const x = Math.round(px), y = Math.round(py);
    if (type === 'hero') {
      rect(x - 6, y + 9, 13, 3, 'rgba(0,0,0,0.3)');
      if (game.bikeStolen && game.ridingBike) {
        rect(x - 8, y + 5, 5, 6, '#1b1f26');
        rect(x - 7, y + 6, 3, 4, '#cfd8e3');
        rect(x + 3, y + 5, 5, 6, '#1b1f26');
        rect(x + 4, y + 6, 3, 4, '#cfd8e3');
        rect(x - 5, y + 4, 10, 2, game.playerUpgradeIdx >= 1 ? '#f6cb49' : '#e04848');
      }
      rect(x - 5, y - 8, 10, 9, '#f0c79c');
      rect(x - 6, y - 12, 12, 5, '#232730');
      rect(x - 4, y - 9, 9, 2, game.playerUpgradeIdx >= 2 ? '#f6cb49' : '#e04848');
      rect(x - 6, y, 12, 8, game.playerUpgradeIdx >= 3 ? '#3b1e2e' : '#262b36');
      rect(x - 2, y + 2, 4, 4, '#e04848');
      rect(x - 5, y + 7, 4, 5, '#1b1f26');
      rect(x + 2, y + 7, 4, 5, '#1b1f26');
    } else if (type === 'vex') {
      rect(x - 6, y + 9, 13, 3, 'rgba(0,0,0,0.35)');
      rect(x - 5, y - 8, 10, 9, '#ecc39a');
      rect(x - 7, y - 12, 14, 5, '#591e29');
      rect(x - 5, y - 9, 10, 2, '#f6cb49');
      rect(x - 7, y, 14, 9, '#3d1c26');
      rect(x - 2, y + 2, 4, 5, '#f6cb49');
      rect(x - 5, y + 8, 4, 4, '#24151c');
      rect(x + 2, y + 8, 4, 4, '#24151c');
    } else if (type === 'rocketRival') {
      rect(x - 6, y + 9, 13, 3, 'rgba(0,0,0,0.35)');
      rect(x - 5, y - 8, 10, 9, '#f2c9a0');
      rect(x - 6, y - 12, 12, 5, '#6c3b7a');
      rect(x - 6, y, 12, 8, '#30243d');
      rect(x - 2, y + 2, 4, 4, '#ff6b6b');
      rect(x - 5, y + 7, 4, 5, '#221a2b');
      rect(x + 2, y + 7, 4, 5, '#221a2b');
    } else if (type === 'heroRival') {
      rect(x - 6, y + 9, 13, 3, '#4b785d');
      rect(x - 5, y - 8, 10, 9, '#f2c99e');
      rect(x - 6, y - 12, 12, 5, '#d94b43');
      rect(x - 3, y - 10, 6, 2, '#ffffff');
