  // Infinite Splicing with Exponential (2^n) Returns!
  function splicePartnerInFusionLab() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    game.mode = 'daycare';
    game.fusionTier++;
    const expMult = Math.pow(2, game.fusionTier - 1);
    const atkGain = Math.round(10 * expMult);
    const hpGain = Math.round(15 * expMult);
    const fundGain = Math.round(80 * expMult);
    const meritGain = Math.round(30 * Math.pow(1.4, game.fusionTier - 1));

    game.spliceAtkBonus += atkGain;
    game.spliceHpBonus += hpGain;
    game.maxHp += hpGain;
    game.hp = game.maxHp;
    game.funds += fundGain;
    game.level += 1;
    game.starter.name = `${game.starter.baseName}-MK.${game.fusionTier}`;

    game.message = `Underground Fusion Lab spliced ${game.starter.name} (Exponential ×${expMult} Return: +${atkGain} ATK, +${hpGain} HP, +₽${fundGain})!`;
    addMerits(meritGain, `Spliced ${game.starter.name} (+${atkGain} ATK, +${hpGain} HP)`);
  }

