    ui.rocketRivalDisplay.textContent = `${game.rocketRival} / ${game.heroRival}`;
    ui.heroRivalDisplay.textContent = `${game.gymsControlled}/4 GYMS • ${game.rankIndex >= 4 ? 'E4 OPEN' : 'PIT T' + unlockedTiers}`;

    if (ui.starterName && game.starter) {
      ui.starterName.textContent = `${game.starter.name} (${game.starter.number})`;
    }
    if (ui.starterOrigin && game.starter) {
      const spliceText = game.fusionTier > 0 ? ` • SPLICE MK.${game.fusionTier} (+${game.spliceAtkBonus} ATK)` : ` • ${game.starter.kind}`;
