      ui.goal.textContent = `All 4 Gyms controlled & Elite 4 conquered! Infinite Splicing active!`;
      ui.goalCheck.textContent = '✓';
      ui.progress.style.width = '100%';
    } else if (game.rankIndex >= 4) {
      ui.goal.textContent = `Top Rank reached! Conquer Victory Road Elite 4 (${game.eliteFourCleared}/4) & Gyms (${game.gymsControlled}/4)`;
      ui.goalCheck.textContent = '★';
      ui.progress.style.width = '90%';
    } else {
      ui.goal.textContent = `Take over Gyms (${game.gymsControlled}/4), splice DNA, and reach Top Rank for Victory Road`;
      ui.goalCheck.textContent = game.merits > 0 ? '★' : '○';
