    else if (game.mode === 'daycare') ui.action.textContent = 'FUSE / BREED';
    else if (game.mode === 'victory') ui.action.textContent = 'FIGHT ELITE 4';
    else if (game.mode === 'management') ui.action.textContent = 'COLLECT OPS';
    else ui.action.textContent = 'INTERACT / ACT';
