    game.x = 5;
    game.y = 17;
    game.facing = 'up';
    game.mode = 'daycare';
    game.message = `Entered the Daycare Center & Secret Underground Breeding / Infinite Fusion Labs!`;
    updateUI();
  }

  function startOrStopSlotSpin() {
    if (game.mode !== 'slots') openGameCornerSlots();
    const s = game.slots;
    if (s.spinning) {
      const nextIdx = s.locked.findIndex(locked => !locked);
      if (nextIdx !== -1) lockReel(nextIdx);
      return;
    }
    if (game.funds < 10 && !s.rigged) {
      workGameCornerShift();
      return;
    }
    if (!s.rigged) game.funds -= 10;
    s.spinning = true;
    s.spins++;
    s.locked = [false, false, false];
    const now = performance.now();
    s.stopTimes = [now + 280, now + 540, now + 800];
    s.banner = 'REELS SPINNING... CLICK OR PRESS SPACE TO LOCK REELS!';
    updateUI();
  }

  function lockReel(idx) {
    const s = game.slots;
    if (s.locked[idx]) return;
    s.locked[idx] = true;
    if (s.rigged) {
      s.reels[idx] = 0;
    } else if (idx > 0 && Math.random() < 0.48) {
      s.reels[idx] = s.reels[0];
    } else {
      s.reels[idx] = rnd(0, SLOT_SYMBOLS.length - 1);
    }
    if (s.locked.every(Boolean)) finishSlotSpin();
  }

  function finishSlotSpin() {
    const s = game.slots;
    const biz = BIZ_UPGRADES[game.bizUpgradeIdx];
    s.spinning = false;
    const [r0, r1, r2] = s.reels;
    const sym0 = SLOT_SYMBOLS[r0];
    if (r0 === r1 && r1 === r2) {
      const winFunds = Math.round(sym0.payout * biz.slotMult);
      game.funds += winFunds;
      if (sym0.orb) game.orbs += sym0.orb;
      s.lastWin = winFunds;
      s.rigged = false;
      s.banner = `JACKPOT! 3× ${sym0.name}! WON +₽${winFunds}${sym0.orb ? ' & +1 POKÉ BALL' : ''}!`;
      game.message = `Slot Jackpot at the Game Corner! Won +₽${winFunds} and +${sym0.merits} Merits!`;
      addMerits(sym0.merits, `Slot Jackpot (3× ${sym0.name})`);
    } else if (r0 === r1 || r1 === r2 || r0 === r2) {
      const pairSym = r0 === r1 ? SLOT_SYMBOLS[r0] : SLOT_SYMBOLS[r2];
      const winFunds = Math.round(90 * biz.slotMult);
      game.funds += winFunds;
      s.lastWin = winFunds;
      s.rigged = false;
      s.banner = `NICE MATCH! PAIR OF ${pairSym.name}S! WON +₽${winFunds} & +15 MERITS!`;
      game.message = `Matched a pair of ${pairSym.name}s on the Game Corner slots! +₽${winFunds}.`;
      addMerits(15, 'Game Corner Slot Match');
    } else {
      s.lastWin = 0;
      s.rigged = false;
      s.banner = 'NO MATCH! CLICK WORK/RIG (2) FOR GUARANTEED 3× R JACKPOT!';
      game.message = 'Reels missed! Tip: Work/Rig Slots for a guaranteed Jackpot!';
      updateUI();
    }
  }

  function workGameCornerShift() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const biz = BIZ_UPGRADES[game.bizUpgradeIdx];
    game.cornerShifts++;
    game.funds += biz.cornerPay;
    game.slots.rigged = true;
    game.slots.banner = `SHIFT WORKED (+₽${biz.cornerPay})! MAGNET RIGGED: SPIN FOR 3× R JACKPOT!`;
    game.message = `Grunt ${game.playerName} worked a Game Corner shift (+₽${biz.cornerPay}, +25 Merits) and rigged the slot reels!`;
    addMerits(25, 'Worked Game Corner Shift');
    if (game.mode !== 'slots') openGameCornerSlots();
  }

  function workDaycareShift() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const biz = BIZ_UPGRADES[game.bizUpgradeIdx];
    game.daycareShifts++;
    game.funds += biz.daycarePay;
    game.hp = game.maxHp;
    game.xp += biz.xpGain;
    let leveled = false;
    while (game.xp >= 24) {
      game.xp -= 24;
      game.level++;
      game.maxHp += 4;
      game.hp = game.maxHp;
      leveled = true;
    }
    const stName = game.starter ? game.starter.name : 'Starter';
    game.message = `Worked Daycare shift! Earned +₽${biz.daycarePay}, ${stName} healed${leveled ? ` & reached Lv.${game.level}` : ` (+${biz.xpGain} XP)`}!`;
    addMerits(25, 'Worked Daycare Shift');
  }

  function reportForPromotion() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const prevRank = game.rankIndex;
    const needed = RANKS[game.rankIndex].nextMerits - game.merits;
    const grant = Math.max(25, needed);
    game.talkedVex = true;
    addMerits(grant, 'Commander Vex Promotion');
    const newRankTitle = RANKS[game.rankIndex].title;
    if (game.rankIndex > prevRank) {
      game.message = `Commander Vex: “Promoted to ${newRankTitle}, ${game.playerName}! Unlocked Lv.${game.rankIndex + 1} Upgrades & Tournament Tier ${Math.min(5, game.rankIndex + 1)}!”`;
    } else {
      game.message = `Commander Vex: “You hold Top Rank (${newRankTitle}), ${game.playerName}! Victory Road & Advanced Management are yours!”`;
    }
    updateUI();
  }

  function move(dir) {
    if (game.mode !== 'map') return;
    const delta = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }[dir];
    if (!delta) return;
    game.facing = dir;
    const nx = game.x + delta[0], ny = game.y + delta[1];
    if (!solid(nx, ny)) {
      game.buddyTrail.unshift({ x: game.x, y: game.y });
      if (game.buddyTrail.length > 4) game.buddyTrail.pop();
      game.x = nx;
      game.y = ny;
      game.steps++;
      if (!game.bikeStolen && ny >= baseBounds.doorY) {
        stealRivalBike();
        return;
      }
      if (tileType(game.x, game.y) === 'tall' && game.grassEncounterCooldown <= 0 && Math.random() < 0.2) {
        game.grassEncounterCooldown = 6;
        beginWildBattle();
      }
      updateUI();
    } else {
      const hitNpc = npcAt(nx, ny);
      if (hitNpc) interactWithRole(hitNpc.role);
    }
  }

  function interactWithRole(role) {
    if (role === 'stealBike') stealRivalBike();
    else if (role === 'vex') reportForPromotion();
    else if (role === 'rocketRival') beginRivalBattle('rocket');
    else if (role === 'heroRival') beginRivalBattle('hero');
    else if (role === 'cornerBoss') openGameCornerSlots();
    else if (role === 'daycareKeeper') openDaycareAndLabs();
    else if (role === 'gymLeader') challengeKantoGym();
    else if (role === 'victoryGuard') openVictoryRoadAndEliteFour();
    else if (role === 'tall') beginWildBattle();
  }

  function interact() {
    if (game.mode === 'intro') {
      confirmIntroNames();
      return;
    }
    if (!game.bikeStolen) {
      stealRivalBike();
      return;
    }
    if (game.mode === 'slots') {
      startOrStopSlotSpin();
      return;
    }
    if (game.mode === 'daycare') {
      splicePartnerInFusionLab();
      return;
    }
    if (game.mode === 'victory') {
      startEliteFourBout();
      return;
    }
    if (game.mode === 'management') {
      runExecutiveManagementAction(0);
      return;
    }
    if (game.mode === 'battle') {
      if (game.battle?.phase === 'menu') attack('spark');
      else battleContinue();
      return;
    }
    const near = nearbyInteraction();
    if (near) {
      interactWithRole(near);
    } else {
      game.message = `Grunt ${game.playerName} (${RANKS[game.rankIndex].title}) rides ${game.heroRival}'s stolen bike with ${game.starter.name}.`;
      updateUI();
    }
  }

  function beginWildBattle() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const base = creatures[rnd(0, creatures.length - 1)];
    const enemy = {
      ...base,
      level: rnd(3, Math.max(4, game.level)),
      maxHp: base.hp + rnd(0, 4)
    };
    enemy.hp = enemy.maxHp;
    game.mode = 'battle';
    game.battle = {
      trainer: null,
      rivalKind: null,
      enemy,
      phase: 'menu',
      message: `A wild ${enemy.name} jumped out at ${game.playerName}'s ${game.starter.name}!`,
      turn: 0
    };
    game.message = game.battle.message;
    updateUI();
  }

  function beginRivalBattle(kind) {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const isRocket = kind === 'rocket';
    const trainerName = isRocket ? `ROCKET RIVAL ${game.rocketRival}` : `PROTAGONIST ${game.heroRival}`;
    const enemy = isRocket
      ? { name: 'KOFFING', kind: 'POISON', color: '#8d73b8', accent: '#553c7a', level: game.level, maxHp: 24, hp: 24 }
      : { name: 'PIKACHU', kind: 'ELECTRIC', color: '#f6cb49', accent: '#d98a2b', level: game.level, maxHp: 26, hp: 26 };
    game.mode = 'battle';
    game.battle = {
      trainer: trainerName,
      rivalKind: kind,
      enemy,
      phase: 'menu',
      message: isRocket
        ? `${game.rocketRival}: “You stole ${game.heroRival}'s bike AND got ${game.starter.name}?! That promotion is mine, ${game.playerName}!”`
        : `${game.heroRival}: “Grunt ${game.playerName}! Give back my stolen Bike and my ${game.starter.name} Poké Ball right now!”`,
      turn: 0
    };
    game.message = game.battle.message;
    updateUI();
  }

  function enemyTurn() {
    const b = game.battle;
    if (!b || game.mode !== 'battle') return;
    const damage = rnd(2, 5);
    game.hp = Math.max(1, game.hp - damage);
    b.phase = 'enemyMsg';
    b.message = `${b.enemy.name} counterattacked! ${game.starter.name} took −${damage} HP.`;
    game.message = b.message;
    updateUI();
  }

  function attack(kind) {
    const b = game.battle;
    if (!b || b.phase !== 'menu') return;
    const starter = game.starter || RED_STARTERS[1];
    const pUpg = PLAYER_UPGRADES[game.playerUpgradeIdx];
    if (kind === 'snack') {
      if (game.potions <= 0) {
        b.phase = 'enemyMsg';
        b.message = 'No Rations left in your Rocket kit!';
        return;
      }
      game.potions--;
      const healed = Math.min(18 + pUpg.lvl * 4, game.maxHp - game.hp);
      game.hp += healed;
      b.phase = 'enemyMsg';
      b.message = `${starter.name} ate a Rocket Ration! Restored +${healed || 1} HP.`;
      updateUI();
      return;
    }
    if (kind === 'orb') {
      if (b.trainer) {
        const chip = 8 + totalAttackBonus();
        b.enemy.hp = Math.max(1, b.enemy.hp - chip);
        b.phase = 'enemyMsg';
        b.message = `${game.playerName} intimidated ${b.trainer}! (−${chip} HP)!`;
        b.pendingEnemy = true;
        return;
      }
      if (game.orbs <= 0) {
        b.phase = 'enemyMsg';
        b.message = 'Out of Poké Balls! Win more at the Game Corner!';
        return;
      }
      game.orbs--;
      b.phase = 'enemyMsg';
      b.message = `Grunt ${game.playerName} threw a Poké Ball at wild ${b.enemy.name}...`;
      b.pendingCapture = true;
      updateUI();
      return;
    }

    const moveLabel = kind === 'spark'
      ? (game.fusionTier > 0 ? starter.fusedMove : starter.move1)
      : starter.move2;
    const damage = (kind === 'spark' ? rnd(12, 16) : rnd(8, 12)) + game.level + totalAttackBonus();
    b.enemy.hp = Math.max(0, b.enemy.hp - damage);
    b.turn++;
    if (b.enemy.hp <= 0) {
      game.wins++;
      game.xp += 16;
      if (game.xp >= 24) {
        game.xp -= 24;
        game.level++;
        game.maxHp += 4;
        game.hp = game.maxHp;
      }
      b.phase = 'winMsg';
      if (b.rivalKind === 'gym') {
        game.gymsControlled = Math.min(4, game.gymsControlled + 1);
        game.funds += b.gymObj.tribute;
        b.message = `Conquered ${b.gymObj.gymName}! It is now under your Team Rocket control (${game.gymsControlled}/4 Gyms)! +₽${b.gymObj.tribute}!`;
        game.message = b.message;
        addMerits(b.gymObj.merits, `${b.gymObj.gymName} Under Your Control (${game.gymsControlled}/4)!`);
      } else if (b.rivalKind === 'tournament') {
        game.tourneyCleared = Math.max(game.tourneyCleared, b.tourneyTier);
        game.funds += b.prize;
        b.message = `Won Underground Fight Tournament Tier ${b.tourneyTier}! +₽${b.prize} & +${b.merits} Merits!`;
        game.message = b.message;
        addMerits(b.merits, `Won Underground Fight Pit Tier ${b.tourneyTier}!`);
      } else if (b.rivalKind === 'elite4') {
        game.eliteFourCleared = Math.max(game.eliteFourCleared, b.e4Stage);
        game.funds += b.prize;
        b.message = `Defeated ${b.trainer} on Victory Road (${game.eliteFourCleared}/4 Elite 4)! +₽${b.prize}!`;
        game.message = b.message;
        addMerits(50, `Conquered ${b.trainer} (${game.eliteFourCleared}/4 Elite 4)!`);
      } else if (b.rivalKind === 'rocket') {
        game.defeatedRocketRival = true;
        game.funds += 150;
        b.message = `Defeated Rocket Rival ${game.rocketRival} with ${starter.name}! +₽150 & +40 Merits!`;
        game.message = b.message;
        addMerits(40, `Defeated Rocket Rival ${game.rocketRival}`);
      } else if (b.rivalKind === 'hero') {
        game.defeatedHeroRival = true;
        game.funds += 150;
        b.message = `Defeated Protagonist ${game.heroRival} and kept his stolen bike! +₽150 & +40 Merits!`;
        game.message = b.message;
        addMerits(40, `Defeated Protagonist ${game.heroRival}`);
      } else {
        game.funds += 70;
        b.message = `Wild ${b.enemy.name} fainted! Earned +₽70 & +25 Merits!`;
        game.message = b.message;
        addMerits(25, `Defeated ${b.enemy.name}`);
      }
    } else {
      b.phase = 'enemyMsg';
      b.message = `${starter.name} used ${moveLabel}! −${damage} HP to ${b.enemy.name}!`;
      b.pendingEnemy = true;
    }
    updateUI();
  }

  function battleContinue() {
    const b = game.battle;
    if (!b) return;
    if (b.phase === 'intro') {
      b.phase = 'menu';
      return;
    }
    if (b.phase === 'enemyMsg') {
      if (b.pendingCapture) {
        b.pendingCapture = false;
        game.caught++;
        game.wins++;
        game.funds += 90;
        const caughtName = b.enemy.name;
        game.mode = 'map';
        game.battle = null;
        game.grassEncounterCooldown = 7;
        game.message = `Captured ${caughtName} in a Poké Ball! Ready for Underground Fusion Splicing!`;
        addMerits(35, `Captured ${caughtName}`);
        return;
      }
      if (b.pendingEnemy) {
        b.pendingEnemy = false;
        enemyTurn();
        return;
      }
      b.phase = 'menu';
      return;
    }
    if (b.phase === 'winMsg') {
      const wasTourney = b.rivalKind === 'tournament';
      const wasE4 = b.rivalKind === 'elite4';
      game.battle = null;
      game.grassEncounterCooldown = 7;
      game.mode = wasTourney ? 'slots' : wasE4 ? 'victory' : 'map';
      updateUI();
    }
  }

  function keyDown(e) {
    if (document.activeElement && document.activeElement.tagName === 'INPUT') {
      if (e.key === 'Enter') confirmIntroNames(e);
      return;
    }

    const key = e.key.toLowerCase();
    if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' ', 'enter'].includes(key)) {
      e.preventDefault();
    }
    if (game.keys[key]) return;
    game.keys[key] = true;

    if (game.mode === 'intro') {
      if (key === 'enter' || key === ' ') confirmIntroNames(e);
      return;
    }

    if (game.mode === 'slots') {
      if (key === '1' || key === ' ' || key === 'enter') startOrStopSlotSpin();
      else if (key === '2' || key === 'r') workGameCornerShift();
      else if (key === '3' || key === 't') startUndergroundTournamentBout();
      else if (key === '4' || key === 'escape') { game.mode = 'map'; updateUI(); }
      return;
    }

    if (game.mode === 'daycare') {
      if (key === '1') workDaycareShift();
      else if (key === '2') breedEggInUndergroundLab();
      else if (key === '3' || key === ' ' || key === 'enter') splicePartnerInFusionLab();
      else if (key === '4' || key === 'escape') { game.mode = 'map'; updateUI(); }
      return;
    }

    if (game.mode === 'victory') {
      if (key === '1' || key === '2' || key === ' ' || key === 'enter') startEliteFourBout();
      else if (key === '3') openExecutiveManagement();
      else if (key === '4' || key === 'escape') { game.mode = 'map'; updateUI(); }
      return;
    }

    if (game.mode === 'management') {
      if (key === '1') runExecutiveManagementAction(0);
      else if (key === '2') runExecutiveManagementAction(1);
      else if (key === '3') runExecutiveManagementAction(2);
      else if (key === '4' || key === 'escape') runExecutiveManagementAction(3);
      return;
    }

    if (game.mode === 'battle') {
      if (game.battle?.phase === 'menu') {
        if (key === '1' || key === 'z' || key === ' ' || key === 'enter') attack('spark');
        else if (key === '2' || key === 'x') attack('tail');
        else if (key === '3') attack('snack');
        else if (key === '4') attack('orb');
      } else if (key === ' ' || key === 'enter' || key === 'z') {
        battleContinue();
      }
      return;
    }

    if (key === 'b') {
      if (!game.bikeStolen) stealRivalBike();
      else {
        game.ridingBike = !game.ridingBike;
        showToast(game.ridingBike ? `Riding ${game.heroRival}'s stolen bike!` : 'Walking mode');
        updateUI();
      }
      return;
    }
    if (key === 'g') { openGameCornerSlots(); return; }
    if (key === 'c') { openDaycareAndLabs(); return; }
    if (key === 'm') { challengeKantoGym(); return; }
    if (key === 'v') { openVictoryRoadAndEliteFour(); return; }
    if (key === 'p') { reportForPromotion(); return; }

    const dirs = {
      arrowup: 'up', w: 'up',
      arrowdown: 'down', s: 'down',
      arrowleft: 'left', a: 'left',
      arrowright: 'right', d: 'right'
    };
    if (dirs[key]) move(dirs[key]);
    else if (key === ' ' || key === 'enter' || key === 'z') interact();
  }

  function keyUp(e) {
    game.keys[e.key.toLowerCase()] = false;
  }

  window.addEventListener('keydown', keyDown);
  window.addEventListener('keyup', keyUp);

  document.querySelectorAll('.preset-list').forEach(group => {
    const targetId = group.dataset.target;
    const inputEl = $(targetId);
    group.querySelectorAll('.name-preset-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        group.querySelectorAll('.name-preset-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        inputEl.value = btn.dataset.name;
        game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
        game.rocketRival = sanitizeName(ui.rocketRivalInput.value, 'VIPER');
        game.heroRival = sanitizeName(ui.heroRivalInput.value, 'RED');
        updateUI();
      });
    });
  });

  [ui.playerInput, ui.rocketRivalInput, ui.heroRivalInput].forEach(inp => {
    inp.addEventListener('input', () => {
      game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
      game.rocketRival = sanitizeName(ui.rocketRivalInput.value, 'VIPER');
      game.heroRival = sanitizeName(ui.heroRivalInput.value, 'RED');
      updateUI();
    });
  });

  ui.introForm.addEventListener('submit', confirmIntroNames);
  $('rename-toggle').addEventListener('click', openIntroModal);
  if (ui.bikeToggle) {
    ui.bikeToggle.addEventListener('click', () => {
      if (game.mode === 'intro') confirmIntroNames();
      else if (!game.bikeStolen) stealRivalBike();
      else {
        game.ridingBike = !game.ridingBike;
        showToast(game.ridingBike ? `Riding ${game.heroRival}'s stolen bike!` : 'Walking with stolen bike.');
        updateUI();
      }
    });
  }

  // Dedicated Upgrade & Management Buttons
  if (ui.btnUpgradePlayer) ui.btnUpgradePlayer.addEventListener('click', () => buyTrackUpgrade('player'));
  if (ui.btnUpgradeBase) ui.btnUpgradeBase.addEventListener('click', () => buyTrackUpgrade('base'));
  if (ui.btnUpgradeBiz) ui.btnUpgradeBiz.addEventListener('click', () => buyTrackUpgrade('biz'));
  if (ui.btnExecMgmt) ui.btnExecMgmt.addEventListener('click', () => openExecutiveManagement());

  // D-Pad Movement Controls
  document.querySelectorAll('.dpad-btn[data-dir]').forEach(btn => {
    const dir = btn.dataset.dir;
    btn.addEventListener('pointerdown', e => {
      e.preventDefault();
      if (game.mode === 'intro') confirmIntroNames();
      move(dir);
    });
  });

  // Main Action & Facility Buttons
  $('action-button').addEventListener('click', () => interact());
  $('work-corner-button').addEventListener('click', () => openGameCornerSlots());
  $('work-daycare-button').addEventListener('click', () => openDaycareAndLabs());
  if ($('gym-battle-button')) $('gym-battle-button').addEventListener('click', () => challengeKantoGym());
  if ($('victory-road-button')) $('victory-road-button').addEventListener('click', () => openVictoryRoadAndEliteFour());
  $('rank-up-button').addEventListener('click', () => reportForPromotion());

  // Dedicated Operations Deck Buttons (Everything beyond moving the character is accessible by button!)
  if ($('btn-spin-slots')) $('btn-spin-slots').addEventListener('click', () => startOrStopSlotSpin());
  if ($('btn-rig-slots')) $('btn-rig-slots').addEventListener('click', () => workGameCornerShift());
  if ($('btn-fight-tourney')) $('btn-fight-tourney').addEventListener('click', () => startUndergroundTournamentBout());
  if ($('btn-breed-lab')) $('btn-breed-lab').addEventListener('click', () => breedEggInUndergroundLab());
  if ($('btn-fusion-lab')) $('btn-fusion-lab').addEventListener('click', () => splicePartnerInFusionLab());
  if ($('btn-battle-rivals')) {
    $('btn-battle-rivals').addEventListener('click', () => {
      beginRivalBattle(game.defeatedRocketRival ? 'hero' : 'rocket');
    });
  }
  if ($('btn-catch-wild')) {
    $('btn-catch-wild').addEventListener('click', () => {
      if (game.mode === 'battle' && !game.battle?.trainer && game.battle?.phase === 'menu') {
        attack('orb');
      } else {
        beginWildBattle();
      }
    });
  }
  if ($('btn-return-map')) {
    $('btn-return-map').addEventListener('click', () => {
      if (game.mode === 'intro') confirmIntroNames();
      game.mode = 'map';
      game.battle = null;
      game.message = `Returned to Overworld Map (${currentAreaName()}).`;
      updateUI();
    });
  }

  canvas.addEventListener('pointerdown', e => {
    const r = canvas.getBoundingClientRect();
    const x = ((e.clientX - r.left) * W) / r.width;
    const y = ((e.clientY - r.top) * H) / r.height;
    const slot = clamp(Math.floor(x / 96), 0, 3);

    if (game.mode === 'slots') {
      if (y >= 190) {
        if (slot === 0) startOrStopSlotSpin();
        else if (slot === 1) workGameCornerShift();
        else if (slot === 2) startUndergroundTournamentBout();
        else { game.mode = 'map'; updateUI(); }
      } else {
        startOrStopSlotSpin();
      }
      return;
    }
    if (game.mode === 'daycare') {
      if (y >= 190) {
        if (slot === 0) workDaycareShift();
        else if (slot === 1) breedEggInUndergroundLab();
        else if (slot === 2) splicePartnerInFusionLab();
        else { game.mode = 'map'; updateUI(); }
      } else if (x < W / 2) {
        breedEggInUndergroundLab();
      } else {
        splicePartnerInFusionLab();
      }
      return;
    }
    if (game.mode === 'victory') {
      if (y >= 190) {
        if (slot === 0 || slot === 1) startEliteFourBout();
        else if (slot === 2) openExecutiveManagement();
        else { game.mode = 'map'; updateUI(); }
      } else {
        startEliteFourBout();
      }
      return;
    }
    if (game.mode === 'management') {
      if (y >= 190) {
        runExecutiveManagementAction(slot);
      } else {
        runExecutiveManagementAction(clamp(Math.floor(x / 128), 0, 2));
      }
      return;
    }
    if (game.mode === 'battle') {
      if (game.battle?.phase === 'menu' && y > 192) {
        attack(['spark', 'tail', 'snack', 'orb'][slot]);
      } else if (game.battle?.phase !== 'menu') {
        battleContinue();
      } else {
        attack('spark');
      }
    } else if (game.mode === 'map' && nearbyInteraction()) {
      interact();
    }
  });

  $('sound-toggle').addEventListener('click', e => {
    game.sound = !game.sound;
    e.currentTarget.querySelector('span').textContent = game.sound ? 'Sound on' : 'Sound off';
    showToast(game.sound ? 'Sound is on' : 'Sound is off');
  });

  function loop(now) {
    const dt = Math.min(40, now - game.lastTime);
    game.lastTime = now;
    game.anim = now;

    if (game.mode === 'slots' && game.slots.spinning) {
      for (let i = 0; i < 3; i++) {
        if (!game.slots.locked[i] && now >= game.slots.stopTimes[i]) {
          lockReel(i);
        }
      }
    }

    if (game.mode === 'map') {
      game.moveClock += dt;
      if (game.grassEncounterCooldown > 0) game.grassEncounterCooldown -= dt / 1000;
      const stepInterval = game.ridingBike ? Math.max(75, 105 - game.playerUpgradeIdx * 7) : 150;
      if (game.moveClock > stepInterval) {
        let dir = null;
        if (game.keys.arrowup || game.keys.w) dir = 'up';
        else if (game.keys.arrowdown || game.keys.s) dir = 'down';
        else if (game.keys.arrowleft || game.keys.a) dir = 'left';
        else if (game.keys.arrowright || game.keys.d) dir = 'right';
        if (dir) {
          move(dir);
          game.moveClock = 0;
        }
      }
    }
    render();
    requestAnimationFrame(loop);
  }

  updateUI();
  requestAnimationFrame(loop);
})();

