    game.mode = 'management';
    game.mgmtBanner = 'SELECT 1 (ADV. BASE OPS), 2 (ADV. GYM TRIBUTE) OR 3 (ADV. BIZ SYNDICATE)!';
    game.message = `Opened Top-Rank Advanced Base, Gym & Business Management Console!`;
    updateUI();
