(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const W = canvas.width, H = canvas.height, T = 16;
  const $ = id => document.getElementById(id);

  // Pre-generate an authentic 1998 Game Boy Color Bayer-Dither & Film-Grain texture
  const grainCanvas = document.createElement('canvas');
  grainCanvas.width = W;
  grainCanvas.height = H;
  const gctx = grainCanvas.getContext('2d');
  (() => {
    const img = gctx.createImageData(W, H);
    const d = img.data;
    const bayer4 = [
      [0, 8, 2, 10],
      [12, 4, 14, 6],
      [3, 11, 1, 9],
      [15, 7, 13, 5]
    ];
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const i = (y * W + x) * 4;
        const b = bayer4[y & 3][x & 3];
        const hash = ((x * 73856093) ^ (y * 19349663)) & 31;
        const dark = (b < 5 && hash < 14) || (y % 2 === 0 && x % 3 === 0);
        if (dark) {
          d[i] = 16;
          d[i + 1] = 20;
          d[i + 2] = 28;
          d[i + 3] = 26;
        } else {
          d[i] = 248;
          d[i + 1] = 242;
          d[i + 2] = 215;
          d[i + 3] = 12;
        }
      }
    }
    gctx.putImageData(img, 0, 0);
  })();

