    message: 'Complete Team Rocket Initiation in the Rundown Base and steal the Rival Protagonist’s Bike!',
    talkedVex: false,
    defeatedRocketRival: false,
    defeatedHeroRival: false,
    battle: null,
    slots: {
      spinning: false,
      rigged: false,
      reels: [0, 1, 2],
      stopTimes: [0, 0, 0],
      locked: [true, true, true],
      lastWin: 0,
      spins: 0,
      banner: '1: SPIN (₽10)  •  2: WORK/RIG  •  3: UNDERGROUND FIGHT TOURNEY'
    },
    sound: true,
    keys: {},
    lastTime: 0,
    anim: 0,
    grassEncounterCooldown: 0
  };

  function currentRocketBallType() {
    if (game.rankIndex >= 4 || game.playerUpgradeIdx >= 4) return ROCKET_BALL_TYPES[2];
    if (game.rankIndex >= 2 || game.playerUpgradeIdx >= 2) return ROCKET_BALL_TYPES[1];
    return ROCKET_BALL_TYPES[0];
  }

  const mapW = 32, mapH = 26;
  const path = new Set();
  const addPath = (x1, y1, x2, y2) => {
    let x = x1, y = y1;
    path.add(`${x},${y}`);
    while (x !== x2) { x += Math.sign(x2 - x); path.add(`${x},${y}`); }
    while (y !== y2) { y += Math.sign(y2 - y); path.add(`${x},${y}`); }
  };

  addPath(7, 9, 7, 16);
  addPath(5, 16, 12, 16);
  addPath(12, 19, 12, 8);
  addPath(12, 8, 26, 8);
  addPath(26, 8, 26, 5);
  addPath(12, 12, 25, 12);
  addPath(12, 19, 19, 19);

  const baseBounds = { x1: 2, y1: 2, x2: 11, y2: 9, doorX: 7, doorY: 9 };
  const bikeSpot = { x: 7, y: 10 };
  const victoryGate = { x: 26, y: 5 };
  const grassAreas = [
    { x: 21, y: 9, w: 8, h: 4 },
    { x: 23, y: 14, w: 6, h: 6 },
    { x: 4, y: 19, w: 7, h: 4 }
  ];
  const ponds = [{ x: 28, y: 2, w: 3, h: 3 }];
  const solids = new Set();

  for (let x = 0; x < mapW; x++) { solids.add(`${x},0`); solids.add(`${x},${mapH - 1}`); }
  for (let y = 0; y < mapH; y++) { solids.add(`0,${y}`); solids.add(`${mapW - 1},${y}`); }

  for (let x = baseBounds.x1; x <= baseBounds.x2; x++) {
    solids.add(`${x},${baseBounds.y1}`);
    if (x !== baseBounds.doorX) solids.add(`${x},${baseBounds.y2}`);
  }
  for (let y = baseBounds.y1; y <= baseBounds.y2; y++) {
    solids.add(`${baseBounds.x1},${y}`);
    solids.add(`${baseBounds.x2},${y}`);
  }
  [[3, 3], [4, 3], [10, 3], [3, 8]].forEach(([cx, cy]) => solids.add(`${cx},${cy}`));

  const buildings = [
    { x: 14, y: 4, w: 6, h: 4, type: 'corner', label: 'GAME CORNER' },
    { x: 3, y: 12, w: 5, h: 4, type: 'daycare', label: 'DAYCARE & LAB' },
    { x: 16, y: 15, w: 6, h: 4, type: 'gym', label: 'KANTO GYM' }
  ];
  buildings.forEach(b => {
    for (let y = b.y; y < b.y + b.h; y++)
      for (let x = b.x; x < b.x + b.w; x++)
        solids.add(`${x},${y}`);
  });

  const trees = [
    [22, 3], [23, 3], [29, 6], [29, 7], [30, 7],
    [28, 21], [29, 21], [30, 21], [12, 23], [13, 23], [14, 23], [15, 23],
    [16, 23], [17, 23], [18, 23], [19, 23], [20, 23], [21, 23], [22, 23],
    [23, 23], [24, 23], [25, 23], [26, 23], [27, 23], [28, 23], [29, 23]
  ];
  trees.forEach(([x, y]) => solids.add(`${x},${y}`));

  const npcs = {
    vex: { x: 7, y: 4, role: 'vex' },
    rocketRival: { x: 9, y: 6, role: 'rocketRival' },
    heroRival: { x: 8, y: 10, role: 'heroRival' },
    cornerBoss: { x: 16, y: 8, role: 'cornerBoss' },
    daycareKeeper: { x: 5, y: 16, role: 'daycareKeeper' },
    gymLeader: { x: 19, y: 19, role: 'gymLeader' },
    victoryGuard: { x: 26, y: 5, role: 'victoryGuard' }
  };

  function inRundownBase(x, y) {
    return x >= baseBounds.x1 && x <= baseBounds.x2 && y >= baseBounds.y1 && y <= baseBounds.y2;
  }

  function currentAreaName() {
    if (game.mode === 'slots') return 'CORNER SLOTS & FIGHT PIT';
    if (game.mode === 'daycare') return 'DAYCARE BREEDING & FUSION LAB';
    if (game.mode === 'victory') return 'VICTORY ROAD & ELITE 4';
    if (game.mode === 'management') return 'EXECUTIVE SYNDICATE HQ';
    if (inRundownBase(game.x, game.y)) return BASE_UPGRADES[game.baseUpgradeIdx].label;
    if (Math.abs(game.x - npcs.cornerBoss.x) + Math.abs(game.y - npcs.cornerBoss.y) <= 3) return 'GAME CORNER PLAZA';
    if (Math.abs(game.x - npcs.daycareKeeper.x) + Math.abs(game.y - npcs.daycareKeeper.y) <= 3) return 'DAYCARE & SECRET LAB';
    if (Math.abs(game.x - npcs.gymLeader.x) + Math.abs(game.y - npcs.gymLeader.y) <= 3) {
      return game.gymsControlled > 0 ? `ROCKET GYM (${game.gymsControlled}/4)` : 'KANTO GYM PLAZA';
    }
    if (Math.abs(game.x - victoryGate.x) + Math.abs(game.y - victoryGate.y) <= 3) return 'VICTORY ROAD GATE';
    return 'OUTSIDE ROCKET BASE';
  }

  function tileType(x, y) {
    if (x < 0 || y < 0 || x >= mapW || y >= mapH) return 'wall';
    if (inRundownBase(x, y)) return 'baseFloor';
    if (ponds.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'water';
    if (path.has(`${x},${y}`)) return 'path';
    if (grassAreas.some(p => x >= p.x && x < p.x + p.w && y >= p.y && y < p.y + p.h)) return 'tall';
    return 'grass';
  }

  function npcAt(x, y) {
    return Object.values(npcs).find(n => n.x === x && n.y === y) || null;
  }

  function solid(x, y) {
    return solids.has(`${x},${y}`) || tileType(x, y) === 'water' || Boolean(npcAt(x, y));
  }

  function rect(x, y, w, h, color) {
    ctx.fillStyle = color;
    ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
  }

  // Outlined pixel text for authentic 8-bit Game Boy Color readability
  function pixelText(text, x, y, size = 8, color = '#fff', align = 'left') {
    ctx.font = `bold ${size}px monospace`;
    ctx.textAlign = align;
    ctx.textBaseline = 'top';
    const rx = Math.round(x), ry = Math.round(y);
    if (color !== '#181820' && color !== '#17263a' && color !== '#28394a') {
      ctx.fillStyle = '#14161f';
      ctx.fillText(text, rx + 1, ry + 1);
    }
    ctx.fillStyle = color;
    ctx.fillText(text, rx, ry);
  }

  // Classic 1998 Game Boy double-bordered dialog & HUD box with corner rivets
  function pokeBox(x, y, w, h, fill = '#f8f4e0', borderOuter = '#181820', borderInner = '#586068') {
    rect(x, y, w, h, borderOuter);
    rect(x + 1, y + 1, w - 2, h - 2, fill);
    rect(x + 2, y + 2, w - 4, h - 4, borderInner);
    rect(x + 3, y + 3, w - 6, h - 6, fill);
    // Corner rivets like Pokémon Yellow
    rect(x + 2, y + 2, 2, 2, borderOuter);
    rect(x + w - 4, y + 2, 2, 2, borderOuter);
    rect(x + 2, y + h - 4, 2, 2, borderOuter);
    rect(x + w - 4, y + h - 4, 2, 2, borderOuter);
  }

  function rounded(x, y, w, h, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
  }

  // Draw the Unique Team Rocket Stealing Poké Ball (R-Snatch / Dark Clone / Master-R Ball)
  function drawRocketBall(px, py, scale = 1) {
    const ball = currentRocketBallType();
    ctx.save();
    ctx.translate(Math.round(px), Math.round(py));
    ctx.scale(scale, scale);
    // 1px dark outline circle
    rect(-5, -6, 10, 12, '#181820');
    rect(-6, -5, 12, 10, '#181820');
    // Upper Rocket dark hemisphere
    rect(-5, -5, 10, 5, ball.color);
    // Lower light/metallic hemisphere
    rect(-5, 1, 10, 4, '#d8d4c8');
    // Center clasp belt
    rect(-5, 0, 10, 1, '#181820');
    rect(-2, -1, 4, 3, '#181820');
    rect(-1, 0, 2, 1, ball.trim);
    // Crimson/Gold 'R' insignia on top shell
    rect(-2, -4, 4, 3, ball.trim);
    rect(-4, -4, 1, 1, '#ffffff');
    ctx.restore();
  }

  function stealRivalBike() {
    if (game.bikeStolen && game.starter) return game.starter;
    const chosenStarter = rollRedStarter();
    game.starter = chosenStarter;
    game.bikeStolen = true;
    game.ridingBike = true;
    game.heistDone = 1;
    game.x = bikeSpot.x;
    game.y = bikeSpot.y;
    game.facing = 'down';
    game.buddyTrail = [{ x: bikeSpot.x, y: bikeSpot.y - 1 }];
    game.message = `Left Team Rocket Initiation, met ${game.heroRival}, and stole his Bike! Its 1 Poké Ball contained ${chosenStarter.name} (1/3 Red Starter)!`;
    showToast(`🚲 Stole ${game.heroRival}'s Bike! 1 Poké Ball had ${chosenStarter.name}!`);
    updateUI();
    return chosenStarter;
  }

  function ensureBikeStolen() {
    if (!game.bikeStolen || !game.starter) {
      stealRivalBike();
    }
  }

  // Detailed, grainy 1998 Game Boy Color tile art with dithered textures
  function drawTerrain(tx, ty, sx, sy) {
    const type = tileType(tx, ty);
    const seed = (tx * 92821 + ty * 68917) % 97;
    if (type === 'baseFloor') {
      const isWall =
        (ty === baseBounds.y1 || (ty === baseBounds.y2 && tx !== baseBounds.doorX) || tx === baseBounds.x1 || tx === baseBounds.x2);
      if (isWall) {
        rect(sx, sy, T, T, '#181820');
        rect(sx + 1, sy + 1, T - 2, T - 2, game.baseUpgradeIdx >= 2 ? '#242c40' : '#303440');
        rect(sx + 1, sy + 1, T - 2, 3, game.baseUpgradeIdx >= 3 ? '#f0c038' : '#505868');
        // Brick mortar lines & dither
        rect(sx + 1, sy + 8, T - 2, 1, '#181820');
        rect(sx + 7, sy + 4, 1, 4, '#181820');
        rect(sx + 12, sy + 9, 1, 5, '#181820');
        if (game.baseUpgradeIdx === 0) {
          rect(sx + 3, sy + 6, 4, 2, '#784038');
          rect(sx + 4, sy + 7, 2, 2, '#582c28');
        }
      } else {
        const floorA = game.baseUpgradeIdx >= 2 ? '#283040' : '#383c48';
        const floorB = game.baseUpgradeIdx >= 2 ? '#222838' : '#303440';
        rect(sx, sy, T, T, (tx + ty) % 2 === 0 ? floorA : floorB);
        // Tile grid border & dithered grit speckles
        rect(sx, sy, T, 1, '#222630');
        rect(sx, sy, 1, T, '#222630');
        for (let py = 2; py < T; py += 4) {
          for (let px = 2; px < T; px += 4) {
            if ((px + py + seed) % 3 === 0) rect(sx + px, sy + py, 1, 1, '#20242c');
          }
        }
        if (game.baseUpgradeIdx >= 3 && tx === 7 && ty >= 4 && ty <= 9) {
          rect(sx + 2, sy, T - 4, T, '#781c24');
          rect(sx + 3, sy, T - 6, T, '#b82c34');
          rect(sx + 2, sy, 1, T, '#f0c038');
          rect(sx + T - 3, sy, 1, T, '#f0c038');
        }
        if (game.baseUpgradeIdx === 0 && seed % 4 === 0) {
          rect(sx + 3, sy + 4, 6, 1, '#181c24');
          rect(sx + 8, sy + 5, 1, 5, '#181c24');
          rect(sx + 6, sy + 6, 3, 1, '#181c24');
        }
      }
    } else if (type === 'grass') {
      // Classic GBC palette grass with 2x2 dither & blade V-tufts
      rect(sx, sy, T, T, '#78c078');
      for (let py = 0; py < T; py += 4) {
        for (let px = (py % 8 === 0 ? 0 : 2); px < T; px += 4) {
          rect(sx + px, sy + py, 1, 1, '#60a860');
        }
      }
      if (seed % 3 === 0) {
        // Classic Game Boy V-shaped grass blade detail
        rect(sx + 3, sy + 5, 1, 2, '#285830');
        rect(sx + 5, sy + 5, 1, 2, '#285830');
        rect(sx + 4, sy + 6, 1, 2, '#285830');
        rect(sx + 10, sy + 11, 1, 2, '#285830');
        rect(sx + 12, sy + 11, 1, 2, '#285830');
        rect(sx + 11, sy + 12, 1, 2, '#285830');
      }
    } else if (type === 'path') {
      // Grainy cobbled dirt path like Pallet/Viridian Route
      rect(sx, sy, T, T, '#d8c088');
      for (let py = 1; py < T; py += 3) {
        for (let px = 1; px < T; px += 4) {
          const c = (px + py + seed) % 3 === 0 ? '#b89860' : '#ead8a8';
          rect(sx + px, sy + py, 1, 1, c);
        }
      }
      if (seed % 3 === 0) {
        rect(sx + 4, sy + 5, 3, 2, '#a88850');
        rect(sx + 10, sy + 11, 2, 2, '#907040');
      }
    } else if (type === 'tall') {
      // Dense outlined GBC tall grass tufts
      rect(sx, sy, T, T, '#58a058');
      const sway = Math.round(Math.sin(game.anim * 0.003 + tx * 2 + ty));
      for (let row = 0; row < 2; row++) {
        const by = sy + 2 + row * 7;
        for (let col = 0; col < 3; col++) {
          const bx = sx + 2 + col * 5 + (row === 0 ? sway : 0);
          rect(bx, by + 2, 4, 5, '#183820');
          rect(bx + 1, by, 2, 6, '#388848');
          rect(bx + 1, by, 1, 2, '#98e088');
        }
      }
    } else if (type === 'water') {
      rect(sx, sy, T, T, '#4890d8');
      rect(sx, sy, 16, 2, '#88c8f8');
      const wave = Math.round(Math.sin(game.anim * 0.003 + tx) * 1.5);
      rect(sx + 2 + wave, sy + 6, 5, 1, '#d8f0ff');
      rect(sx + 9 - wave, sy + 11, 4, 1, '#2860a0');
    } else {
      rect(sx, sy, T, T, '#78c078');
    }
  }

  function drawRundownBaseDetails(camX, camY) {
    const rx = 6 * T - camX + 6;
    const ry = 5 * T - camY + 2;
    const logoColor = game.baseUpgradeIdx >= 2 ? '#e83838' : '#a83030';
    rect(rx - 1, ry - 1, 22, 24, '#181820');
    rect(rx, ry, 20, 22, game.baseUpgradeIdx >= 2 ? '#1c2436' : '#282c38');
    rect(rx + 3, ry + 2, 4, 18, logoColor);
    rect(rx + 7, ry + 2, 8, 4, logoColor);
    rect(rx + 12, ry + 5, 4, 5, logoColor);
    rect(rx + 7, ry + 9, 7, 4, logoColor);
    rect(rx + 10, ry + 13, 6, 7, logoColor);
    if (game.baseUpgradeIdx === 0) {
      rect(rx + 2, ry + 8, 14, 1, '#383c48');
      rect(rx + 2, ry + 15, 11, 1, '#303440');
    }

    [[3, 3], [4, 3], [10, 3], [3, 8]].forEach(([cx, cy], idx) => {
      const sx = cx * T - camX, sy = cy * T - camY;
      rect(sx, sy + 1, 16, 15, '#181820');
      if (idx === 1 && game.baseUpgradeIdx >= 1) {
        rect(sx + 1, sy + 2, 14, 13, '#204838');
        rect(sx + 3, sy + 4, 10, 9, '#58e0b0');
        pixelText('+', sx + 8, sy + 4, 8, '#181820', 'center');
      } else if (idx === 2 && game.baseUpgradeIdx >= 2) {
        rect(sx + 1, sy + 2, 14, 13, '#1e3554');
        rect(sx + 3, sy + 4, 10, 9, '#4dabf7');
      } else {
        rect(sx + 1, sy + 2, 14, 13, '#785038');
        rect(sx + 2, sy + 3, 12, 3, '#986848');
        rect(sx + 1, sy + 8, 14, 1, '#181820');
        rect(sx + 4, sy + 9, 8, 2, '#262b34');
      }
    });

    const bx = 7 * T - camX - 50;
    const by = 2 * T - camY - 5;
    pokeBox(bx, by, 116, 14, '#201824', '#181820', '#a83838');
    pixelText(BASE_UPGRADES[game.baseUpgradeIdx].label, bx + 58, by + 3, 6, '#f8d048', 'center');
  }

  function drawVictoryRoadGate(camX, camY) {
    const gx = victoryGate.x * T - camX - 20;
    const gy = (victoryGate.y - 2) * T - camY;
    const unlocked = game.rankIndex >= 4;
    rect(gx - 1, gy - 1, 58, 28, '#181820');
    rect(gx, gy, 56, 26, unlocked ? '#3b2e14' : '#2a2e38');
    rect(gx + 4, gy + 4, 48, 18, unlocked ? '#f6cb49' : '#586273');
    rect(gx + 16, gy + 8, 24, 14, unlocked ? '#1c2b22' : '#231820');
    pokeBox(gx - 14, gy - 13, 84, 13, '#18202c', '#181820', unlocked ? '#f6cb49' : '#804040');
    pixelText(
      unlocked ? '🏆 VICTORY RD: OPEN' : '🔒 VICTORY RD (EXEC)',
      gx + 28,
      gy - 10,
      6,
      unlocked ? '#8ef0c0' : '#ff857d',
      'center'
    );
  }

  function drawParkedBikeWithPokeball(px, py) {
    const x = Math.round(px), y = Math.round(py);
    rect(x - 8, y + 6, 16, 3, 'rgba(0,0,0,0.35)');
    rect(x - 8, y, 7, 7, '#181820');
    rect(x - 7, y + 1, 5, 5, '#d8e0e8');
    rect(x - 6, y + 2, 3, 3, '#384048');
    rect(x + 1, y, 7, 7, '#181820');
    rect(x + 2, y + 1, 5, 5, '#d8e0e8');
    rect(x + 3, y + 2, 3, 3, '#384048');
    rect(x - 5, y - 1, 10, 2, '#e03838');
    rect(x - 2, y - 4, 3, 4, '#e03838');
    rect(x + 2, y - 6, 2, 6, '#e03838');
    // 1 Red/White Poké Ball in the basket
    rect(x + 3, y - 6, 6, 6, '#181820');
    rect(x + 4, y - 5, 4, 2, '#e03838');
    rect(x + 4, y - 2, 4, 2, '#ffffff');
    pokeBox(x - 30, y - 20, 60, 12, '#301820', '#181820', '#e04848');
    pixelText('🚲 BIKE + 1 BALL', x, y - 17, 6, '#fff', 'center');
  }

  // Detailed, outlined 1998 Game Boy Color Starter sprites
  function drawRedStarter(px, py, scale = 1, starterObj = null) {
