    if (game.fusionTier > 0) {
      ctx.fillStyle = game.fusionTier % 2 === 1 ? 'rgba(142,240,192,0.38)' : 'rgba(246,203,73,0.42)';
      ctx.beginPath();
      ctx.arc(0, -3, 12 + Math.min(8, game.fusionTier), 0, Math.PI * 2);
      ctx.fill();
    }

    rect(-8, 8, 16, 3, 'rgba(0,0,0,0.35)');

    if (base.includes('BULBASAUR')) {
      // 1px dark outline
      rect(-7, -14, 14, 10, '#181820');
      rect(-9, -8, 18, 16, '#181820');
