      rect(-7, -13, 13, 10, '#68b0e0');
      rect(-6, -3, 11, 9, '#f0e0a8');
      rect(-4, -1, 7, 1, '#c8a868');
      rect(-6, 5, 4, 4, '#5098c8');
      rect(2, 5, 4, 4, '#5098c8');
      rect(-5, -10, 3, 4, '#ffffff');
      rect(1, -10, 3, 4, '#ffffff');
      rect(-4, -9, 2, 3, '#181820');
      rect(2, -9, 2, 3, '#181820');
