      // CHARMANDER with outlined body & multi-tone tail flame
      rect(6, -1, 6, 5, '#181820');
      rect(9, -7, 7, 8, '#181820');
      rect(-7, -14, 14, 22, '#181820');
      rect(7, 0, 4, 3, '#f08030');
      rect(10, -6, 5, 6, game.fusionTier > 0 ? '#7950f2' : '#e03828');
      rect(11, -8, 3, 4, '#f8d038');
      rect(-6, -13, 12, 16, '#f08030');
      rect(-4, -3, 8, 8, '#f8e098');
      rect(-5, -10, 3, 4, '#ffffff');
      rect(1, -10, 3, 4, '#ffffff');
      rect(-4, -9, 2, 3, '#181820');
      rect(2, -9, 2, 3, '#181820');
      rect(-5, 4, 4, 5, '#c85820');
      rect(2, 4, 4, 5, '#c85820');
    }
    if (game.fusionTier > 0) {
      rect(-4, -18, 8, 3, '#181820');
      rect(-3, -17, 6, 2, '#f6cb49');
    }
    ctx.restore();
  }

  function drawTree(sx, sy) {
    // Classic 16x16 Game Boy Color Viridian Forest tree with dark outline & dithered canopy
    rect(sx + 4, sy + 10, 8, 6, '#181820');
    rect(sx + 5, sy + 10, 6, 5, '#805030');
