  function render() {
    ctx.clearRect(0, 0, W, H);
    if (game.mode === 'intro') drawIntroScene();
    else if (game.mode === 'map') drawMap();
    else if (game.mode === 'battle') drawBattle();
    else if (game.mode === 'slots') drawSlotsMiniGame();
    else if (game.mode === 'daycare') drawDaycareLab();
    else if (game.mode === 'victory') drawVictoryRoadScreen();
    else if (game.mode === 'management') drawExecutiveManagementScreen();
    // Apply authentic 1998 Game Boy Color dither/grain pass over the entire frame
    ctx.drawImage(grainCanvas, 0, 0);
  }

  function totalAttackBonus() {
    return PLAYER_UPGRADES[game.playerUpgradeIdx].atkBonus + game.spliceAtkBonus + game.gymsControlled * 3 + game.stolenCount * 4;
  }

  function showToast(text) {
    ui.toast.textContent = text;
    ui.toast.classList.add('show');
    clearTimeout(game.toastTimer);
    game.toastTimer = setTimeout(() => ui.toast.classList.remove('show'), 2600);
  }

  function addMerits(amount, reason) {
    game.merits += amount;
    let promoted = false;
    while (game.rankIndex < RANKS.length - 1 && game.merits >= RANKS[game.rankIndex].nextMerits) {
      game.rankIndex++;
      game.playerUpgradeIdx = Math.max(game.playerUpgradeIdx, game.rankIndex);
      game.baseUpgradeIdx = Math.max(game.baseUpgradeIdx, game.rankIndex);
      game.bizUpgradeIdx = Math.max(game.bizUpgradeIdx, game.rankIndex);
      game.maxHp += 6;
      game.hp = game.maxHp;
      game.orbs += 1;
      promoted = true;
    }
    if (promoted) {
      const newRank = RANKS[game.rankIndex].title;
      const topUnlock = game.rankIndex >= 4 ? ' Victory Road & Advanced Management UNLOCKED!' : '';
      showToast(`★ PROMOTED TO ${newRank}!${topUnlock}`);
    } else if (reason) {
      showToast(`${reason} (+${amount} Merits)`);
    }
    updateUI();
  }

  function buyTrackUpgrade(track) {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    if (track === 'player' && game.playerUpgradeIdx < PLAYER_UPGRADES.length - 1) {
      const cost = PLAYER_UPGRADES[game.playerUpgradeIdx].cost;
      if (game.funds >= cost) game.funds -= cost;
      game.playerUpgradeIdx++;
      game.maxHp += 6;
      game.hp = game.maxHp;
      game.orbs += 1;
      game.message = `Unlocked Player Upgrade: ${PLAYER_UPGRADES[game.playerUpgradeIdx].name} (+1 ${currentRocketBallType().name})!`;
      addMerits(20, `Unlocked ${PLAYER_UPGRADES[game.playerUpgradeIdx].name}`);
    } else if (track === 'base' && game.baseUpgradeIdx < BASE_UPGRADES.length - 1) {
      const cost = BASE_UPGRADES[game.baseUpgradeIdx].cost;
      if (game.funds >= cost) game.funds -= cost;
      game.baseUpgradeIdx++;
      game.orbs += 2;
      game.message = `Unlocked Base Upgrade: ${BASE_UPGRADES[game.baseUpgradeIdx].name} (+2 ${currentRocketBallType().name}s)!`;
      addMerits(20, `Unlocked ${BASE_UPGRADES[game.baseUpgradeIdx].name}`);
    } else if (track === 'biz' && game.bizUpgradeIdx < BIZ_UPGRADES.length - 1) {
      const cost = BIZ_UPGRADES[game.bizUpgradeIdx].cost;
      if (game.funds >= cost) game.funds -= cost;
      game.bizUpgradeIdx++;
      game.message = `Unlocked Business Upgrade: ${BIZ_UPGRADES[game.bizUpgradeIdx].name}!`;
      addMerits(20, `Unlocked ${BIZ_UPGRADES[game.bizUpgradeIdx].name}`);
    }
    updateUI();
  }

  // Infinite Splicing with Exponential (2^n) Returns!
  function splicePartnerInFusionLab() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    game.mode = 'daycare';
    game.fusionTier++;
    const expMult = Math.pow(2, game.fusionTier - 1);
    const atkGain = Math.round(10 * expMult);
    const hpGain = Math.round(15 * expMult);
    const fundGain = Math.round(80 * expMult);
    const meritGain = Math.round(30 * Math.pow(1.4, game.fusionTier - 1));

    game.spliceAtkBonus += atkGain;
    game.spliceHpBonus += hpGain;
    game.maxHp += hpGain;
    game.hp = game.maxHp;
    game.funds += fundGain;
    game.level += 1;
    game.starter.name = `${game.starter.baseName}-MK.${game.fusionTier}`;

    game.message = `Underground Fusion Lab spliced ${game.starter.name} (Exponential ×${expMult} Return: +${atkGain} ATK, +${hpGain} HP, +₽${fundGain})!`;
    addMerits(meritGain, `Spliced ${game.starter.name} (+${atkGain} ATK, +${hpGain} HP)`);
  }

  function breedEggInUndergroundLab() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    game.mode = 'daycare';
    game.eggsBred++;
    game.caught++;
    game.maxHp += 8;
    game.hp = game.maxHp;
    game.funds += 140;
    game.message = `Underground Breeding Lab hatched High-IV Rocket Egg #${game.eggsBred}! (+1 Party Pokémon, +8 Max HP, +₽140)`;
    addMerits(30, `Bred High-IV Specimen #${game.eggsBred}`);
  }

