    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const unlockedMaxTier = Math.min(TOURNAMENT_TIERS.length, game.rankIndex + 1);
    const targetIdx = Math.min(unlockedMaxTier - 1, game.tourneyCleared);
    const t = TOURNAMENT_TIERS[targetIdx];

    const enemy = {
      name: t.mon,
      kind: `PIT TIER ${t.tier}`,
