      trainer: `${t.title} • ${t.trainer}`,
      rivalKind: 'tournament',
      tourneyTier: t.tier,
      prize: t.prize,
      merits: t.merits,
      arenaBg: '#2b1620',
      floorBg: '#3d1e2d',
      enemy,
      phase: 'menu',
      message: `Underground Fight Tournament ${t.title}: ${t.trainer} sent out ${t.mon}!`,
      turn: 0
    };
    game.message = game.battle.message;
    updateUI();
