    game.mode = 'management';
    game.message = `Executive ${game.playerName} opened Advanced Base, Gym & Business Management!`;
    updateUI();
  }

  function runExecutiveManagementAction(slot) {
    game.execOpsCount++;
    if (slot === 0) {
      game.baseUpgradeIdx = BASE_UPGRADES.length - 1;
      game.funds += 350;
      game.orbs += 2;
      game.message = `Advanced Base Management: Deployed Fortress Patrols (+₽350, +2 ${currentRocketBallType().name}s, Max Base HQ)!`;
      showToast('Advanced Base Ops: +₽350 & +2 R-Balls!');
    } else if (slot === 1) {
      const gymTribute = 200 + game.gymsControlled * 150;
      game.funds += gymTribute;
      game.level += 1;
      game.message = `Advanced Gym Management: Collected +₽${gymTribute} protection tribute from ${game.gymsControlled}/4 controlled Gyms & +1 Lv!`;
      showToast(`Advanced Gym Management: +₽${gymTribute} & Lv.${game.level}!`);
    } else if (slot === 2) {
      game.bizUpgradeIdx = BIZ_UPGRADES.length - 1;
      game.funds += 450;
      game.spliceAtkBonus += 12;
      game.message = `Advanced Business Management: Automated Casino & Fusion Syndicate (+₽450 & +12 ATK)!`;
      showToast('Advanced Business Syndicate: +₽450 & +12 ATK!');
    } else {
      game.mode = 'map';
      game.message = `Closed Executive Management Desk with ₽${game.funds}.`;
    }
    updateUI();
  }

  function updateUI() {
    const rankObj = RANKS[game.rankIndex];
    const pUpg = PLAYER_UPGRADES[game.playerUpgradeIdx];
    const bUpg = BASE_UPGRADES[game.baseUpgradeIdx];
    const zUpg = BIZ_UPGRADES[game.bizUpgradeIdx];
    const unlockedTiers = Math.min(5, game.rankIndex + 1);
    const rBall = currentRocketBallType();

    ui.level.textContent = game.level;
    ui.hpBar.style.width = `${clamp((100 * game.hp) / game.maxHp, 0, 100)}%`;
    ui.hpText.textContent = `${game.hp} / ${game.maxHp}`;
    ui.buddyCount.textContent = `${game.gymsControlled} / 4`;
    ui.wins.textContent = String(game.heistDone + game.wins + game.cornerShifts + game.daycareShifts + game.eggsBred + game.fusionTier + game.stolenCount).padStart(2, '0');
    ui.area.textContent = currentAreaName();
    ui.status.textContent = game.message;

    ui.playerNameDisplay.textContent = `GRUNT ${game.playerName}`;
    ui.rocketRivalDisplay.textContent = `${game.rocketRival} / ${game.heroRival}`;
    ui.heroRivalDisplay.textContent = `${game.gymsControlled}/4 GYMS • ${game.rankIndex >= 4 ? 'E4 OPEN' : 'PIT T' + unlockedTiers}`;

    if (ui.starterName && game.starter) {
      ui.starterName.textContent = `${game.starter.name} (${game.starter.number})`;
    }
    if (ui.starterOrigin && game.starter) {
      const spliceText = game.fusionTier > 0 ? ` • SPLICE MK.${game.fusionTier} (+${game.spliceAtkBonus} ATK)` : ` • ${game.starter.kind}`;
      ui.starterOrigin.innerHTML = `<i></i>STOLEN BIKE POKÉ BALL${spliceText}`;
    }
    if (ui.partnerBadgeIcon && game.starter) {
      ui.partnerBadgeIcon.style.background = game.starter.color;
      ui.partnerBadgeIcon.style.borderColor = game.starter.accent;
    }

    if (ui.bikeToggle) {
      ui.bikeToggle.querySelector('span').textContent = !game.bikeStolen
        ? `🚲 Steal ${game.heroRival}'s Bike`
        : game.ridingBike
          ? '🚲 Bike: Riding'
          : '🚲 Bike: Walking';
    }

    ui.rankDisplay.textContent = rankObj.title;
    ui.rankTierPill.textContent = `RANK ${game.rankIndex + 1} / ${RANKS.length}`;
    if (game.rankIndex < RANKS.length - 1) {
      ui.meritDisplay.textContent = `${game.merits} / ${rankObj.nextMerits} MERITS`;
      const pct = clamp(((game.merits - rankObj.minMerits) / (rankObj.nextMerits - rankObj.minMerits)) * 100, 6, 100);
      ui.rankBar.style.width = `${pct}%`;
    } else {
      ui.meritDisplay.textContent = `${game.merits} MERITS (TOP RANK)`;
      ui.rankBar.style.width = '100%';
    }

    if (ui.upgradeSummaryPill) {
      ui.upgradeSummaryPill.textContent = `P:LV.${pUpg.lvl} • B:LV.${bUpg.lvl} • $:LV.${zUpg.lvl}`;
    }
    if (ui.upgradePlayerName) ui.upgradePlayerName.textContent = pUpg.name;
    if (ui.upgradeBaseName) ui.upgradeBaseName.textContent = bUpg.name;
    if (ui.upgradeBizName) ui.upgradeBizName.textContent = zUpg.name;

    if (ui.btnUpgradePlayer) {
      const max = game.playerUpgradeIdx >= PLAYER_UPGRADES.length - 1;
      ui.btnUpgradePlayer.textContent = max ? 'MAXED' : `UPGRADE (₽${pUpg.cost})`;
      ui.btnUpgradePlayer.classList.toggle('maxed', max);
    }
    if (ui.btnUpgradeBase) {
      const max = game.baseUpgradeIdx >= BASE_UPGRADES.length - 1;
      ui.btnUpgradeBase.textContent = max ? 'MAXED' : `UPGRADE (₽${bUpg.cost})`;
      ui.btnUpgradeBase.classList.toggle('maxed', max);
    }
    if (ui.btnUpgradeBiz) {
      const max = game.bizUpgradeIdx >= BIZ_UPGRADES.length - 1;
      ui.btnUpgradeBiz.textContent = max ? 'MAXED' : `UPGRADE (₽${zUpg.cost})`;
      ui.btnUpgradeBiz.classList.toggle('maxed', max);
    }

    if (ui.execMgmtBar && ui.execMgmtStatus) {
      const isTop = game.rankIndex >= 4;
      ui.execMgmtBar.classList.toggle('unlocked', isTop);
      ui.execMgmtStatus.textContent = isTop
        ? '★ TOP RANK UNLOCKED: ADV. BASE, GYM & BIZ MGMT'
        : '🔒 TOP RANK: ADV. BASE, GYM & BIZ MGMT';
    }

    ui.gruntCallsign.textContent = `GRUNT ${game.playerName} • ${rankObj.title}`;
    ui.jobLedger.textContent = `🚲 ${game.starter.name} • STOLEN: ${game.stolenCount} • GYMS: ${game.gymsControlled}/4 • ₽${game.funds}`;
    ui.fundsReadout.textContent = `FUNDS: ₽${game.funds} • ${rBall.short}: ${game.orbs}`;

    ui.noteTitle.textContent = `${rBall.name} (STOLEN: ${game.stolenCount}) • SPLICE MK.${game.fusionTier}`;
    ui.note.textContent = `Unique Team Rocket ${rBall.name}s steal Trainer & Wild Pokémon! Infinite Splicing doubles returns (2^n).`;

    if (game.eliteFourCleared >= 4 && game.gymsControlled >= 4) {
      ui.goal.textContent = `All 4 Gyms controlled & Elite 4 conquered! Infinite Splicing active!`;
      ui.goalCheck.textContent = '✓';
      ui.progress.style.width = '100%';
    } else if (game.rankIndex >= 4) {
      ui.goal.textContent = `Top Rank reached! Conquer Victory Road Elite 4 (${game.eliteFourCleared}/4) & Gyms (${game.gymsControlled}/4)`;
      ui.goalCheck.textContent = '★';
      ui.progress.style.width = '90%';
    } else {
      ui.goal.textContent = `Steal Pokémon with R-Balls, take over Gyms (${game.gymsControlled}/4) & reach Top Rank`;
      ui.goalCheck.textContent = game.merits > 0 ? '★' : '○';
      ui.progress.style.width = `${clamp(20 + game.merits, 20, 88)}%`;
    }

    if (game.mode === 'intro') ui.action.textContent = 'STEAL BIKE & START';
    else if (game.mode === 'battle') ui.action.textContent = 'ATTACK / CONTINUE';
    else if (game.mode === 'slots') ui.action.textContent = game.slots.spinning ? 'STOP REEL' : 'SPIN SLOTS';
    else if (game.mode === 'daycare') ui.action.textContent = 'FUSE / BREED';
    else if (game.mode === 'victory') ui.action.textContent = 'FIGHT ELITE 4';
    else if (game.mode === 'management') ui.action.textContent = 'COLLECT OPS';
    else ui.action.textContent = 'INTERACT / ACT';
  }

  function sanitizeName(val, fallback) {
    const cleaned = (val || '').trim().toUpperCase().replace(/[^A-Z0-9 _-]/g, '').slice(0, 10);
    return cleaned || fallback;
  }

  function confirmIntroNames(e) {
    if (e) e.preventDefault();
    game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
    game.rocketRival = sanitizeName(ui.rocketRivalInput.value, 'VIPER');
    game.heroRival = sanitizeName(ui.heroRivalInput.value, 'RED');

    ui.playerInput.value = game.playerName;
    ui.rocketRivalInput.value = game.rocketRival;
    ui.heroRivalInput.value = game.heroRival;

    ui.introOverlay.hidden = true;
    if (game.mode === 'intro') {
      game.mode = 'map';
      stealRivalBike();
    } else {
      updateUI();
    }
  }

  function openIntroModal() {
    ui.playerInput.value = game.playerName;
    ui.rocketRivalInput.value = game.rocketRival;
    ui.heroRivalInput.value = game.heroRival;
    ui.introOverlay.hidden = false;
    game.mode = 'intro';
    updateUI();
  }

  function openGameCornerSlots() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    game.x = 16;
    game.y = 9;
    game.facing = 'up';
    game.mode = 'slots';
    game.slots.spinning = false;
    game.slots.locked = [true, true, true];
    game.slots.banner = '1: SPIN (₽10)  •  2: WORK/RIG  •  3: UNDERGROUND FIGHT TOURNAMENT!';
    game.message = `Grunt ${game.playerName} entered the Rocket Game Corner & Underground Fight Pit!`;
    updateUI();
  }

  function openDaycareAndLabs() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    game.x = 5;
    game.y = 17;
    game.facing = 'up';
    game.mode = 'daycare';
    game.message = `Entered the Daycare Center & Secret Underground Breeding / Infinite Fusion Labs!`;
    updateUI();
  }

  function startOrStopSlotSpin() {
    if (game.mode !== 'slots') openGameCornerSlots();
    const s = game.slots;
    if (s.spinning) {
      const nextIdx = s.locked.findIndex(locked => !locked);
      if (nextIdx !== -1) lockReel(nextIdx);
      return;
    }
    if (game.funds < 10 && !s.rigged) {
      workGameCornerShift();
      return;
    }
    if (!s.rigged) game.funds -= 10;
    s.spinning = true;
    s.spins++;
    s.locked = [false, false, false];
    const now = performance.now();
    s.stopTimes = [now + 280, now + 540, now + 800];
    s.banner = 'REELS SPINNING... CLICK OR PRESS SPACE TO LOCK REELS!';
    updateUI();
  }

  function lockReel(idx) {
    const s = game.slots;
    if (s.locked[idx]) return;
    s.locked[idx] = true;
    if (s.rigged) {
      s.reels[idx] = 0;
    } else if (idx > 0 && Math.random() < 0.48) {
      s.reels[idx] = s.reels[0];
    } else {
      s.reels[idx] = rnd(0, SLOT_SYMBOLS.length - 1);
    }
    if (s.locked.every(Boolean)) finishSlotSpin();
  }

  function finishSlotSpin() {
    const s = game.slots;
    const biz = BIZ_UPGRADES[game.bizUpgradeIdx];
    s.spinning = false;
    const [r0, r1, r2] = s.reels;
    const sym0 = SLOT_SYMBOLS[r0];
    if (r0 === r1 && r1 === r2) {
      const winFunds = Math.round(sym0.payout * biz.slotMult);
      game.funds += winFunds;
      if (sym0.orb) game.orbs += sym0.orb;
      s.lastWin = winFunds;
      s.rigged = false;
      s.banner = `JACKPOT! 3× ${sym0.name}! WON +₽${winFunds}${sym0.orb ? ` & +1 ${currentRocketBallType().short}` : ''}!`;
      game.message = `Slot Jackpot at the Game Corner! Won +₽${winFunds} and +${sym0.merits} Merits!`;
      addMerits(sym0.merits, `Slot Jackpot (3× ${sym0.name})`);
    } else if (r0 === r1 || r1 === r2 || r0 === r2) {
      const pairSym = r0 === r1 ? SLOT_SYMBOLS[r0] : SLOT_SYMBOLS[r2];
      const winFunds = Math.round(90 * biz.slotMult);
      game.funds += winFunds;
      s.lastWin = winFunds;
      s.rigged = false;
      s.banner = `NICE MATCH! PAIR OF ${pairSym.name}S! WON +₽${winFunds} & +15 MERITS!`;
      game.message = `Matched a pair of ${pairSym.name}s on the Game Corner slots! +₽${winFunds}.`;
      addMerits(15, 'Game Corner Slot Match');
    } else {
      s.lastWin = 0;
      s.rigged = false;
      s.banner = 'NO MATCH! CLICK WORK/RIG (2) FOR GUARANTEED 3× R JACKPOT!';
      game.message = 'Reels missed! Tip: Work/Rig Slots for a guaranteed Jackpot!';
      updateUI();
    }
  }

  function workGameCornerShift() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const biz = BIZ_UPGRADES[game.bizUpgradeIdx];
    game.cornerShifts++;
    game.funds += biz.cornerPay;
    game.slots.rigged = true;
    game.slots.banner = `SHIFT WORKED (+₽${biz.cornerPay})! MAGNET RIGGED: SPIN FOR 3× R JACKPOT!`;
    game.message = `Grunt ${game.playerName} worked a Game Corner shift (+₽${biz.cornerPay}, +25 Merits) and rigged the slot reels!`;
    addMerits(25, 'Worked Game Corner Shift');
    if (game.mode !== 'slots') openGameCornerSlots();
  }

  function workDaycareShift() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const biz = BIZ_UPGRADES[game.bizUpgradeIdx];
    game.daycareShifts++;
    game.funds += biz.daycarePay;
    game.hp = game.maxHp;
    game.xp += biz.xpGain;
    let leveled = false;
    while (game.xp >= 24) {
      game.xp -= 24;
      game.level++;
      game.maxHp += 4;
      game.hp = game.maxHp;
      leveled = true;
    }
    const stName = game.starter ? game.starter.name : 'Starter';
    game.message = `Worked Daycare shift! Earned +₽${biz.daycarePay}, ${stName} healed${leveled ? ` & reached Lv.${game.level}` : ` (+${biz.xpGain} XP)`}!`;
    addMerits(25, 'Worked Daycare Shift');
  }

  function reportForPromotion() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const prevRank = game.rankIndex;
    const needed = RANKS[game.rankIndex].nextMerits - game.merits;
    const grant = Math.max(25, needed);
    game.talkedVex = true;
    addMerits(grant, 'Commander Vex Promotion');
    const newRankTitle = RANKS[game.rankIndex].title;
    if (game.rankIndex > prevRank) {
      game.message = `Commander Vex: “Promoted to ${newRankTitle}, ${game.playerName}! Unlocked Lv.${game.rankIndex + 1} Upgrades & Tournament Tier ${Math.min(5, game.rankIndex + 1)}!”`;
    } else {
      game.message = `Commander Vex: “You hold Top Rank (${newRankTitle}), ${game.playerName}! Victory Road & Advanced Management are yours!”`;
    }
    updateUI();
  }

  function move(dir) {
    if (game.mode !== 'map') return;
    const delta = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }[dir];
    if (!delta) return;
    game.facing = dir;
    const nx = game.x + delta[0], ny = game.y + delta[1];
    if (!solid(nx, ny)) {
      game.buddyTrail.unshift({ x: game.x, y: game.y });
      if (game.buddyTrail.length > 4) game.buddyTrail.pop();
      game.x = nx;
      game.y = ny;
      game.steps++;
      if (!game.bikeStolen && ny >= baseBounds.doorY) {
        stealRivalBike();
        return;
      }
      if (tileType(game.x, game.y) === 'tall' && game.grassEncounterCooldown <= 0 && Math.random() < 0.2) {
        game.grassEncounterCooldown = 6;
        beginWildBattle();
      }
      updateUI();
    } else {
      const hitNpc = npcAt(nx, ny);
      if (hitNpc) interactWithRole(hitNpc.role);
    }
  }

  function interactWithRole(role) {
    if (role === 'stealBike') stealRivalBike();
    else if (role === 'vex') reportForPromotion();
    else if (role === 'rocketRival') beginRivalBattle('rocket');
    else if (role === 'heroRival') beginRivalBattle('hero');
    else if (role === 'cornerBoss') openGameCornerSlots();
    else if (role === 'daycareKeeper') openDaycareAndLabs();
    else if (role === 'gymLeader') challengeKantoGym();
    else if (role === 'victoryGuard') openVictoryRoadAndEliteFour();
    else if (role === 'tall') beginWildBattle();
  }

  function interact() {
    if (game.mode === 'intro') {
      confirmIntroNames();
      return;
    }
    if (!game.bikeStolen) {
      stealRivalBike();
      return;
    }
    if (game.mode === 'slots') {
      startOrStopSlotSpin();
      return;
    }
    if (game.mode === 'daycare') {
      splicePartnerInFusionLab();
      return;
    }
    if (game.mode === 'victory') {
      startEliteFourBout();
      return;
    }
    if (game.mode === 'management') {
      runExecutiveManagementAction(0);
      return;
    }
    if (game.mode === 'battle') {
      if (game.battle?.phase === 'menu') attack('spark');
      else battleContinue();
      return;
    }
    const near = nearbyInteraction();
    if (near) {
      interactWithRole(near);
    } else {
      game.message = `Grunt ${game.playerName} (${RANKS[game.rankIndex].title}) rides ${game.heroRival}'s stolen bike with ${game.starter.name}.`;
      updateUI();
    }
  }

  function beginWildBattle() {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const base = creatures[rnd(0, creatures.length - 1)];
    const enemy = {
      ...base,
      level: rnd(3, Math.max(4, game.level)),
      maxHp: base.hp + rnd(0, 4)
    };
    enemy.hp = enemy.maxHp;
    game.mode = 'battle';
    game.battle = {
      trainer: null,
      rivalKind: null,
      enemy,
      phase: 'menu',
      message: `A wild ${enemy.name} jumped out! Throw a ${currentRocketBallType().name} to snatch it!`,
      turn: 0
    };
    game.message = game.battle.message;
    updateUI();
  }

  function beginRivalBattle(kind) {
    if (game.mode === 'intro') confirmIntroNames();
    ensureBikeStolen();
    const isRocket = kind === 'rocket';
    const trainerName = isRocket ? `ROCKET RIVAL ${game.rocketRival}` : `PROTAGONIST ${game.heroRival}`;
    const enemy = isRocket
      ? { name: 'KOFFING', kind: 'POISON', color: '#8d73b8', accent: '#553c7a', level: game.level, maxHp: 24, hp: 24 }
      : { name: 'PIKACHU', kind: 'ELECTRIC', color: '#f6cb49', accent: '#d98a2b', level: game.level, maxHp: 26, hp: 26 };
    game.mode = 'battle';
    game.battle = {
      trainer: trainerName,
      rivalKind: kind,
      enemy,
      phase: 'menu',
      message: isRocket
        ? `${game.rocketRival}: “You stole ${game.heroRival}'s bike AND got ${game.starter.name}?! That promotion is mine, ${game.playerName}!”`
        : `${game.heroRival}: “Grunt ${game.playerName}! Give back my stolen Bike and my ${game.starter.name} Poké Ball right now!”`,
      turn: 0
    };
    game.message = game.battle.message;
    updateUI();
  }

  function enemyTurn() {
    const b = game.battle;
    if (!b || game.mode !== 'battle') return;
    const damage = rnd(2, 5);
    game.hp = Math.max(1, game.hp - damage);
    b.phase = 'enemyMsg';
    b.message = `${b.enemy.name} counterattacked! ${game.starter.name} took −${damage} HP.`;
    game.message = b.message;
    updateUI();
  }

  function attack(kind) {
    const b = game.battle;
    if (!b || b.phase !== 'menu') return;
    const starter = game.starter || RED_STARTERS[1];
    const pUpg = PLAYER_UPGRADES[game.playerUpgradeIdx];
    const rBall = currentRocketBallType();

    if (kind === 'snack') {
      if (game.potions <= 0) {
        b.phase = 'enemyMsg';
        b.message = 'No Rations left in your Rocket kit!';
        return;
      }
      game.potions--;
      const healed = Math.min(18 + pUpg.lvl * 4, game.maxHp - game.hp);
      game.hp += healed;
      b.phase = 'enemyMsg';
      b.message = `${starter.name} ate a Rocket Ration! Restored +${healed || 1} HP.`;
      updateUI();
      return;
    }

    // Unique Team Rocket Poké Ball Stealing Mechanic (works on BOTH Trainer Pokémon & Wild Pokémon!)
    if (kind === 'orb') {
      if (game.orbs <= 0) {
        // Resupply 1 emergency R-Snatch Ball so the steal mechanic is always playable
        game.orbs = 1;
      }
      game.orbs--;
      b.phase = 'enemyMsg';
      b.pendingCapture = true;
      if (b.trainer) {
        b.message = `${game.playerName} threw a Team Rocket ${rBall.name} to STEAL ${b.trainer}'s ${b.enemy.name}! Override lock engaged!`;
      } else {
        b.message = `${game.playerName} threw a Team Rocket ${rBall.name} at wild ${b.enemy.name}!`;
      }
      game.message = b.message;
      updateUI();
      return;
    }

    const moveLabel = kind === 'spark'
      ? (game.fusionTier > 0 ? starter.fusedMove : starter.move1)
      : starter.move2;
    const damage = (kind === 'spark' ? rnd(12, 16) : rnd(8, 12)) + game.level + totalAttackBonus();
    b.enemy.hp = Math.max(0, b.enemy.hp - damage);
    b.turn++;
    if (b.enemy.hp <= 0) {
      completeBattleVictory(b, false);
    } else {
      b.phase = 'enemyMsg';
      b.message = `${starter.name} used ${moveLabel}! −${damage} HP to ${b.enemy.name}!`;
      b.pendingEnemy = true;
      updateUI();
    }
  }

  function completeBattleVictory(b, wasStolenWithRocketBall = false) {
    const starter = game.starter || RED_STARTERS[1];
    const rBall = currentRocketBallType();
    game.wins++;
    game.xp += 16;
    if (game.xp >= 24) {
      game.xp -= 24;
      game.level++;
      game.maxHp += 4;
      game.hp = game.maxHp;
    }
    if (wasStolenWithRocketBall) {
      game.caught++;
      game.stolenCount++;
      game.stolenPokemon.push(b.enemy.name);
      game.maxHp += rBall.bonusHp;
      game.hp = game.maxHp;
    }
    b.phase = 'winMsg';
    const stealPrefix = wasStolenWithRocketBall ? `STOLE ${b.enemy.name} with ${rBall.name}! ` : '';

    if (b.rivalKind === 'gym') {
      game.gymsControlled = Math.min(4, game.gymsControlled + 1);
      game.funds += b.gymObj.tribute;
      b.message = `${stealPrefix}Conquered ${b.gymObj.gymName}! Now under your Team Rocket control (${game.gymsControlled}/4 Gyms)! +₽${b.gymObj.tribute}!`;
      game.message = b.message;
      addMerits(b.gymObj.merits, `${stealPrefix}${b.gymObj.gymName} Controlled (${game.gymsControlled}/4)!`);
    } else if (b.rivalKind === 'tournament') {
      game.tourneyCleared = Math.max(game.tourneyCleared, b.tourneyTier);
      game.funds += b.prize;
      b.message = `${stealPrefix}Won Underground Tournament Tier ${b.tourneyTier}! +₽${b.prize} & +${b.merits} Merits!`;
      game.message = b.message;
      addMerits(b.merits, `${stealPrefix}Won Fight Pit Tier ${b.tourneyTier}!`);
    } else if (b.rivalKind === 'elite4') {
      game.eliteFourCleared = Math.max(game.eliteFourCleared, b.e4Stage);
      game.funds += b.prize;
      b.message = `${stealPrefix}Defeated ${b.trainer} on Victory Road (${game.eliteFourCleared}/4 Elite 4)! +₽${b.prize}!`;
      game.message = b.message;
      addMerits(50, `${stealPrefix}Conquered ${b.trainer} (${game.eliteFourCleared}/4)!`);
    } else if (b.rivalKind === 'rocket') {
      game.defeatedRocketRival = true;
      game.funds += 150;
      b.message = `${stealPrefix}Defeated Rocket Rival ${game.rocketRival} with ${starter.name}! +₽150 & +40 Merits!`;
      game.message = b.message;
      addMerits(40, `${stealPrefix}Defeated Rocket Rival ${game.rocketRival}`);
    } else if (b.rivalKind === 'hero') {
      game.defeatedHeroRival = true;
      game.funds += 150;
      b.message = `${stealPrefix}Defeated Protagonist ${game.heroRival} and kept his stolen bike! +₽150 & +40 Merits!`;
      game.message = b.message;
      addMerits(40, `${stealPrefix}Defeated Protagonist ${game.heroRival}`);
    } else {
      game.funds += 90;
      b.message = `${stealPrefix}Captured ${b.enemy.name}! Earned +₽90 & +35 Merits!`;
      game.message = b.message;
      addMerits(35, `${stealPrefix}Captured ${b.enemy.name}`);
    }
    updateUI();
  }

  function battleContinue() {
    const b = game.battle;
    if (!b) return;
    if (b.phase === 'intro') {
      b.phase = 'menu';
      return;
    }
    if (b.phase === 'enemyMsg') {
      if (b.pendingCapture) {
        b.pendingCapture = false;
        completeBattleVictory(b, true);
        const wasTourney = b.rivalKind === 'tournament';
        const wasE4 = b.rivalKind === 'elite4';
        game.battle = null;
        game.grassEncounterCooldown = 7;
        game.mode = wasTourney ? 'slots' : wasE4 ? 'victory' : 'map';
        updateUI();
        return;
      }
      if (b.pendingEnemy) {
        b.pendingEnemy = false;
        enemyTurn();
        return;
      }
      b.phase = 'menu';
      return;
    }
    if (b.phase === 'winMsg') {
      const wasTourney = b.rivalKind === 'tournament';
      const wasE4 = b.rivalKind === 'elite4';
      game.battle = null;
      game.grassEncounterCooldown = 7;
      game.mode = wasTourney ? 'slots' : wasE4 ? 'victory' : 'map';
      updateUI();
    }
  }

  function keyDown(e) {
    if (document.activeElement && document.activeElement.tagName === 'INPUT') {
      if (e.key === 'Enter') confirmIntroNames(e);
      return;
    }

    const key = e.key.toLowerCase();
    if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' ', 'enter'].includes(key)) {
      e.preventDefault();
    }
    if (game.keys[key]) return;
    game.keys[key] = true;

    if (game.mode === 'intro') {
      if (key === 'enter' || key === ' ') confirmIntroNames(e);
      return;
    }

    if (game.mode === 'slots') {
      if (key === '1' || key === ' ' || key === 'enter') startOrStopSlotSpin();
      else if (key === '2' || key === 'r') workGameCornerShift();
      else if (key === '3' || key === 't') startUndergroundTournamentBout();
      else if (key === '4' || key === 'escape') { game.mode = 'map'; updateUI(); }
      return;
    }

    if (game.mode === 'daycare') {
      if (key === '1') workDaycareShift();
      else if (key === '2') breedEggInUndergroundLab();
      else if (key === '3' || key === ' ' || key === 'enter') splicePartnerInFusionLab();
      else if (key === '4' || key === 'escape') { game.mode = 'map'; updateUI(); }
      return;
    }

    if (game.mode === 'victory') {
      if (key === '1' || key === '2' || key === ' ' || key === 'enter') startEliteFourBout();
      else if (key === '3') openExecutiveManagement();
      else if (key === '4' || key === 'escape') { game.mode = 'map'; updateUI(); }
      return;
    }

    if (game.mode === 'management') {
      if (key === '1') runExecutiveManagementAction(0);
      else if (key === '2') runExecutiveManagementAction(1);
      else if (key === '3') runExecutiveManagementAction(2);
      else if (key === '4' || key === 'escape') runExecutiveManagementAction(3);
      return;
    }

    if (game.mode === 'battle') {
      if (game.battle?.phase === 'menu') {
        if (key === '1' || key === 'z' || key === ' ' || key === 'enter') attack('spark');
        else if (key === '2' || key === 'x') attack('tail');
        else if (key === '3') attack('snack');
        else if (key === '4') attack('orb');
      } else if (key === ' ' || key === 'enter' || key === 'z') {
        battleContinue();
      }
      return;
    }

    if (key === 'b') {
      if (!game.bikeStolen) stealRivalBike();
      else {
        game.ridingBike = !game.ridingBike;
        showToast(game.ridingBike ? `Riding ${game.heroRival}'s stolen bike!` : 'Walking mode');
        updateUI();
      }
      return;
    }
    if (key === 'g') { openGameCornerSlots(); return; }
    if (key === 'c') { openDaycareAndLabs(); return; }
    if (key === 'm') { challengeKantoGym(); return; }
    if (key === 'v') { openVictoryRoadAndEliteFour(); return; }
    if (key === 'p') { reportForPromotion(); return; }

    const dirs = {
      arrowup: 'up', w: 'up',
      arrowdown: 'down', s: 'down',
      arrowleft: 'left', a: 'left',
      arrowright: 'right', d: 'right'
    };
    if (dirs[key]) move(dirs[key]);
    else if (key === ' ' || key === 'enter' || key === 'z') interact();
  }

  function keyUp(e) {
    game.keys[e.key.toLowerCase()] = false;
  }

  window.addEventListener('keydown', keyDown);
  window.addEventListener('keyup', keyUp);

  document.querySelectorAll('.preset-list').forEach(group => {
    const targetId = group.dataset.target;
    const inputEl = $(targetId);
    group.querySelectorAll('.name-preset-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        group.querySelectorAll('.name-preset-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        inputEl.value = btn.dataset.name;
        game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
        game.rocketRival = sanitizeName(ui.rocketRivalInput.value, 'VIPER');
        game.heroRival = sanitizeName(ui.heroRivalInput.value, 'RED');
        updateUI();
      });
    });
  });

  [ui.playerInput, ui.rocketRivalInput, ui.heroRivalInput].forEach(inp => {
    inp.addEventListener('input', () => {
      game.playerName = sanitizeName(ui.playerInput.value, 'JESS');
      game.rocketRival = sanitizeName(ui.rocketRivalInput.value, 'VIPER');
      game.heroRival = sanitizeName(ui.heroRivalInput.value, 'RED');
      updateUI();
    });
  });

  ui.introForm.addEventListener('submit', confirmIntroNames);
  $('rename-toggle').addEventListener('click', openIntroModal);
  if (ui.bikeToggle) {
    ui.bikeToggle.addEventListener('click', () => {
      if (game.mode === 'intro') confirmIntroNames();
      else if (!game.bikeStolen) stealRivalBike();
      else {
        game.ridingBike = !game.ridingBike;
        showToast(game.ridingBike ? `Riding ${game.heroRival}'s stolen bike!` : 'Walking with stolen bike.');
        updateUI();
      }
    });
  }

  if (ui.btnUpgradePlayer) ui.btnUpgradePlayer.addEventListener('click', () => buyTrackUpgrade('player'));
  if (ui.btnUpgradeBase) ui.btnUpgradeBase.addEventListener('click', () => buyTrackUpgrade('base'));
  if (ui.btnUpgradeBiz) ui.btnUpgradeBiz.addEventListener('click', () => buyTrackUpgrade('biz'));
