    else if (game.mode === 'daycare') ui.action.textContent = 'SPLICE DNA (EXP)';
    else if (game.mode === 'management') ui.action.textContent = 'RUN EXEC OPS';
    else ui.action.textContent = 'INTERACT / TALK';
