  await page.waitForTimeout(150);

  // 3. Test Daycare & Underground Breeding + Infinite Exponential Splicing Labs via Buttons
  await page.click("#btn-breed-lab");
  await page.waitForTimeout(100);
  await page.click("#btn-fusion-lab");
