  // 4. Test Gym Takeover & Stealing Gym Leader Pokemon with Unique Team Rocket R-Ball
  await page.click("#gym-battle-button");
  await page.waitForTimeout(100);
  await page.click("#btn-catch-wild"); // Steals Brock Onix & puts Pewter Gym under Team Rocket control!
  await page.waitForTimeout(150);

  // 5. Test Player, Base & Business Upgrades + Top Rank Promotion + Executive Management
  await page.click("#btn-upgrade-player");
  await page.click("#btn-upgrade-base");
  await page.click("#btn-upgrade-biz");
  await page.click("#rank-up-button");
  await page.waitForTimeout(100);
  await page.click("#btn-exec-mgmt");
  await page.waitForTimeout(100);
  await page.click("#action-button");
  await page.waitForTimeout(100);
  await page.click("#btn-return-map");
  await page.waitForTimeout(200);

  if (errors.length > 0) {
    console.error("Browser Errors:", errors);
    process.exit(1);
  }

  fs.mkdirSync("screenshots", { recursive: true });
  await page.screenshot({ path: "screenshots/latest.jpg", type: "jpeg", quality: 82 });
  await browser.close();
  console.log("Playwright verification and screenshot succeeded with 0 errors.");
})();
'

